window.__D("text/torat-shmuel/c049",{"p":[[2000480309,"את היו\"ד מהעלם אל הגילוי, מההעלם העצמי (שנשאר בהעלם), וזה קאי על מצות שהם ממשיכים את האור דתורה.\n<b>והנה</b> כלליות המצות נק' בשם צדקה וכמ\"ש וצדקה תהי' לנו<sup data-n=\"2862\">100</sup> כי נשמור לעשות כל המצוה הזאת דכמו הצדקה למטה הוא להחיות רוח שפלים<sup data-n=\"2863\">101</sup> דהעני הוא שפל ונבזה בעיני עצמו ועומד אצל פתח הבית, כמו\"כ כלליות עולמות העליונים עולמות הא\"ס הם שפלים ודלים לגבי הקב\"ה ולכן אני הוי' לא שניתי<sup data-n=\"2864\">102</sup> שלא יש שום שנוי בין קודם הבריאה לאחר הבריאה אתה הוא קודם שנבה\"ע<sup data-n=\"2865\">103</sup> ואתה הוא לאחר שנברה\"ע דכלליות השתל' העולמות הוא רק משם והארה בעלמא שאינו נוגע לעצמיות, דהארה אינו שייך שיפעול שינוי בהעצם, וא\"כ כמו העני הוא דך ושפל כמו\"כ העולמות הם דכים ושפלים לגבי א\"ס ומה שע\"י ממשיכים<sup data-n=\"2866\">104</sup> המשכות אלקות כמו ע\"י תפלין ד' מוחין<sup data-n=\"2867\">105</sup> וכדומה ה\"ז צדקה לכן נק' המצות בשם צדקה, וגבי צדקה כתי' משפט וצדקה ביעקב אתה עשית<sup data-n=\"2868\">106</sup> שהצדקה צ\"ל במשפט, דכשיטול לעצמו על כל התענוגים והמותר יתן לענים הגם שהוא צדקה אך א\"ז במשפט, דמה שארז\"ל חייך קודמים<sup data-n=\"2869\">107</sup> היינו דוקא כעין מעשה שהי', שהי' רק קתון ולא יספיק לשניהם אז חייך קודמים, אבל לא שהוא יתענג בכל התענוגי' בתפנוקי עוה\"ז והעני ימות ברעב ח\"ו א\"ז יושר, הגם שנתנו לו (העשירות) אך זהו הבחנה שבוחנין אותו, וזהו שארז\"ל גלגל החוזר הוא בעולם<sup data-n=\"2870\">108</sup> והכל רק הבחנה ולפעמים מבחינים לזה כו', וע\"י המשפט בצדקה ממשיך בחי' את\"ה עשית אתה הוא גילוי<sup data-n=\"2871\">109</sup> וכמו שאומרי' לנוכח אתה, והיינו שיומשך גילוי אלקות בעולמות עליונים למטה<sup data-n=\"2872\">110</sup> יומשך מזה השפעה גשמיות וכמ\"ש אם בחקתי תלכו<sup data-n=\"2873\">111</sup> ונתתי גשמיכם בעתו<sup data-n=\"2874\">112</sup> שיומשך השפעה גשמיות דכל גשמיות אין שרשו מגשמיות אלא בשרשו הוא רוחניות ולמטה נמשך מזה גשמיות וכמארז\"ל כל אורה האמור באליהו בן ברכאל<sup data-n=\"2875\">113</sup> בירידות גשמים הכתוב מדבר ומ\"מ הוא אור",[["2862","100","<b>כלליות המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה [בדילוג]. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 27."],["2863","101","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם."],["2864","102","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 82."],["2865","103","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["2866","104","<b>שע\"י ממשיכים</b>: אוצ\"ל: שע\"י מצות ממשיכים."],["2867","105","<b>תפלין ד' מוחין</b>: ראה זהר ואתחנן רסב, א. סידור שער התפילין ז, א. אמרי בינה שער התפילין קיב, א ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ."],["2868","106","<b>משפט וצדקה ביעקב אתה עשית</b>: תהלים צט, ד. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 31."],["2869","107","<b>חייך קודמים</b>: ב\"מ סב, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1395."],["2870","108","<b>גלגל החוזר הוא בעולם</b>: ראה שבת קנא, ב."],["2871","109","<b>אתה הוא גילוי</b>: ראה גם (בחלק המאמרים) בהמאמר כאן ובהערה 32."],["2872","110","<b>למטה</b>: אוצ\"ל: ולמטה."],["2873","111","<b>אם בחקתי תלכו</b>: בחוקותי כו, ג."],["2874","112","<b>ונתתי גשמיכם בעתו</b>: בחוקותי שם, ד [ושם: בעתם — ראה גם סה\"מ תרל\"ח ס\"ע תקיח]."],["2875","113","<b>כל אורה האמור באליהו בן ברכאל</b>: בב\"ר ספכ\"ו: כל אורה שנאמר באליהוא אינה אלא בירידת גשמים. ראה סה\"מ תרל\"ח ע' קס. וש\"נ. לקמן הנחה ד\"ה כנשר יעיר קנו על יד הערה 60. ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 46. (בחלק ההנחות) הנחה ד\"ה כנשר יעיר קנו על יד הערה 61."]]],[2000480310,"דענין גשם הוא כמ\"ש והי' אור הלבנה כאור חמה<sup data-n=\"2876\">114</sup> ואור החמה יהי' שבעתיים כאור שבעת הימים ופרש\"י<sup data-n=\"2877\">115</sup> זפ\"ז מ\"ט ז\"פ מ\"ט עולה שמ\"ג גש\"ם, והנה אור שבעת הימים הם ז\"ת דעתיקא<sup data-n=\"2878\">116</sup> ושבעתיים כאור שבעת הימים הוא גשם למעלה ומ\"מ הוא אור רק כשנשפל למטה נעשה גשם, וזהו אם בחקתי תלכו ונתתי גשמיכם ר\"ל גשם שלכם והיינו שיושפע השפעות גשמיות למטה.\n<b>ועוי\"ל</b> פי' אתה עשית, דהנה אף שנת\"ל שצדקה צריך להיות במשפט וא\"כ ה\"ז אתכפייא וכן שארי המצות, שלא יאמר אדם עכשיו איני יכול לעשות המצוה או מצוה זו אין ביכולתי לעשות, הנה אם האמת כ\"ה שנוגע לו לחיי נפשו ממש הרי כתי' אשר יעשה אותם האדם<sup data-n=\"2879\">117</sup> וחי בהם ולא שימות בהם אבל כל שלא הגיע למדרי' זו הרי המצוה קדום (ה' ויש מצות שעליהם ארז\"ל יהרג ואל יעבור ובשעת כו' אפי' ערקתא דמסאנא<sup data-n=\"2880\">118</sup> כו' א\"כ הרי נוגע לו בחיי נפשו ממש וממית נפשו עליהם, ואין לך אתכפיי' גדולה מזו ע') וה\"ז אתכפייא, מ\"מ כ\"ז לגבי האדם ה\"ז אתכפי' אבל לגבי הקב\"ה שכל העולם אינו תופס מקום כלל מה תופס מקום האדם עם האתכפי' שלו, עז\"א את\"ה עשית שכך עלה ברצונו שיהי' מצוה והאתכפי' יחשב לכפי' ועי\"ז יומשך בחי' אתה הוא גילוי אלקות. וזהו כל האומר אין לי כו' אלא תורה וגמ\"ח שע\"י המצות ממשיכים בחי' ותורה אור (דכל המצות הם העלאה<sup data-n=\"2881\">119</sup> ואפי' מצות שהם המשכות<sup data-n=\"2882\">120</sup> מ\"מ ה\"ה מעלה את הדבר גשמי וכמו עד\"מ ע\"י מצות תפילין ממשיכים ד' מוחין, אך ע\"י המצוה מעלים הקלף וממה שעושים הבתים והדיו, וכמו\"כ כללות המצות, וע\"י ההעלאה ממשיכים בחי' ותורה אור).\n<b>וביאור</b> הענין<sup data-n=\"2883\">121</sup> הנה יסוד<sup data-n=\"2884\">123</sup> הרוח שהוא האויר הוא למטה מיסוד האש<sup data-n=\"2885\">122</sup> דיסוד האש הוא תחת גלגל הירח<sup data-n=\"2886\">124</sup>, ומ\"מ במעלה הוא גובה<sup data-n=\"2887\">125</sup> מיסוד",[["2876","114","<b>והי' אור הלבנה כאור חמה</b>: ישעי' ל, כו [ושם: החמה]."],["2877","115","<b>ופרש\"י</b>: ראה ישעי' שם. סה\"מ תרל\"ח שם. וש\"נ. לקמן בג' ההנחות הנ\"ל בהערה 113."],["2878","116","<b>אור שבעת הימים הם ז\"ת דעתיקא</b>: ראה סידור שער חהמ\"צ רצא, ד."],["2879","117","<b>אשר יעשה אותם האדם</b>: אחרי יח, ה. יומא פה, ב."],["2880","118","<b>מצות. . יהרג ואל יעבור. . ערקתא דמסאנא</b>: ראה סנהדרין עד, א."],["2881","119","<b>דכל המצות הם העלאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו\"א מקץ לח, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370189\" data-slug=\"torah-or\" data-id=\"3901370189\">מב, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">מג, א</a> ואילך."],["2882","120","<b>מצות שהם המשכות</b>: ראה גם לעיל בפנים על יד הערה 105. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1697."],["2883","121","<b>וביאור הענין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370194\" data-slug=\"torah-or\" data-id=\"3901370194\">תו\"א מקץ מג, ב</a>. סידור שער החנוכה רעג, ג ואילך."],["2884","123","<b>יסוד הרוח. . למטה מיסוד האש. . גבוה מיסוד האש</b>: ראה גם (בנוסף להערה 121) אוה\"ת שבהערה 95 ע' תקיט. (לעיל בחלק המאמרים) בהמאמר כאן רפ\"ב."],["2885","122","<b>יסוד הרוח. . למטה מיסוד האש</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ג, ה\"ד. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1005."],["2886","124","<b>דיסוד האש הוא תחת גלגל הירח</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט</a> בשם הע\"ח. מהדו\"ק שם ע' קלב הערה 5. המשך תער\"ב ח\"ג ע' א'שכט מספורנו בראשית א, ב. לקו\"ב לשער היחוד קסט, ד בשם פלוסופים הראשונים. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370432\" data-slug=\"torah-or\" data-id=\"3901370432\">תו\"א מג\"א צו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">צז, א</a>."],["2887","125","<b>גובה</b>: אוצ\"ל: גבוה."]]],[2000480311,"האש ולכן הוא פועל באש לנפחו ולפעמים יתגבר עליו ויכבה אותו וידוע דפועל ונפעל הפועל חזק מהנפעל, וא\"כ איך אפשר שיהיו שניהם למטה וגם למעלה ממנו. והענין דהנה כתי' גבי יעקב כשבא למקום המקדש א' מה נורא המקום הזה<sup data-n=\"2888\">126</sup> לית דין אתר הדיוט<sup data-n=\"2889\">127</sup>, ובנוסח התפלה אומרים ג\"כ האל הגדול הגבור והנורא<sup data-n=\"2890\">128</sup> ת\"ת מדתו של יעקב<sup data-n=\"2891\">129</sup>, וצ\"ל דלכאורה והנורא<sup data-n=\"2892\">130</sup> שייך ליצחק שהוא גבורה<sup data-n=\"2893\">131</sup> מדת הפחד<sup data-n=\"2894\">132</sup>, אך הנה יעקב הוא בריח התיכון<sup data-n=\"2895\">133</sup> המבריח מן הקצה אל הקצה ומחבר חו\"ג<sup data-n=\"2896\">134</sup> וכלול בו יראה ג\"כ לכן והנורא קאי על יעקב, ובסדר הספי' ת\"ת הוא למטה מחו\"ג, אבל באמת ת\"ת עולה עד הכתר<sup data-n=\"2897\">135</sup> וזהו והנורא בוא\"ו שרשו בכתר<sup data-n=\"2898\">136</sup>, וכמו\"כ יובן באויר דאויר הוא אור יו\"ד, יו\"ד יש השכלות הי' וכמו עשה הוא ל' עבר יעשה ל' הוה והשנוי הוא מצד אות יו\"ד, ויש עצם אות היו\"ד<sup data-n=\"2899\">137</sup> שמוציא ההשכלה מכח אל הפועל מהעלם העצמי והוא למעלה מההשכלה דיו\"ד דכל פועל ונפעל הפועל חזק מהנפעל, ואויר שהוא אור י' הוא המקור של הי'<sup data-n=\"2900\">138</sup> (ה' ר\"ל אור הוא המקור של היו\"ד וזהו אויר כי ואויר<sup data-n=\"2901\">139</sup> ואור הכל א' כנ\"ל ע') וכמו אנת הוא חכים<sup data-n=\"2902\">140</sup>, חכים הוא חכ' הגלוי' והגם דא' ולא בחכ' ידיעה ר\"ל שאינו ידוע לגמרי אבל מ\"מ נק' בשם חכים וא\"כ ה\"ז פועל יוצא אף דלמעלה אין לך דבר שחוץ ממנו והוא וחכמתו א'<sup data-n=\"2903\">141</sup>, אבל כמו\"ש<sup data-n=\"2904\">142</sup> למטה ה\"ז פועל יוצא, וא' אנת הוא חכים הרי יש בחי'",[["2888","126","<b>מה נורא המקום הזה</b>: ויצא כח, יז. ראה בהבא לקמן תו\"א וסידור שבהערה 121. אוה\"ת שבהערה 95."],["2889","127","<b>לית דין אתר הדיוט</b>: ת\"א ויצא שם."],["2890","128","<b>האל הגדול הגבור והנורא</b>: תפלת שמו\"ע. ראה (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 39."],["2891","129","<b>ת\"ת מדתו של יעקב</b>: ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג תוספות שב, א. פרדס שער הכנויים שכ\"ב, פ\"ד. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 16."],["2892","130","<b>דלכאורה והנורא. . גבורה</b>: ראה גם פרדס שער עה\"כ שכ\"ג, פי\"ד ערך נורא. ראה גם אוה\"ת (יהל אור) תהלים ע' תקנג."],["2893","131","<b>ליצחק שהוא גבורה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["2894","132","<b>גבורה מדת הפחד</b>: ראה ס' הבהיר סק\"צ. פרדס שער עה\"כ שכ\"ג, פי\"ז מערכת פחד. מאו\"א מערכת פחד סל\"ט וביאיר נתיב שם."],["2895","133","<b>יעקב הוא בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["2896","134","<b>יעקב. . ומחבר חו\"ג</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול בתחילתו. וש\"נ."],["2897","135","<b>ת\"ת עולה עד הכתר</b>: ראה שערי אורה לר\"י גיקטלייא שער ה (סג, ב). מאמרי אדה\"ז הקצרים ע' תקעט."],["2898","136","<b>והנורא בוא\"ו שרשו בכתר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370107\" data-slug=\"torah-or\" data-id=\"3901370107\">תו\"א ויצא כג, א</a>. אוה\"ת ענינים ע' קעב<sup data-n=\"e247\">ו</sup>."],["2899","137","<b>יו\"ד יש השכלות הי'. . עצם אות היו\"ד</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 53."],["2900","138","<b>ואויר שהוא אור יו\"ד הוא המקור של הי'</b>: ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 22."],["2901","139","<b>ואויר</b>: אוצ\"ל: אויר."],["2902","140","<b>אנת הוא חכים</b>: ראה ת\"ז בהקדמה יז, ב. (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 23."],["2903","141","<b>והוא וחכמתו א'</b>: פרדס שער מהות והנהגה ש\"ח, פט\"ו. תניא פ\"ב."],["2904","142","<b>כמו\"ש</b>: כמו שהוא — אולי כ\"ה בגוכתי\"ק.\n\n<b>ו</b>  נדפס גם במאמרי אדה\"ז תקס\"ז ע' תלג."]]],[2000480312,"שהוא גורם שיהי' בחי' חכים, וכמו\"כ יובן בענין אור יו\"ד דהאור הוא מקור היו\"ד, יו\"ד הוא השכלות התורה וחכ' ואותיותי' והאור הם המצות הממשיכים את האור, וזהו יעקב חבל נחלתו ולכאו' תי' חבל מיותר והול\"ל יעקב נחלתו, אלא כמו החבל שראשו א' קשור למעלה<sup data-n=\"2905\">143</sup> והב' למטה כשמנענעים בקצה התחתון מתנענע קצה העליון, כמו\"כ המצות הם מצות המלך<sup data-n=\"2906\">144</sup> הוא בחי' מל' אבל שרשם תרי\"ג מצות<sup data-n=\"2907\">146</sup>, הם תרי\"ג ארחין<sup data-n=\"2908\">147</sup> דגלגלתא<sup data-n=\"2909\">145</sup> ותרי\"ג מצות דאורייתא וז\"מ<sup data-n=\"2910\">149</sup> דרבנן הם תר\"ך<sup data-n=\"2911\">148</sup> עמודי אור<sup data-n=\"2912\">150</sup>, וענין עמודי או\"ר הוא אור יו\"ד מקור של היו\"ד. וזהו כי נר מצוה ותורה אור הקדים מצוה לתורה אף דתורה הוא אור ומצות נר, מ\"מ מעלת הנר שצריכה אויר, ואויר הוא אור יו\"ד שהוא המקור של תורה והוא הממשיך בחי' אור תורה.\n<b>והנה</b> הרמב\"ם כ' שהרוח (והוא האור שנת' כאן) הוא הכוונה והרצון<sup data-n=\"2913\">151</sup> וכמו כל רוחו יוצא כסיל<sup data-n=\"2914\">152</sup> שר\"ל הפנימיות, וכן ונבקע רוח מצרים<sup data-n=\"2915\">153</sup> ופרש\"י<sup data-n=\"2916\">154</sup> נתרוקנה חכמתם, וכן מי תכן את רוח ה'<sup data-n=\"2917\">155</sup> מי יודע את סדר רצונו (לרא\"ח<sup data-n=\"2918\">156</sup> הכוונה בזה שהמצות הם עצם הרצה\"ע ולא שלוחי הרצה\"ע) ועפ\"ז יובן מ\"ש בזהר שהכנפים הם להנף<sup data-n=\"2919\">157</sup> על הלב להשקיט את חום הלב (לרא\"ח זה ית' לקמן אי\"ה איך שמובן מזה), וביאור<sup data-n=\"2920\">158</sup> (פ' תרומה ביאור מי יתנך<sup data-n=\"2921\">159</sup> ) דהנה כתי'",[["2905","143","<b>יעקב חבל נחלתו. . החבל שראשו א' קשור למעלה</b>: האזינו לב, ט. ראה גם (לעיל בחלק המאמרים) בהמאמר כאן ובהערה 58."],["2906","144","<b>המצות הם מצות המלך</b>: ראה אסתר ג, ג. מאמרי אדה\"א שמות ח\"א ע' יא. וש\"נ. נ\"ך ע' רלה. ש\"א ע' נו."],["2907","146","<b>תרי\"ג מצות</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות הערה 80."],["2908","147","<b>תרי\"ג מצות. . ארחין דגלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו הערה 56."],["2909","145","<b>המצות. . מל'. . דגלגלתא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380376\" data-slug=\"likkutei-torah\" data-id=\"4001380376\">לקו\"ת במדבר יז, א</a> (ובהנסמן בריש המאמר שם). סה\"מ תרל\"ח ח\"ב ע' שכב. וש\"נ."],["2910","149","<b>וז\"מ דרבנן</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות הערות 82-83."],["2911","148","<b>ותרי\"ג. . וז\"מ. . תר\"ך</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["2912","150","<b>תר\"ך עמודי אור</b>: ראה לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670571\" data-slug=\"torat-chaim\" data-id=\"2300670571\">תו\"ח בראשית מה, ג</a> הערה 32."],["2913","151","<b>הרמב\"ם כ' שהרוח. . הכוונה והרצון</b>: ראה מו\"נ ח\"א פ\"מ."],["2914","152","<b>כל רוחו יוצא כסיל</b>: משלי כט, יא [ושם: יוציא — ראה גם (לעיל בחלק המאמרים) בהמאמר כאן הערה 69]."],["2915","153","<b>ונבקע רוח מצרים</b>: ישעי' יט, ג [ושם: ונבקה]."],["2916","154","<b>ופרש\"י</b>: ישעי' שם (בשינוי קל)."],["2917","155","<b>מי תכן את רוח ה'</b>: ישעי' מ, יג."],["2918","156","<b>לרא\"ח</b>: וכן מובא עוה\"פ בסמוך בפנים — אולי הכוונה להרב החסיד ר' אהרן ז\"ל זעליגסאהן, ונקרא בשם ר' אהרן חוזר. ראה גם סה\"מ תרל\"ח ע' תו. וש\"נ."],["2919","157","<b>להנף</b>: לעיל בפנים על יד הערה 14 נרשם: להניף."],["2920","158","<b>וביאור</b>: אוצ\"ל: וביאור הענין."],["2921","159","<b>(פ' תרומה ביאור מי יתנך)</b>: כ\"ז נרשם עה\"ג<sup data-n=\"e248\">ז</sup> בצד הימני של העמוד, בסמיכות להתיבות שהובאו בפנים, בלי חצ\"ע. והכוונה שלהבא להלן לעיין בתו\"א תרומה פא, ב.\n\n<b>ז</b>  ראה גם לעיל על יד הערה 93."]]],[2000480313,"והכרובים פורשים כנפים למעלה<sup data-n=\"2922\">160</sup> סוככים בכנפיהם אל<sup data-n=\"2923\">161</sup> הכפורת ופירש רבינו ז\"ל כרובים הוא כשכתר א' לשניהם<sup data-n=\"2924\">162</sup>, והארון הוא יסו\"א<sup data-n=\"2925\">163</sup> שנשפל למטה בעשי' והכרובים הם סוככים בכנפיהם כי<sup data-n=\"2926\">164</sup> לעלות את הארון והלוחות מבי\"ע לאצי', וזמן ההעלאה<sup data-n=\"2927\">165</sup> הוא ג\"פ ביום וכמ\"ש בזהר ג' זמנין<sup data-n=\"2928\">166</sup> ביומא מגרמייהו סלקא, ופי' הרמ\"ז שהם נגד ג' תפילות היום, ולכאו' מה שייך זה לתפלה, והענין דהנה בעת התפלה האדם נתעורר באהוי\"ר לכן אז זמן ההעלאה. וזהו עולת שבת בשבתו על עולת התמיד<sup data-n=\"2929\">167</sup>, עולת שבת הוא דששת ימי החול מתעלים בשבת<sup data-n=\"2930\">168</sup> ע\"י עולת התמיד הוא דבתמיד השחר ושל בין הערבים וכנגדם עכשיו התפלה<sup data-n=\"2931\">169</sup> מתעלה בירורי' של כל היום<sup data-n=\"2932\">171</sup>, ואז מתעלים<sup data-n=\"2933\">172</sup> המצות<sup data-n=\"2934\">170</sup> ג\"כ דאהוי\"ר הוא מקור רמ\"ח מ\"ע ושס\"ה<sup data-n=\"2935\">173</sup> מל\"ת<sup data-n=\"2936\">174</sup> וכשמתעורר בעצם אהוי\"ר שהוא המקור של המצות ממילא מתעלים המצות ג\"כ, ובאמת הנה ארז\"ל שהם שלוחים (ה' מובן מהכתב<sup data-n=\"2937\">176</sup> דהיינו שיש במצות ג\"כ כח זה שבתפלה) דאי' במד' היו מכבדים את המצות<sup data-n=\"2938\">175</sup> שהם שלוחי ושלוחו של אדם כמותו, היינו שע\"י נמשך הרצה\"ע למטה והשליח צריך להביא בחזרה ג\"כ היינו שמעלה הדבר גשמי וכמו עד\"מ אתרוג כשאוכל אותו מי שהוא אינו מברך עליו אינו מעלה אותו רק מצומח למדבר<sup data-n=\"2939\">178</sup> ואף זאת רק מי",[["2922","160","<b>והכרובים פורשים כנפים למעלה</b>: וכ\"ה במאמרי אדה\"א דברים ח\"א ע' רסד<sup data-n=\"e249\">ח</sup> [ושם: פורשי]. קונטרסים ריש ע' שסג. תרומה כה, כ [ושם: והיו הכרובים]. ויקהל לז, ט [ושם: ויהיו הכרובים]."],["2923","161","<b>אל</b>: שם: על."],["2924","162","<b>כרובים. . כשכתר א' לשניהם</b>: ראה תו\"א כאן. אוה\"ת תרומה ע' א'תנ."],["2925","163","<b>והארון הוא יסו\"א</b>: ראה ע\"ח שער הארת המוחין זו\"ן של\"ב, פ\"ח. לקו\"ת להאריז\"ל תרומה כה, י. מאו\"א מערכת ארון סקכ\"א."],["2926","164","<b>כי</b>: אולי כתוב: כו'."],["2927","165","<b>וזמן ההעלאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370355\" data-slug=\"torah-or\" data-id=\"3901370355\">תו\"א תרומה עט, ד</a>."],["2928","166","<b>בזהר ג' זמנין</b>: אחרי נט, א. ויחי רכח, סע\"ב."],["2929","167","<b>עולת שבת. . עולת התמיד</b>: פינחס כח, י."],["2930","168","<b>דששת ימי החול מתעלים בשבת</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370357\" data-slug=\"torah-or\" data-id=\"3901370357\">תו\"א תרומה פ, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. (לעיל בחלק המאמרים) המשך יונתי ספכ\"ב."],["2931","169","<b>דבתמיד השחר. . הערבים וכנגדם עכשיו התפלה</b>: ברכות כו, ב."],["2932","171","<b>התפלה מתעלה בירורי' של כל היום</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540674\" data-slug=\"torat-chaim\" data-id=\"2300540674\">תו\"ח בא ח\"א צד, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550883\" data-slug=\"torat-chaim\" data-id=\"2300550883\">ויקהל ח\"ב תלז, ד</a>."],["2933","172","<b>התפלה. . מתעלים המצות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. פלח הרמון בהר ע' שצב. וש\"נ."],["2934","170","<b>דבתמיד השחר. . הערבים. . מתעלים המצות</b>: ראה גם פלח הרמון בהר ע' תיז."],["2935","173","<b>דאהוי\"ר. . רמ\"ח מ\"ע ושס\"ה מל\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא</a> פ\"ד ובמ\"מ, הגהות והע\"ק לשם. של\"ה מאמר ג ומאמר ד נא, ב. מאמרי אדה\"א קונטרסים ע' פז, וש\"נ."],["2936","174","<b>רמ\"ח מ\"ע ושס\"ה מל\"ת</b>: מכות כג, ב."],["2937","176","<b>מובן מהכתב</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן פ\"ג פיסקא והנה<sup data-n=\"e250\">ט</sup>."],["2938","175","<b>שהם שלוחים. . במד' היו מכבדין את המצות</b>: תנחומא ויגש ו."],["2939","178","<b>אתרוג. . שהוא אינו מברך. . מצומח למדבר</b>: ראה גם לקמן הנחה ד\"ה אני לדודי הב' על יד הערה 67. (בחלק ההנחות) הנחה ד\"ה אני לדודי הא' על יד הערה 62. והב' על יד הערה 49.\n\n<b>ח</b>  ושם צ\"ל: תרומה כה, כ.\n\n<b>ט</b>  ראה גם הנרשם בריש ההנחה כאן."]]],[2000480314,"שמקיים ז\"מ בני נח<sup data-n=\"2940\">179</sup>, אבל כשעושה אותו למצוה אסור ליהנות ממנו דאסור להריח בו<sup data-n=\"2941\">177</sup> א\"כ נסתלק מהגשמיות ונעשה תכלית הרוחניות א\"כ ה\"ז העלאה, ולכן נמשלו המצות לכנפים שהם שלוחי הרצון וכמו\"כ המצות הם שלוחי הרצון, ועכשיו יש ג\"כ גילוי זה דמשחרב בהמ\"ק אין להקב\"ה בעולמו אלא ד\"א של הלכה<sup data-n=\"2942\">180</sup> א\"כ כמו שצמצם שכינתו<sup data-n=\"2943\">181</sup> בין ב' בדי ארון כמו\"כ עכשיו בד\"א של הלכה, וגבי לוחות כתי' והמכתב כו' חרות<sup data-n=\"2944\">182</sup> כו' אין לך בן חורין אלא מי שעוסק בתורה<sup data-n=\"2945\">183</sup> שהתורה מכסה על יגון ואנחה, וגם בגשמיות מי שעוסק מלאכתו<sup data-n=\"2946\">184</sup> נעשה ע\"י אחר, וכל ישראל עוסקים בתורה לכן קבעוהו בתפלה פ' איזהו מקומן<sup data-n=\"2947\">185</sup>, ויש דברים שיוצאים בהם לימוד בתורה<sup data-n=\"2948\">186</sup> והוא הלכה ואין מורין כן<sup data-n=\"2949\">187</sup> מ\"מ הלכה, והעיקר הוא ע\"י המצות. וזהו יונתי בחגוי הסלע כמו כנפי יונה הם שלוחי הרצון כמו\"כ הם<sup data-n=\"2950\">188</sup> רצה\"ע וע\"י נר מצוה ממשיכים בחי' ותורה אור כו'.",[["2940","179","<b>ז\"מ בני נח</b>: ראה סנהדרין נו, סע\"א. רמב\"ם הל' מלכים רפ\"ט. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 169."],["2941","177","<b>אתרוג. . דאסור להריח בו</b>: ראה סדר ברכת הנהנין פי\"א, ה\"ח: טוב למנוע מלהריח בו כל החג להנצל מספק ברכה."],["2942","180","<b>דמשחרב בהמ\"ק. . ד\"א של הלכה</b>: ראה ברכות ח, א. מאמרי אדה\"ז תקע\"א ע' צח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550570\" data-slug=\"torat-chaim\" data-id=\"2300550570\">תו\"ח תרומה ח\"ב שיז, ב</a> ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. הנחות תקע\"ז ע' ש. וש\"נ."],["2943","181","<b>שצמצם שכינתו</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380223\" data-slug=\"likkutei-torah\" data-id=\"4001380223\">לקו\"ת אמור לד, ב</a>. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["2944","182","<b>והמכתב כו' חרות</b>: תשא לב, טז."],["2945","183","<b>אין לך בן חורין. . בתורה</b>: אבות פ\"ו, ב [ושם: בתלמוד תורה — ראה (לעיל בחלק המאמרים) בהמאמר כאן הערה 91]."],["2946","184","<b>שעוסק מלאכתו</b>: אוצ\"ל: שעוסק בתורה מלאכתו."],["2947","185","<b>וכל ישראל. . בתפלה פ' איזהו מקומן</b>: ראה גם שו\"ע אדה\"ז הל' ברכות השחר רס\"נ."],["2948","186","<b>בתורה</b>: אוצ\"ל: התורה."],["2949","187","<b>הלכה ואין מורין כן</b>: ראה (לעיל בחלק המאמרים) בהמאמר כאן."],["2950","188","<b>כמו\"כ הם</b>: אוצ\"ל: כמו\"כ המצות הם."]]],[2000480315,"<h3>ואהבת את ה' אלקיך</h3>\n<b>ש\"פ עקב תר\"ם לפ\"ק</b>\n<b>ואהבת</b> את ה' אלקיך<sup data-n=\"2951\">1</sup> בכל לבבך ובכל נפשך ובכל מאדך<sup data-n=\"2952\">2</sup>, ואי' במשנה בכל לבבך בשני יצריך<sup data-n=\"2953\">3</sup> שגם היצה\"ר יהי' לו אהבה לאלקות, וצ\"ל מאחר שנק' יצר הר\"ע איך שייך שיהי' לו אהבה. ונראה שאף שיש לו אהבה מ\"מ נק' יצה\"ר ואיך אפ\"ל שניהם. והענין דהנה כתי' חלק ה' עמו<sup data-n=\"2954\">4</sup> וצ\"ל אם קאי רק על נה\"א או אם גם",[["2951","1","<b>ואהבת את ה' אלקיך</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הב' מהמשך יונתי (פ\"ד — פ\"ז) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: והנה כמו שנמשלו המצות בנר].\nבמאמר זה להלן על יד הערה 7 ועל יד הערה 23 בגוכתי\"ק עה\"ג באים ציונים."],["2952","2","<b>ואהבת את ה'. . ובכל מאדך</b>: ואתחנן ו, ה."],["2953","3","<b>במשנה בכל לבבך בשני יצריך</b>: ברכות נד, א. ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 18."],["2954","4","<b>חלק הוי' עמו</b>: האזינו לב, ט."]]],[2000480316,"הנה\"ב נק' חלק ה'. והענין דהנה כמו שנת\"ל בענין כי נר מצוה שהמצות נק' נר<sup data-n=\"2955\">5</sup> כמו\"כ יובן שהנשמה נק' נר וכמ\"ש נר ה' נשמת אדם<sup data-n=\"2956\">6</sup> חופש כל חדרי בטן הרי שנק' נר ולא נר סתם אלא נר ה', וצ\"ל מה שייך לזה אומרו חופש כל חדרי בטן וע\"פ פשוט הפי' שע\"י אמצעית הנשמה יודעים מה שבחדרי בטן, אך צ\"ל דבלא זה לא הי' יודע, (תו\"א מי כה' אלקי', המגבי' לשבת)<sup data-n=\"2957\">7</sup> והנה צ\"ל תחילה מהו נר דלכאו' שם נר הונח על השמן או החלב או השעוה, אבל באמת אינו כן שהרי נק' נר של שמן או כו' מובן שהנר הוא דבר בפ\"ע והוא של שמן או כו' וגם אפ\"ל שהנר הוא הכלי המחזיק השמן, אך זה שייך דוקא בנר של שמן אבל של חלב או שעוה שא\"צ כלי למה נק' נר, אלא ענין נר הוא הפתילה, הגם שא\"א להכחיש דכשהשמן טוב אז האור בהיר כו' וכמ\"ש ויקחו אליך שמן זית זך<sup data-n=\"2958\">8</sup> כתית למאור להעלות נר תמיד, מ\"מ זה תלוי בהפתילה ג\"כ וכמארז\"ל פתילות ושמנים<sup data-n=\"2959\">9</sup> שאין מדליקים בהם בשבת מדליקים בהם בחנוכה מפני שאסור להנות לאורו לכן אף אם לא ימשך השמן אחר הפתילה מ\"מ מותר להדליק, אבל בשבת שצריכים להנות לאורו אסור להדליק פתילות אלו מפני שאין השמן נמשך אחריהם, א\"כ הפתילה פועל כמו השמן, ומה שהשמן גורם שהיות הזמן זה תלוי ג\"כ בהפתילה שלולי הפתילה לא הי' דולק כלל, ויש מעלה בהפתילה שבו נאחז האור וע\"י נכלל השמן בהפתילה ועי\"ז האור מבהיק נמצא שהפתילה הוא כמו ממוצע שממשיך האור וגורם שיוכלל השמן בהאור, ומה שע\"י השמן מבהיק האור זה תלוי בהפתילה ג\"כ, והפתילה מרחיק האור מהשמן שלא יוטבע בהשמן ויכבה.\n<b>וככל</b> המשל הזה יובן למעלה ג\"כ דהנשמה נק' נר ה' דכתי' חלק הוי' עמו שכל נשמה היא חלק ה'<sup data-n=\"2960\">10</sup>, ואין ר\"ל חלק מאות א' דשם הוי' מיו\"ד ונשמה זו מה\"א כו' אלא כל נשמה ונשמה כלולה מי' ה' ו' ה', והגוף ה\"ה חומר פשוט לקבל צורת הנפש לכן בציורו יש שם הוי'<sup data-n=\"2961\">11</sup>, הראש הוא י', ה' אצבעות ידיו ורגליו הוא ה' ראשונה וה' אחרונה והגם שאין זה תמונות ה' מ\"מ הוא מספר ה', והגוף הוא ו' ובראשו יו\"ד זהו הראש, וראי' לזה שצריכים שיהי' חומר מוכן לקבל צורת הנפש הוא מענין הגלגולים שנשמת האדם מתגלגלת בצומח או בחי<sup data-n=\"2962\">12</sup> או בדומם<sup data-n=\"2963\">13</sup>, וידוע דעונש הגלגול קשה מעונש המיתה שאין לך אדם שיפטר מזה אבל הגלגול הוא על",[["2955","5","<b>שנת\"ל. . שהמצות נק' נר</b>: הנחה ד\"ה יונתי על יד הערה 92 ואילך."],["2956","6","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["2957","7","<b>(<a class=\"ft-cite\" href=\"#/read/torah-or/3901370174\" data-slug=\"torah-or\" data-id=\"3901370174\">תו\"א</a> מי כה' אלקי' המגבי' לשבת)</b>: כ\"ז נרשם עה\"ג<sup data-n=\"e251\">א</sup> בצד הימני של העמוד, בסמיכות להתיבות שהובאו בפנים, בלי חצ\"ע. והכוונה שלהבא להלן לעיין בתו\"א מקץ לח, ב."],["2958","8","<b>ויקחו אליך שמן זית זך</b>: תצוה כז, כ."],["2959","9","<b>פתילות ושמנים</b>: ראה שבת כא, ב."],["2960","10","<b>שכל נשמה היא חלק הוי'</b>: ראה אגה\"ת פ\"ד."],["2961","11","<b>והגוף. . בציורו יש שם הוי'</b>: ראה לעיל (בחלק המאמרים) בההמשך כאן הערות 103-104."],["2962","12","<b>הגלגולים. . בחי</b>: ראה ת\"ז ת\"ע קלג, א ובכס\"מ שם אות ת (קעח, א). סה\"מ תרכ\"ט ע' יח. וש\"נ. ע' ריח. וש\"נ. ע' שצה. פלח רמון בהר ע' שצו. וש\"נ."],["2963","13","<b>הגלגולים. . בדומם</b>: ראה מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670317\" data-slug=\"torat-chaim\" data-id=\"2300670317\">תו\"ח נח סח, ב</a> ובהערה 9. שמות ח\"א כח, ב. וש\"נ.\n\n<b>א</b>  ראה גם לקמן על יד הערה 23."]]],[2000480317,"עבירות חמורות, וצ\"ל מה גודל העונש כ\"כ ואם נא' שהוא מה שנתלבש בדומם הרי הגוף בצאת הנפש ממנו הוא דומם, ואם נא' שהעונש הוא דקודם התלבשותה בגוף כתי' חי ה' אשר עמדתי לפניו<sup data-n=\"2964\">14</sup> והי' לה אהוי\"ר ועתה אין לה אהוי\"ר, הרי גם בעת התלבשותה בגוף ג\"כ לא הי' להם האהוי\"ר, ועוד דהנה נשמות הפורחות באויר ג\"כ אינם משיגים כו' ועונשם קטן מעונש הגלגול<sup data-n=\"2965\">15</sup> שהוא רק לנשמות העשוקות<sup data-n=\"2966\">16</sup> רק מעבירות חמורות ממילא נעשה נשמות עשוקות, וצ\"ל דהעונש הוא דגוף הבהמה אינו חומר מוכן לקבל צורת נפש האדם<sup data-n=\"2967\">17</sup> דהנה הבהמה שרשה מתהו ושרש האדם מתקון אשר שם שייך מעלה ומטה לכן בהאדם ג\"כ יש התחלקות ראש ורגל, הגם דנעוץ תחב\"ס<sup data-n=\"2968\">18</sup> שיש מעלה בהרגל מה שאין בראש מ\"מ הראש הוא עיקר הראש<sup data-n=\"2969\">19</sup> ואין מתחילין מן הרגל, ומ\"ש מבלי אשר ימצא ראש וסוף<sup data-n=\"2970\">20</sup> ר\"ל שבאמת אינו שייך לומר סוף שהרי יש מעלה בהרגל שהוא נק' ראש אבל מ\"מ הראש ראש והרגל רגל, אבל הבהמה שרשה מתהו שהוא בחי' עגולים אשר אין שם מעלה ומטה כלל לכן הראש והזנב הוא בקו השוה בבהמה אדרבה היא משפיל ראשה<sup data-n=\"2971\">21</sup>, ועיקר התקון הוא ע\"י עשי' וכשמתגלגלת הנשמה בגוף הבהמה הרי א\"א להיות עשי' שהרי חומר הבהמה אינו מוכן לקבל צורת הנפש וא\"כ א\"א להיות תקון מצ\"ע כ\"א זמן המוגבל או אחר אפשר לעשות טובה לפ\"ז העונש קשה מאד. היוצא מזה שצריכים חומר מוכן לקבל צורת הנפש כדי לפעול פעולת הנפש, וצ\"ל מהו פעולת הנפש.\n<b>הנה</b> יו\"ד שבנפש הוא חכ'<sup data-n=\"2972\">22</sup> (ה' וע' מענין ש' הוי' שבנפש בד\"ה ראה אנכי נותן לפניכם ע'<sup data-n=\"2973\">23</sup> ) ואין זה השגה והבנה, שהוא מ\"ש ונשמת שדי תבינם<sup data-n=\"2974\">24</sup> והוא בינה, אלא בחי' חכ' הוא ברק המבריק<sup data-n=\"2975\">25</sup> טרם שבא לידי השגה שגם הוא עצמו אינו משיג עדיין, ויש בזה מה שנשאר בהעלם ומה שיוצא לידי גילוי וכמו השכל שבא לידי גילוי מהמשכיל, ויש עוד בחי' בנשמה והוא בטל הרצון שלמעלה",[["2964","14","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח סב, סע\"ד</a>. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["2965","15","<b>נשמות הפורחות באויר.. הגלגול</b>: ראה גם (לעיל בחלק המאמרים) בההמשך כאן על יד הערה 108."],["2966","16","<b>נשמות העשוקות</b>: ראה גם זהר סבא משפטים צה, ב."],["2967","17","<b>דגוף הבהמה. . אדם</b>: ראה לעיל (בחלק המאמרים) בההמשך כאן הערות 109-110."],["2968","18","<b>דנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["2969","19","<b>הראש</b>: כ\"ה בגוכתי\"ק."],["2970","20","<b>מבלי אשר ימצא ראש וסוף</b>: ע\"פ קהלת ג, יא."],["2971","21","<b>הראש והזנב. . בבהמה. . ראשה</b>: ראה גם לעיל (בחלק המאמרים) בההמשך כאן ובהערה 111."],["2972","22","<b>יו\"ד. . חכ'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38. לעיל המשך יונתי הערה 26."],["2973","23","<b>(ה'. . בד\"ה ראה אנכי נותן לפניכם ע')</b>: כ\"ז נרשם עה\"ג<sup data-n=\"e252\">ב</sup> בצד השמאלי של העמוד בסופו, בסמיכות להתיבות שהובאו בפנים, בלי חצ\"ע. והכוונה שלהבא להלן לעיין ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת פ' ראה יח, א</a>. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 26."],["2974","24","<b>ונשמת שדי תבינם</b>: איוב לב, ח. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600675\" data-slug=\"or-hatorah-hb\" data-id=\"8316600675\">אוה\"ת איוב כרך א ע' תרעה</a> ואילך."],["2975","25","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לעיל (בחלק המאמרים) המשך יונתי רפ\"ד. וש\"נ.\n\n<b>ב</b>  ראה גם לעיל על יד הערה 7."]]],[2000480318,"מטו\"ד הוא קוש\"י<sup data-n=\"2976\">26</sup> והוא מה שנשאר בהעלם לגמרי, וזהו כי עם קשה ערף וסלחת<sup data-n=\"2977\">27</sup> ולכאורה צ\"ל מה זה נתינת טעם על סליחות עונות והלא טעם זה מחייב ההיפוך, אך ר\"ל מאחר שהם מתנהגים למטה בבחי' ביטל שלמעלה מטו\"ד צריכים להתנהג עמהם מלמעלה ג\"כ בבחי' שלמעלה מטו\"ד הגם שעפ\"י הטו\"ד עשו היפך כו' מ\"מ מצד בחי' שלמעלה מטו\"ד צ\"ל סליחות עונות, זהו יו\"ד וקוש\"י בקצרה.\n<b>ה'</b> הוא התבוננות וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה המוציא במספר צבאם ולכולם<sup data-n=\"2978\">28</sup> בשם יקרא איש לא נעדר, וביאור הענין דהנה בשבחי דהמע\"ה ששיבח את הקב\"ה אמר מה רבו מעשיך ה'<sup data-n=\"2979\">29</sup>, ומה גדלו מעשיך ה'<sup data-n=\"2980\">30</sup>, וצ\"ל מהו השינוי ל' והו\"ל בשניהם מה רבו או מה גדלו, אך הנה מה גדלו מעשיך ה' הוא גדולי הנבראים שנבראו כמו מלאכים דארז\"ל מלאך בשליש עולם עומד<sup data-n=\"2981\">31</sup> וכן השמש אי' ברמב\"ם הל' יסודי התורה<sup data-n=\"2982\">32</sup> שהוא ק\"ע פעמים נגד הארץ (ה' והוא ערך 4,104000 מיל<sup data-n=\"2983\">33</sup> הסובב של השמש ע') והירח כ' שם שהוא בערך חלק ארבעים מן הארץ (ה' והוא בערך תקצ\"ה מיל ושמינית מיל<sup data-n=\"2984\">34</sup> הסובב של הירח ע') והכוכב הקטן שבכל הכוכבים הוא מיל<sup data-n=\"2985\">35</sup> סבובו, ונמצא ארכו שליש מיל, וכשהתבונן דוד בריבוי הפרטים שנבראו בכל מין ומין א' מה רבו מעשיך ה' הגם שבכלל הם רק ד' דצח\"מ מ\"מ הפרטים הם רב מאד וכמו במין דומם יש כמה מינים כמו אבן פשוט עד אבני חשן ואפוד שלא הי' צומח כ\"א דומם רק שהוא יקר המציאות והוא מבהיק, וביניהם יש כמה מינים, וכן בעפר יש העפר שבקרקע המשכן<sup data-n=\"2986\">36</sup> שהוא בדיקה לאשת זנונים<sup data-n=\"2987\">37</sup> ומ\"מ הוא ג\"כ דומם, ויש עפר שמצמיח מין זה ועפר שמצמיח מין אחר וכולם הם דומם, וכן בצומח יש עשבים וזרעוני גינה ותבואות",[["2976","26","<b>בטל הרצון. . קוש\"י</b>: ראה זהר ויקרא י, ב. פרדס שער שם בן ד' שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["2977","27","<b>כי עם קשה עורף וסלחת</b>: תשא לד, ט [בדילוג]. ראה שמו\"ר פמ\"ב, ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380589\" data-slug=\"likkutei-torah\" data-id=\"4001380589\">לקו\"ת בלק סז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380603\" data-slug=\"likkutei-torah\" data-id=\"4001380603\">עא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550766\" data-slug=\"torat-chaim\" data-id=\"2300550766\">תו\"ח תצוה ח\"ב שעט, ד</a>. וש\"נ. סה\"מ תרכ\"ז ס\"ע עד ואילך. וש\"נ."],["2978","28","<b>שאו מרום עיניכם. . ולכולם</b>: ישעי' מ, כו [ושם: לכולם — בדילוג]."],["2979","29","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a>. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 36."],["2980","30","<b>ומה גדלו מעשיך ה'</b>: תהלים צב, ו [ושם: מה]. ראה תו\"א שם. לעיל שם מאמר ד\"ה ואעשך לגוי גדול שם ובהערה 42."],["2981","31","<b>מלאך בשליש עולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 44."],["2982","32","<b>השמש אי' ברמב\"ם הל' יסודי התורה</b>: פ\"ג, ה\"ח [ושם: כמו ק\"ע]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101180\" data-slug=\"likkutei-sichot\" data-id=\"1300101180\">לקו\"ש בראשית כרך י ע' 180</a> ואילך. (לעיל בחלק המאמרים) בההמשך כאן הערה 123."],["2983","33","<b>4104000מיל</b>: בהקדמה לפיה\"מ כותב הרמב\"ם [בד\"ה אחר כן ראה להסתפק]: וכדור הארץ. . שיש בהקפו ארבעה ועשרים אלף מיל (17124000)."],["2984","34","<b>תקצ\"ה מיל ושמינית מיל</b>: כ\"ה בכגוכתי\"ק."],["2985","35","<b>והכוכב הקטן. . מיל</b>: ראה פירוש ליסוה\"ת שם."],["2986","36","<b>העפר שבקרקע המשכן</b>: ע\"פ נשא ה, יז."],["2987","37","<b>בדיקה לאשת זנונים</b>: ראה זהר רע\"מ אמור צז, א."]]],[2000480319,"ובכולם יש כמה מינים, ויש אילני סרק ואילני פרי וכולם בכללן הם צומח לא שנא' שאילני סרק הוא צומח ואילן תפוח הוא בע\"ח אלא כולם צומח, וכן בבע\"ח יש בהמות וחיות בהמות טמאות וטהורות קטנים וגדולים ובחיות יש ג\"כ גדולות שטורפים ודורסים גדולה דוקא וקטנות שטורפים ודורסים קטנה דוקא, ועופות, אפי' במין המדבר שנברא יחידי שלא יאמר אדם לחבירו אבא גדול מאביך<sup data-n=\"2988\">38</sup> מ\"מ יש בהם ג\"כ מינים חלוקים לבד מה ארז\"ל<sup data-n=\"2989\">39</sup> שאין א' מהם דומה לחבירו<sup data-n=\"2990\">40</sup> הוא בהציור, כמו\"כ בטבעות ג\"כ אינם דומין זל\"ז וכ' בס' המסעות שיש מיני ברואים בעין א' ובג' עינים<sup data-n=\"2991\">41</sup> וע\"ז א' מה רבו מעשיך, והנה כל דבר יש לו שרש למעלה וכמארז\"ל אין לך עשב<sup data-n=\"2992\">42</sup> למטה שאין לו מזל למעלה המכה בו ואומר לו גדל שפועל בו ההגדלה מקטנות לגדלות, ופי' המכה בו כמו עד\"מ המכה את חבירו הוא שירגיש ההכאה כמו\"כ כאן ששופע בו חיות וירגיש ההשפעה ופועל בו ההגדלה כו', וזהו ולכולם בשם יקרא שכאו\"א יש לו קריאות שם מיוחד איש לא נעדר, איש הוא ל' שר וכמו האיש אדון הארץ<sup data-n=\"2993\">43</sup>, איש אלקים<sup data-n=\"2994\">44</sup>, ובל' המשנה אישי כה\"ג<sup data-n=\"2995\">45</sup> ר\"ל בעה\"ב, לא נעדר שישנו תמיד דשרש ההתהוות הוא מא\"ס הבבע\"ג והוא נצחי. ומ\"ש השמים כעשן נמלחו והארץ כבגד יבלה<sup data-n=\"2996\">46</sup> עש יאכלם<sup data-n=\"2997\">47</sup> היינו שלא יהי' גשמיים והו\"ע הפשטות הגשמיות וכתי' השמים החדשים<sup data-n=\"2998\">48</sup> כו' שהוא התחדשות אבל הכח הוא קיים לעד.\n<b>ו\"ה</b> הוא מדות ודיבור ולפעמים מבואר שהוא קול ודיבור והם תורה ותפלה וכמ\"ש הקל קול יעקב קלא קדמאה חסר ו' הוא קול של תפלה קלא בתראה<sup data-n=\"2999\">50</sup> מלא ו' הוא קול של תורה<sup data-n=\"3000\">51</sup>, ובמ\"א מבואר שהם תורה ומצות<sup data-n=\"3001\">49</sup>, תורה הוא קלא בתראה כו' ומצות הם דיבור (ה' דבר מלך שלטון<sup data-n=\"3002\">52</sup> ע') וכנגד זה יש בתמונות הגוף ג\"כ שם הוי' כדי שיוצא כחות הנפש מכח אל הפועל.",[["2988","38","<b>שנברא יחידי. . אבא גדול מאביך</b>: ראה סנהדרין לז, א (במשנה)."],["2989","39","<b>ארז\"ל</b>: אוצ\"ל שארז\"ל."],["2990","40","<b>שאין א' מהם דומה לחבירו</b>: סנהדרין שם. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תתקטז ואילך."],["2991","41","<b>וכ' בס' המסעות שיש מיני ברואים בעין א' ובג' עינים</b>: ראה גם (לעיל בחלק המאמרים) בההמשך כאן על יד הערה 128."],["2992","42","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 549."],["2993","43","<b>האיש אדון הארץ</b>: מקץ מב, ל [ושם: אדוני]."],["2994","44","<b>איש אלקים</b>: מלכים-ב א, י."],["2995","45","<b>אישי כה\"ג</b>: יומא פ\"א, מ\"ג. מ\"ה."],["2996","46","<b>השמים כעשן. . כבגד יבלה</b>: ישעי' נא, ו [ושם: כי שמים. . תבלה]."],["2997","47","<b>עש יאכלם</b>: ישעי' נ, ט [ושם: כבגד יבלו עש יאכלם]."],["2998","48","<b>השמים החדשים</b>: ישעי' סו, כב."],["2999","50","<b>הקל קול יעקב קלא קדמאה. . בתראה</b>: תולדות כז, כב. ראה הנסמן באוה\"ת וישב כרך ב ע' 526. כרך ה ע' 1788."],["3000","51","<b>הקל קול יעקב. . תפלה. . תורה</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. מאמרי אדה\"א בראשית ע' שמח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680453\" data-slug=\"torat-chaim\" data-id=\"2300680453\">תו\"ח מקץ רכז, ב</a> ובנסמן במ\"מ לשם."],["3001","49","<b>ו\"ה. . תורה ומצות</b>: ראה אגה\"ת ספ\"ד. סה\"מ מלוקט ב' ע' רלג ובהערה 40."],["3002","52","<b>דבר מלך שלטון</b>: קהלת ח, ד."]]],[2000480320,"<b>אך</b> הנה יש ב' נפשות וכמ\"ש ונשמות אני עשיתי<sup data-n=\"3003\">53</sup> נה\"א ונה\"ב ועז\"א ואהבת את ה' אלקיך בכל לבבך בשני יצריך שגם היצה\"ר יהי' לו אהבה לאלקות. וצ\"ל והלא הוא רע ואיך אפשר שיאהב כו', והענין דהנה נה\"ב הוא כח המתאווה<sup data-n=\"3004\">54</sup> ויוכל לאהוב אלקות ג\"כ רק שעושין בו הציור רע וע\"י התבוננות יכולים לאכפיי' לאלקות, וביאור הענין דהנה כל נפש מב' נפשות אלו יש להם שכל ומדות, נה\"א יש בו שכל ומדות הנולדים מן השכל, ונה\"ב יש לו ג\"כ שכל ומדות הנולדים מהשכל (ה' והמדות הם נק' יצה\"ר וכמ\"ש בתו\"א ובקדושה ג\"כ המדות הנולדים משכל נה\"א נק' יצ\"ט<sup data-n=\"3005\">55</sup> וכמש\"ש ע') והעיקר הוא השכל שמנהיג את המדות, והנה שכל של הנה\"א הוא להשכיל השכלות בהתבוננות אלקות וכמ\"ש שאו מרום עיניכם כו', ומזה נולד המדה לאהבה את ה' אלקיך<sup data-n=\"3006\">56</sup>, למען תירא את ה' אלקיך<sup data-n=\"3007\">57</sup>, וכן שארי המדות, ולהיפך שכל הנה\"ב הוא איך התאות זרות ורצונות זרות טוב לו, אף שבאמת הוא שקר גמור וכמו עד\"מ האוכל דבש הרבה שהוא מתוק וסופו מר וכמו\"כ סוף כל סוף יודע שהוא לרע לו, אך מ\"מ הוא מראה לו את הדבר הטוב לו ומזה נולד המדה שיאהב הדבר ההוא וכשישנו אצל חבירו והוא מבקש ממנו ואינו נותן לו ה\"ה שונא אותו ונמצא עובר על מ\"ע ואהבת לרעך<sup data-n=\"3008\">58</sup> כו' וכן מתפאר בדבר שאין לו ונמצא משקר והוא מצד שמבין בשכלו דמי שיש לו ד\"ז טוב לו לכן הוא מתפאר בזה אבל באמת הוא שקר, וזהו יצה\"ר, אך מפני שהוא מצד השכל לכן יכולים להפכו לאלקות, והוא כשיתבונן בהתבוננות הנ\"ל איך מה רבו מעשיך ה' כו' ולכולם בשם יקרא איש כו' שלכל דבר יש שרש ומקור ולמה ירצה בדבר הנתהווה טוב לו שירצה בהמהווה, ואף גם זאת מ\"מ נק' רע דאל תאמין בעצמך<sup data-n=\"3009\">59</sup> ואפשר שיחזור לקלקולו.\n<b>וביאור</b> הענין איך אפשר שהיצה\"ר יהי' לו אהבה לאלקות, צ\"ל תחילה מ\"ש ואהבת איך שייך ציווי על אהבה<sup data-n=\"3010\">60</sup> שהוא מדה שבלב, אך באמת אין הציווי על האהבה כ\"א על ההתבוננות בפסוק ראשון דק\"ש שמע ישראל<sup data-n=\"3011\">61</sup> ה' אלקינו ה' אחד, שמע יש בו ב' פי' א' מל' הסכת ושמע<sup data-n=\"3012\">62</sup>, ב' מל' וישמע שאול<sup data-n=\"3013\">63</sup>, ושניהם עולים בקנה א' דפי' הסכת ושמע שיקבץ כל הכחות אל חוש השמיעה, ואין פי' שמיעה גשמיות רק שמיעה רוחניות והוא ההתבוננות, ומ\"ש וישמע שאול פי' שקיבץ כל",[["3003","53","<b>ב' נפשות. . ונשמות אני עשיתי</b>: ישעי' נז, טז. ראה תניא פ\"א<sup data-n=\"e253\">ג</sup>."],["3004","54","<b>נה\"ב הוא כח המתאווה</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה תעשה לי על יד הערה 125. (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ב."],["3005","55","<b>והמדות. . יצה\"ר וכמ\"ש ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370174\" data-slug=\"torah-or\" data-id=\"3901370174\">תו\"א</a>. . יצ\"ט</b>: מקץ לח, ב."],["3006","56","<b>לאהבה את ה' אלקיך</b>: נצבים ל, כ."],["3007","57","<b>למען תירא את ה' אלקיך</b>: ואתחנן ו, ב."],["3008","58","<b>שונא. . ואהבת לרעך</b>: קדושים יט, יח."],["3009","59","<b>דאל תאמין בעצמך</b>: אבות פ\"ב, מ\"ד."],["3010","60","<b>איך שייך ציווי על אהבה</b>: ראה גם לעיל ח\"א ע' רפג. וש\"נ."],["3011","61","<b>שמע ישראל</b>: ואתחנן ו, ד."],["3012","62","<b>הסכת ושמע</b>: תבוא כז, ט. ראה זהר אד\"ר נשא קלח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו. וש\"נ. הנחות תקע\"ז ע' קמח. וש\"נ."],["3013","63","<b>וישמע שאול</b>: שמואל-א טו, ד. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381012\" data-slug=\"likkutei-torah\" data-id=\"4001381012\">לקו\"ת האזינו עב, ב</a>. שע\"ת ס, ג ובהערה 8.\n\n<b>ג</b>  וראה גם במ\"מ הגהות והע\"ק ובליקוט פירושים שם."]]],[2000480321,"העם למקום א' לילך ללחום כאחד, ה' אלקינו הוא סוכ\"ע<sup data-n=\"3014\">64</sup> וממכ\"ע<sup data-n=\"3015\">65</sup>, ופי' הוי' הוא ל' מהווה<sup data-n=\"3016\">66</sup> והיו\"ד מורה על תמידות ההתהוות<sup data-n=\"3017\">67</sup>, וזהו ה' אחד ה' שהוא המהווה תמיד הוא אחד דאני לא שניתי<sup data-n=\"3018\">68</sup> אתה הוא קודם שנבה\"ע<sup data-n=\"3019\">69</sup> ואתה הוא לאחר שנבה\"ע, הגם שקודם הברי' לא הי' ואתה<sup data-n=\"3020\">70</sup> יש כו' אך מפני שהוא רק הארה, וזהו שאו' אח\"כ בשכמל\"ו<sup data-n=\"3021\">71</sup> שם הוא הארה לא עצמיות וכבוד הוא לבר מעצמותו, ור\"י קארי למאנא מכבדותא<sup data-n=\"3022\">72</sup> שהוא לבוש הארה בעלמא, ומלכותו הוא מלך שמו נק' עליהם<sup data-n=\"3023\">73</sup> א\"כ ה\"ז הארה, והארה דהארה, והארה דהארה דהארה, ואין הארה פועל שינוי בהעצם, ואי לזאת ואהבת את ה' אלקיך בכל לבבך שגם היצה\"ר יהי' לו אהבה לאלקות (בפ\"א<sup data-n=\"3024\">74</sup> וכמ\"ש מי לי בשמים<sup data-n=\"3025\">75</sup> ועמך לא חפצתי בארץ כל מה שעמך לא חפצתי כ\"א א\"ס עצומ\"ה<sup data-n=\"3026\">76</sup>.\n<b>וזהו</b> מ\"ש נר ה' נשמת אדם, שהנה\"ב הוא השמן, דשמן הוא חכ'<sup data-n=\"3027\">77</sup>, וחכ' יש בכל דבר, והנה\"א הוא הפתילה, דהנה\"א מצד עצמו א\"צ תיקון<sup data-n=\"3028\">78</sup> שהוא חלק ה' ולכן נק' נר ה' והוא הפתילה הממשיך את השמן שמעלה את הנה\"ב, אך השמן צ\"ל שמן זית זך דכשיש בו עפרורית אינו ראוי לדליקה, כמו\"כ כשמעורב בו רע א\"א להתעלות רק צריכים לבררו תחילה ואז נמשך השמן אחר הפתילה, ואז האור",[["3014","64","<b>הוי' אלקינו הוא סוכ\"ע וממכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380613\" data-slug=\"likkutei-torah\" data-id=\"4001380613\">לקו\"ת בלק עג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380615\" data-slug=\"likkutei-torah\" data-id=\"4001380615\">עד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540173\" data-slug=\"torat-chaim\" data-id=\"2300540173\">תו\"ח וארא ח\"א עג, ב</a>. וש\"נ."],["3015","65","<b>סוכ\"ע וממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["3016","66","<b>הוי' הוא ל' מהווה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. פרדס שער עשר ולא תשע ש\"א, פ\"ט. שער עצמות וכלים שער ד, ספ\"י. שער היחוה\"א פ\"ד. פ\"ז. הערה בסה\"מ ת\"ש ע' 40."],["3017","67","<b>והיו\"ד מורה על תמידות ההתהוות</b>: ראה שער היחוד והאמונה רפ\"ד."],["3018","68","<b>דאני לא שניתי</b>: מלאכי ג, ו [בדילוג השם]."],["3019","69","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3020","70","<b>ואתה</b>: אוצ\"ל: ועתה."],["3021","71","<b>בשכמל\"ו</b>: נוסח ק\"ש. פסחים נו, א. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו ובהערה 76."],["3022","72","<b>ור\"י קארי למאנא מכבדותא</b>: ראה שבת קיג, א."],["3023","73","<b>מלך שמו נקרא עליהם</b>: ראה פיוט אדון עולם. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 16."],["3024","74","<b>בפ\"א</b>: [ בפעם א' אמר כ\"ק אדמו\"ר מהר\"ש] ראה גם לקמן ע' תשכא-ג (ב\"פ). ע' תשלו-ז (ב\"פ). ע' תשמא. ע' תשמז-נד (ד\"פ). ע' תשנז. ע' תשפב-ג (ב\"פ) ע' תשפח. ע' תשצד-ז (ג\"פ). ע' תתב-י (ו\"פ). ע' תתיב-ט (ו\"פ<sup data-n=\"e254\">ד</sup>). ע' תתכג-ח (ה\"פ<sup data-n=\"e255\">ה</sup>). ע' תתכט-לה (כב\"פ). ע' תתלח-מו (י\"פ). ע' תתמח-נ (ב\"פ). ע' תתנא. לעיל בח\"א ע' רעט ובהערה 80. סה\"מ תרל\"ח ע' תכז ובהערה 104. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' קכו<sup data-n=\"e256\">ו</sup>."],["3025","75","<b>מי לי בשמים</b>: תהלים עג, כה."],["3026","76","<b>עצומ\"ה</b>: אוצ\"ל: עצומ\"ה)."],["3027","77","<b>דשמן הוא חכ'</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה ובהערה 137."],["3028","78","<b>דהנה\"א. . א\"צ תיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">ש\"א ט, א</a> הערה 4.\n\n<b>ד</b>  שם ע' תתיז [ושם: בפ\"ב בפ\"ג ]. שם [ושם: בפ\"ג].\n\n<b>ה</b>  שם ע' תתכח [ושם: בפ\"א שע\"ה ותכ\"ד חזר ואמר ש\"ע]. שם [ושם: בפ\"ג].\n\n<b>ו</b>  בכותרת שם: בפ\"א ובפ\"ב לא שמעתי מא'."]]],[2000480322,"מבהיק, והיינו שיומשך תוס' אורות בק\"ו מבחי' מל' דא\"ס, דהנה שרש הנה\"ב הוא מתהו<sup data-n=\"3029\">79</sup> שקדם לתיקון<sup data-n=\"3030\">80</sup> וידוע ההפרש בין תהו לתיקון דבתהו ריבוי האור ובתיקון מיעוט האור<sup data-n=\"3031\">81</sup>, ופי' ריבוי ומיעוט הוא שהאור הוא באופן אחר לגמרי<sup data-n=\"3032\">82</sup> וכמו אור שנברא ביום א' הי' אדה\"ר מביט מסוף עולם ועד סופו<sup data-n=\"3033\">83</sup> ועתה יכול האדם לראות רק מיל או פרסה<sup data-n=\"3034\">84</sup>, כמו\"כ אורות דתהו לגבי תיקון אינם בערך כלל, וע\"י שמברר את הנה\"ב נמשך אורות דתהו לבוא לידי גילוי בתיקון, דמעקודים נקודים נעשה ברודים<sup data-n=\"3035\">85</sup>, וזהו נר הוי' נשמת אדם נר הוי' קאי על הנה\"א דהנה\"ב שעדיין לא נתברר א\"א לקרותו נר הוי' נשמת אדם, אדם א' דם<sup data-n=\"3036\">86</sup> והדם הוא הנפש החיונית המחי' את הגוף וכמ\"ש כי הדם הוא הנפש<sup data-n=\"3037\">87</sup> וצריכים לבררו שיהי' בטל לאל\"ף הוא א\"ס אלופו ש\"ע<sup data-n=\"3038\">88</sup>, חופש כל חדרי בטן דהנה צדיק אוכל לשובע נפשו<sup data-n=\"3039\">89</sup> שמעלה את המאכל ובטן רשעים תחסור<sup data-n=\"3040\">90</sup> שעושה חסרון בהמאכל, וע\"י נר ה' חופש כל חדרי בטן שמברר את הדם עי\"ז נתוסף תוס' אורות בנר ה', וזהו ואהב\"ת בגי' ב\"פ אור<sup data-n=\"3041\">91</sup> א' הוא אור דנה\"א מצ\"ע ב' מה שנתוסף בו מצד בירור הנה\"ב, ובעבודה הו\"ע ביטול דוכל נפשך ובכל מאדך, בכל נפשך הוא בכל כחות נפשו וזהו הביטול דנה\"א מצ\"ע, ובכל מאדך הוא שיוצא חוץ להגבלות הכלי לגמרי והוא מצד הבירור דנה\"ב. וזהו",[["3029","79","<b>שרש הנה\"ב הוא מתהו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670141\" data-slug=\"torat-chaim\" data-id=\"2300670141\">תו\"ח נח ס, ג</a> ובהנסמן במ\"מ לשם. סה\"מ תרע\"ח ע' רפ."],["3030","80","<b>מתהו שקדם לתיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ."],["3031","81","<b>ההפרש בין תהו לתיקון. . ריבוי. . מיעוט האור</b>: ראה ע\"ח שער הכללים פ\"א ואילך. שער התיקון ש\"י, פ\"ה. שער המלכים שי\"א, פ\"א-ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370039\" data-slug=\"torah-or\" data-id=\"3901370039\">תו\"א נח ט, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a>. מאמרי אדה\"א דברים ח\"ד ע' א'תעו<sup data-n=\"e257\">ז</sup> ואילך. ע' א'תפאז ואילך. סה\"מ תרל\"ח ע' שנד. וש\"נ. (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת על יד הערה 52. ובחלק ההנחות שם על יד הערה 65."],["3032","82","<b>שהאור הוא באופן אחר לגמרי</b>: ראה סה\"מ תר\"ל ע' קנ. (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 57."],["3033","83","<b>אור שנברא. . אדה\"ר. . סופו</b>: ראה חגיגה יב, א. ב\"ר פי\"ב, ו. פי\"א, ב. לעיל ד\"ה ביום השמיני עצרת שם ובהערה 59."],["3034","84","<b>יכול האדם לראות רק מיל או פרסה</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת על יד הערה 62. לקמן הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 75. ו(בחלק ההנחות) שם על יד הערה 71. ד\"ה ביום השמיני עצרת על יד הערה 79. מאמרי אדה\"א הנחות תקע\"ז ע' רח. ע' שלו. וש\"נ. במדבר ח\"ד ע' א'תצג<sup data-n=\"e258\">ח</sup>. וש\"נ. סה\"מ תרכ\"ז ע' שעד. וש\"נ. תרל\"ב ח\"א ע' שלב. תרל\"ח ע' רפ."],["3035","85","<b>דתהו. . בתיקון דמעקודים נקודים נעשה ברודים</b>: ויצא לא, י. יב. ראה גם הגהת מהרנ\"ש על ע\"ח דרוש העקודים פ\"א מ\"ת אות כד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670078\" data-slug=\"torat-chaim\" data-id=\"2300670078\">תו\"ח נח סד, ב</a> ובהנסמן במ\"מ לשם."],["3036","86","<b>אדם א' דם</b>: נסמן לעיל בהנחה ד\"ה יונתי בחגוי הסלע הערה 85."],["3037","87","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["3038","88","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["3039","89","<b>צדיק אוכל לשובע נפשו</b>: משלי יג, כה. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואמנם יש עוד בחי' חולה ובהערה 13."],["3040","90","<b>תחסור</b>: אוצ\"ל: תחסר."],["3041","91","<b>ואהב\"ת בגי' ב\"פ אור</b>: ראה פע\"ח שער הק\"ש ש\"ח, פכ\"ג. פכ\"ה. מאמרי אדה\"א שמות ח\"ב ע' שנא. וש\"נ. דברים ח\"ד ע' א'תקה ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540608\" data-slug=\"torat-chaim\" data-id=\"2300540608\">תו\"ח וארא ח\"א סה, ג</a>. וש\"נ.\n\n<b>ז</b>  וכן צ\"ל בפלח הרמון בחוקותי ע' תנו בהערות.\n\n<b>ח</b>  וכן צ\"ל בסה\"מ תרל\"ב המובא בסמוך בפנים ההערה."]]],[2000480323,"ואהבת כו' בכל לבבך שגם היצה\"ר יהי' לו אהבה לאלקות והוא כשיתבונן בפסוק ראשון דק\"ש שמע כו' ועי\"ז יתעלה למעלה וכמו השמן שנמשך אחר הפתילה האור ה' נה\"א ועי\"ז מתוסף תוס' אורות בנה\"א והוא בחי' בכל מאדך בלי גבול<sup data-n=\"3042\">92</sup> כו'.",[["3042","92","<b>בכל מאדך בלי גבול</b>: ואתחנן ו, ה. ראה אגה\"ק סי\"ז. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גן נעול הב' ובהערה 35."]]],[2000480324,"<h3>יפה שעה א' הא'</h3>\n<b>ש\"פ ראה תר\"ם לפ\"ק</b>\n<b>יפה</b> שעה א'<sup data-n=\"3043\">1</sup> בתשו' ומע\"ט בעוה\"ז מכל חיי עוה\"ב<sup data-n=\"3044\">2</sup>, הנה עוה\"ב הוא ג\"ע ועצם עשיות המצוה טוב יותר משכר המצוה, וצ\"ל ואיך<sup data-n=\"3045\">3</sup> שייך לומר שעשיות המצוה יהי' יפה משכר המצוה, ואומרו כל חיי עוה\"ב משמע שכולל עולם התחי' ג\"כ, הגם שברוב המקומות שנז' במשנה עוה\"ב ר\"ל ג\"ע וכמאמר כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"3046\">4</sup> וכמ\"ש לעולם ירשו ארץ<sup data-n=\"3047\">5</sup> ומפרשי' ארץ ג\"ע התחתון, וידוע הפלוגתא דהרמב\"ם והרמב\"ן<sup data-n=\"3048\">6</sup> בענין עוה\"ב אם הוא חיי הנפש בלא גוף או מה שיתלבשו נשמות בגופים, אך כאן שאומר מכל חיי עוה\"ב הוראות לשונו כל מיני חיי עוה\"ב שיש והוא על ב' אופנים, א' חיי הנפש בלתי גוף, ב' שהנפש יתלבש בגוף והגוף יהי' נזון מרוחניות והוא שיקבל חיות מא\"ס הסוכ\"ע שגם עתה עיקר החיות מא\"ס הסוכ\"ע דעיקר התהוות מציאות היש מבחי' סוכ\"ע<sup data-n=\"3049\">8</sup> וכמבואר זה במ\"א באריכות (ה' בד\"ה תולדות נח ל\"ז<sup data-n=\"3050\">7</sup> ע') וא\"כ גדלה הקושי' מאחר דעצם עשיות המצוה יפה",[["3043","1","<b>יפה שעה א'</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הג' מהמשך יונתי (פ\"ח — פ\"י) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: ועפ\"ז כו' נרי בידך].\nהנחה אחרת מדרוש זה נדפסה לקמן (בחלק הנחות).\nמאמר זה (כנראה) נזכר לקמן בד\"ה אני לדודי הב' על יד הערה 32 (ושם: ד\"ה ואהבת). על יד הערה 54. 56.\nבמאמר זה להלן על יד הערה 93 עה\"ג בא ציון."],["3044","2","<b>יפה שעה א'. . עוה\"ב</b>: אבות פ\"ד, מי\"ז [ושם: העוה\"ב ראה גם לקמן הנחה ד\"ה זה הב']. ראה גם המשך וככה תרל\"ז רפ\"ט."],["3045","3","<b>ואיך</b>: אוצ\"ל: איך."],["3046","4","<b>כל ישראל. . לעוה\"ב</b>: סנהדרין ר\"פ חלק (צ, א)."],["3047","5","<b>לעולם ירשו ארץ</b>: ישעי' ס, כא [ושם: יירשו]. ראה לקו\"ת ואתחנן ט, א."],["3048","6","<b>הפלוגתא דהרמב\"ם והרמב\"ן</b>: ראה רמב\"ם הל' תשובה פ\"ח, ה\"ב. פיה\"מ ר\"פ חלק. (אגרת) מאמר תחיית המתים. רמב\"ן בסוף שער הגמול. תשובות וביאורים (קה\"ת תשל\"ד) סי\"א ע' 57 הערה 23."],["3049","8","<b>דעיקר התהוות מציאות היש מבחי' סוכ\"ע. ֿ. תולדות נח ל\"ז</b>: פי\"ח. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם ובהערה 48."],["3050","7","<b>והגוף יהי' נזון מרוחניות. . תולדות נח ל\"ז</b>: פי\"ח — לא נדפס לע\"ע. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540369\" data-slug=\"torat-chaim\" data-id=\"2300540369\">תו\"ח שמות ח\"א מ, ב</a>. המשך וככה תרל\"ז פ\"ה (ע' ז). סה\"מ תרכ\"ט ע' כב. וש\"נ. תרל\"ב ח\"א ע' קכא. וש\"נ. תשובות וביאורים שם ס\"ג ע' 12."]]],[2000480325,"מהשכר אפי' דעולם התחי' והלא ארז\"ל אין הקב\"ה מקפח שכר<sup data-n=\"3051\">9</sup> כל ברי' ולפ\"ז מהו השכר.\n<b>והנה</b> צלה\"ק תחילה מה שא' במדרש ע\"פ ראה אנכי נותן<sup data-n=\"3052\">11</sup> כו' וסיום דפרשה עקב הוא כי אם שמר תשמרון<sup data-n=\"3053\">12</sup> ומה הסמיכות כו' ד\"א נרי בידך ונרך בידי<sup data-n=\"3054\">10</sup> אם אתה משמר את תורתי אני משמר אותך, נרי הוא כי נר מצוה<sup data-n=\"3055\">13</sup> ותורה אור, ונרך בידי הוא נר ה' נשמות אדם<sup data-n=\"3056\">14</sup> וע\"י שמור דתומ\"צ אני משמר כו' וצ\"ל והלא אנו אומרים בנוסח אלהי נשמה כו' ואתה משמרה בקרבי וא\"כ מהו השימור שע\"י המצות. והנה צ\"ל תחילה ענין ירידות הנשמה בגוף לכאו' הוא ירידה גדולה ועצומה דהנשמה קודם התלבשותה בגוף כתי' חי הוי' אשר עמדתי לפניו<sup data-n=\"3057\">15</sup> וכמ\"ש גבי מלאכים ויעמידם לעד לעולם<sup data-n=\"3058\">16</sup> וכן שרפים עומדים<sup data-n=\"3059\">17</sup> היינו שעומדים בביטל לאלקות ושרשם מחיצוניות הכלים וכ\"ש הנשמה ששרשה מפנימיות הכלים<sup data-n=\"3060\">18</sup> עמדה תמיד באהוי\"ר כמו שהם בבחי' לפניו וירדה למטה בגוף ונה\"ב לבד שהוא מעלים ומסתיר, הרי אף שנתעורר באהוי\"ר אינו בדמיון וערך כמו שהי' קודם התלבשותה בגוף, ואף גם זאת הנה\"ב מעלים ומסתיר שלא בכל העתים אפשר להתעורר באהוי\"ר והלואי יהי' שבה למעליותא כמו שהי' קודם וכל הדרכים בחזקת סכנה<sup data-n=\"3061\">19</sup>, אלא מוכרח לומר שאף דנדמה לנו שהאהוי\"ר אינו בערך לגבי אהוי\"ר שקודם כו' מ\"מ כדאי בשביל זה לירד למטה בגוף ונה\"ב.\n<b>והענין</b> הוא דהנה עיקר ברה\"ע הי' בשביל קיום תומ\"צ וכמ\"ש בראשית ברא אלקי' ומקשים מהו בראשית אלא בשביל ישראל שנק' ראשית ובשביל התורה<sup data-n=\"3062\">20</sup> שנק' ראשית (ה' ע' בתו\"ח בד\"ה בראשית ב'<sup data-n=\"3063\">21</sup> ע'), וכ\"ה בכמה מקומות עשרה עשרה הכף בשקל הקודש<sup data-n=\"3064\">22</sup> עה\"ד מכוונים כנגד ע\"מ<sup data-n=\"3065\">23</sup>, אם לא בריתי<sup data-n=\"3066\">24</sup>",[["3051","9","<b>אין הקב\"ה מקפח שכר</b>: ב\"ק לח, ב."],["3052","11","<b>ראה אנכי נותן</b>: פ' ראה יא, כו."],["3053","12","<b>כי אם שמר תשמרון</b>: עקב יא, כב."],["3054","10","<b>במדרש ע\"פ ראה. . נרי בידך ונרך בידי</b>: ראה דב\"ר פ\"ד, ד."],["3055","13","<b>כי נר מצוה</b>: משלי ו, כג."],["3056","14","<b>נר ה' נשמות אדם</b>: משלי כ, כז [ושם: נשמת — ראה גם לקמן הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 107]."],["3057","15","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח סב, סע\"ד</a>. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["3058","16","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["3059","17","<b>שרפים עומדים</b>: ישעי' ו, ב. ראה סוטה לט, א (צויין אליו ב) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380390\" data-slug=\"likkutei-torah\" data-id=\"4001380390\">לקו\"ת נשא כ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380398\" data-slug=\"likkutei-torah\" data-id=\"4001380398\">כב, ג</a>."],["3060","18","<b>מחיצוניות הכלים. . מפנימיות הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540226\" data-slug=\"torat-chaim\" data-id=\"2300540226\">תו\"ח בשלח ח\"א רמ, ד</a> ואילך."],["3061","19","<b>וכל הדרכים בחזקת סכנה</b>: ירושלמי ברכות פ\"ד, ה\"ד. קה\"ר ג, ב (ב)."],["3062","20","<b>בראשית ברא. . ישראל. . התורה</b>: בראשית א, א. ראה רש\"י בראשית א, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670527\" data-slug=\"torat-chaim\" data-id=\"2300670527\">תו\"ח בראשית מד, א</a> הערה 6."],["3063","21","<b>בתו\"ח בראשית ב'</b>: ראה שם ז, א ואילך."],["3064","22","<b>עשרה עשרה הכף בשקל הקודש</b>: נשא ז, פו."],["3065","23","<b>עה\"ד מכוונים כנגד ע\"מ</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. לקו\"ת חוקת נז, סע\"ג ואילך בשם המגיד. מאמרי אדה\"א דברים ח\"א ע' רפ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540769\" data-slug=\"torat-chaim\" data-id=\"2300540769\">תו\"ח וארא ח\"א פא, ג</a> ובהערה 636. סה\"מ תרל\"ח ע' ע. וש\"נ. סה\"מ מלוקט ד' ע' פ ואילך."],["3066","24","<b>אם לא בריתי</b>: ירמי' לג, כה. ראה שבת לג, א."]]],[2000480326,"יומם ולילה חוקות שמו\"א לא שמתי תנאי התנה הקב\"ה<sup data-n=\"3067\">25</sup> במע\"ב אם יקיימו ישראל את תורתי מוטב וא\"ל יחזיר העולם לתהו ובוהו, אלה תולדות השו\"א בהבראם<sup data-n=\"3068\">26</sup> אלה בזכות מי כו' בזכות אלה שמות בנ\"י<sup data-n=\"3069\">27</sup> ואלה בזכות מי כו' בזכות אלה העדות והחקים והמשפטים<sup data-n=\"3070\">28</sup>, ומקרא מלא כתי' אנכי עשיתי ארץ<sup data-n=\"3071\">29</sup> ואדם עליה בראתי ומהו הסיפור, ור\"ל מה שנשפל מאנכי מי שאנכי<sup data-n=\"3072\">30</sup> שיהי' ארץ בחי' עשי' הוא בשביל האדם שהוא בחיר שבנבראים<sup data-n=\"3073\">31</sup> וכל העולם לא נברא אלא לצוות לזה, וענין לז\"ה הוא כמ\"ש סוף דבר כו' כי ז\"ה כל האדם<sup data-n=\"3074\">33</sup>, וזהו לצוות לזה שכל הדברים יתאחדו עם האדם<sup data-n=\"3075\">32</sup> והוא יבררם ע\"י בראתי בגימ' תרי\"ג<sup data-n=\"3076\">34</sup> ע\"י תרי\"ג מצות<sup data-n=\"3077\">35</sup>, הרי עיקר ברה\"ע הוא בשביל קיום תומ\"צ, וצ\"ל מהו\"ע המצות, הנה המצות הם למעלה מטו\"ד דאפי' אותן המצות שיש להם טו\"ד הוא על עצם עשיית המצוה שלא יהיו חוקה שא\"י כלל טעמה משא\"כ מצות אלו יודעין טעמם, אבל מפני רצונו<sup data-n=\"3078\">36</sup> ית' שזה יהי' מצוה זה אין יודעין, ואפי' מצות שנא' עליהם הטעם בתורה וכמ\"ש כי בסוכות הושבתי<sup data-n=\"3079\">37</sup> את בנ\"י וכן מצה ע\"ש החפזון<sup data-n=\"3080\">38</sup> מצה זו<sup data-n=\"3081\">39</sup> מזה יודעין האיך לעשות המצוה אבל מפני מה רצונו שסוכה וכמו\"כ מצה יהי' מצוה זה אינו מובן, ואם נא' שהוא רק זכירה על הנעשה לבד שאינו שייך לומר כן, זה גופא צ\"ל למה עשה כן במקריים הזמן שצריכים זכירה עליהם (בפ\"א<sup data-n=\"3082\">40</sup> ואפי' אותן מצות שארז\"ל אלמלי לא ניתנה<sup data-n=\"3083\">41</sup>",[["3067","25","<b>תנאי התנה הקב\"ה</b>: כ\"ה בכ\"מ ומהם: מאמרי אדה\"א בראשית ע' קמ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670135\" data-slug=\"torat-chaim\" data-id=\"2300670135\">תו\"ח בראשית ב, ד</a> הערה 37. סה\"מ מלוקט ד' ע' שכו — ראה שבת פח, א. לקמן (בחלק הנחות) בהנחה יפה שעה הא' כאן על יד הערה 26 [ושם: במד\"ר]."],["3068","26","<b>אלה תולדות השו\"א בהבראם</b>: בראשית ב, ד [ושם: והארץ]. ראה שמו\"ר פמ\"ח, [ב]."],["3069","27","<b>אלה שמות בנ\"י</b>: שמות א, א [ושם: ואלה — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואלא עלמא אמאי קאים ובהערה 17]."],["3070","28","<b>אלה העדות והחקים והמשפטים</b>: ואתחנן ד, מה."],["3071","29","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["3072","30","<b>מאנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["3073","31","<b>האדם שהוא בחיר שבנבראים</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ו. וש\"נ."],["3074","33","<b>סוף דבר. . האדם</b>: קהלת יב, יג."],["3075","32","<b>וכל העולם. . לצוות לזה. . יתאחדו עם האדם</b>: ראה ברכות ו, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה על יד הערה 94 ואילך."],["3076","34","<b>בראתי בגימ' תרי\"ג</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואלא עלמא אמאי קאים הערה 22 מהרמ\"ז והה\"מ."],["3077","35","<b>תרי\"ג מצות</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261512\" data-slug=\"likkutei-sichot\" data-id=\"1300261512\">לקו\"ש יתרו כרך כו ס\"ע 424</a> ואילך. אג\"ק שלו ח\"ג ע' רג."],["3078","36","<b>מפני רצונו</b>: אוצ\"ל: מפני מה רצונו."],["3079","37","<b>כי בסוכות הושבתי</b>: אמור כג, מג."],["3080","38","<b>מצה ע\"ש חפזון</b>: פ' ראה טז, ג."],["3081","39","<b>מצה זו</b>: נוסח ההגדה."],["3082","40","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."],["3083","41","<b>אלמלי לא ניתנה תורה</b>: ערובין ק, ב. ראה גם לקו\"ש יתרו כרך ג ע' 890 הערה 12. חוקת כרך ח ע' 130 ואילך ובהערה 49. כ\"ד טבת כרך כא ע' 284."]]],[2000480327,"תורה למדנו צניעות מחסודה<sup data-n=\"3084\">42</sup> כו' ג\"ז צ\"ל למה ברא מין ב\"ו<sup data-n=\"3085\">43</sup> במדה זו), סוף דבר המצות הם למעלה מטו\"ד, ואם נא' שהוא צורך גבוה<sup data-n=\"3086\">44</sup> אנת הוא שלימותא דכולא<sup data-n=\"3087\">45</sup>, ובאמת ארז\"ל מה איכפת לו להקב\"ה אם שוחט מן העורף או שוחט מן הצואר ר\"ל שאינו נוגע לו כלל וכל מצותיך צדק<sup data-n=\"3088\">47</sup>, שהם צדקה, ולא נתנו המצות אלא לצרף בהם את הבריות<sup data-n=\"3089\">46</sup> ומבואר במ\"א באריכות (ה' ד\"ה מים רבים ל\"ו ע') דהנה\"א אינו שייך לקראו נברא דאפי' נפש דמל' דמל' דעשי' אי' בסש\"ב<sup data-n=\"3090\">49</sup> שבתוכו מלובש חכ' דעשי' כו' חכ' דאצי' שבו שורה אוא\"ס, אלא בריות הם הנה\"ב<sup data-n=\"3091\">48</sup> וגם הגוף הוא נברא, וכמו גוף האדם קודם שנפח בו נפ\"ח הי' מציאות נברא, ועיקר הכוונה הוא לברר את הנה\"ב ובשביל זה כדאי ירידת הנשמה בגוף אף שהוא מסוכן וכמו עד\"מ אבנים יקרים שאין חופרין אותם בארץ אלא נמצאים בקרקע הים ויורדים בים בתיבה<sup data-n=\"3092\">50</sup> כו' ויש בזה סכנות גדולות מ\"מ כשמוציא האבן יקר כדאי לו הסכנה, כמו\"כ יובן כאן אף שכל הדרכים בחזקת סכנה אך כדי שיברר את הנה\"ב כדאי הירידה דע\"י מתעלה הנה\"א ג\"כ וכמ\"ש רוח בנ\"א היא העולה למעלה<sup data-n=\"3093\">51</sup>, אף שיש בו כח מעצמו לעלות למעלה, אין ר\"ל שהוא עולה רק שיש בו כח לעלות, וההפרש בין מי שיש בו כח לעלות או שאין בו כח לעלות הוא, דמי שאין בו כח לעלות א\"א לעלות כ\"א לפ\"ע המקיף וכמו אבן שטבעו לירד למטה וכשזורקין אותו עולה לפ\"ע כח מקיף היד, אבל מי שיש בו כח לעלות יכול לעלות עד למעלה מעלה, אבל ההעלאה היא ע\"י בירור נה\"ב.\n<b>וביאור</b> הענין דהנה אנו אומרים אלהי נשמה שנתת בי טהורה היא אתה בראת כו' הנה קריאת שם טהורה שייך על דבר נברא וצ\"ל כשאו' אתה בראת",[["3084","42","<b>מחסודה</b>: כ\"ה בגוכתי\"ק."],["3085","43","<b>ב\"ו</b>: אולי כ\"ה בגוכתי\"ק."],["3086","44","<b>שהוא צורך גבוה</b>: ראה עבודת הקודש בהקדמה. חלק העבודה פ\"א ואילך. של\"ה (שער הגדול) כט, ב ואילך. לא, ב<sup data-n=\"e259\">א</sup>. לג, סע\"ב<sup data-n=\"e260\">ב</sup>. (בעשרה מאמרות מאמר ד) נב, ב. אוה\"ת משפטים ס\"ע א'ריט ואילך. איוב כרך א ע' תרעט. סה\"מ תרל\"ג ח\"ב ע' תכט (בהערה בסופה). ע' תל ואילך. תרפ\"ט ע' 129. וש\"נ."],["3087","45","<b>אנת הוא שלימותא דכולא</b>: ראה ת\"ז בהקדמה יז, ב."],["3088","47","<b>וכל מצותיך צדק</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 39."],["3089","46","<b>מאי איכפת. . לצרף בהם את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד."],["3090","49","<b>נפש דמל' דמל' דעשי' אי' בסש\"ב</b>: ראה פי\"ח. ראה גם לקמן על יד הערה 58. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 11."],["3091","48","<b>ד\"ה מים רבים ל\"ו. . בריות הם הנה\"ב</b>: פק\"י ע' קטו. ראה גם לעיל (בחלק המאמרים) המשך יונתי כאן ובהערה 204."],["3092","50","<b>אבנים. . בים בתיבה</b>: ראה גם המשך מים רבים תרל\"ו בתחלתו סע\"ב ואילך. לקמן (בחלק הנחות) הנחה יפה שעה הא' כאן על יד הערה 21."],["3093","51","<b>רוח בנ\"א היא העולה למעלה</b>: קהלת ג, כא [ושם: מי יודע רוח בני האדם העולה היא למעלה — ראה גם ש\"א י, ב הערה 36].\n\n<b>א</b>  באוה\"ת איוב (שבפנים ההערה): והאריך עד דף ל\"ה.\n\n<b>ב</b>  ושם: ושטת בעל עבודת הקודש בכל ספרו בכמה מקומות שהעבודה לצורך גבוה."]]],[2000480328,"כו' קודם הבריאה איך שייך לומר טהורה<sup data-n=\"3094\">52</sup>, והענין דהנה כל הנוסחאות תקנו אנשי כנסה\"ג<sup data-n=\"3095\">53</sup> ולא מעצמם אלא קבלה איש מפי איש כו' וא\"כ נוסח דאלקי נשמה אמרו מרע\"ה<sup data-n=\"3096\">54</sup> ג\"כ, וידוע שיש בנשמות ב' מדרי' וכמ\"ש וזרעתי את בנ\"י<sup data-n=\"3097\">56</sup> זרע אדם וזרע בהמה, זרע אדם נשמות דאצי' וזרע בהמה<sup data-n=\"3098\">55</sup> נשמות דבי\"ע, וא\"כ אפי' נשמות הגבוהות נש' דאצי' אמרו נוסח זה, ולכאו' מה שאמר טהורה היא ניחא, אך איך אמרו בראת, וצ\"ל דאפי' נשמה דאצי' כשצריכי' לירד למטה להחיות גוף גשמי צריכה לעבור ע\"י בחי' בראת כו' (ה' י\"ל רק בדרך מעבר<sup data-n=\"3099\">57</sup> משא\"כ נשמות דבי\"ע ע') ואפי' נשמות דבריאה אף שאי' בת\"ז לבושין תקינת לון<sup data-n=\"3100\">58</sup> דמנייהו פרחין נשמתין לב\"נ רק פרחין אבל שרשן באצי' וכמ\"ש בסש\"ב דבחכ' מלובש<sup data-n=\"3101\">59</sup> חכ' דאצי' כו', וענין טהורה היא הנה שם טהור הוא שאין עליו שום דבר החוצץ<sup data-n=\"3102\">60</sup> ולא שום מעלים ומסתיר, והנה בטהורה יש כמה פי', והפי' היותר נעלה במדרי' מכולם שהוא טה\"ע<sup data-n=\"3103\">61</sup> וזהו שכ' בסש\"ב שבו שורה<sup data-n=\"3104\">62</sup> אוא\"ס הכוונה על טה\"ע ששם שורש הנשמות, והנה מבואר במ\"א (ה' ד\"ה גן נעול, מצה זו מ\"ם<sup data-n=\"3105\">63</sup> ע') דרשימה הוא אור שלא נגע בו הצמצום והגם דבאותיות הרשימה נגע הצמצום הוא רק בפעולת האותיות, ואף גם בפעולת האותיות הי' הצמצום בהאור אבל לא בהאותיות ולכן יש בכח האותיות לגלות השכל, והמגלה צ\"ל למעלה מדבר שמגלה והיינו מפני שלא נגע בהם הצמצום כלל, ומבואר במ\"א דהעלי' הוא מגרמוהי לחיוהי<sup data-n=\"3106\">64</sup>, ומאחר ששרש הנשמות מטה\"ע (בפ\"א מפנימיות הכלים) מהו העלי' שמתעלה להאור.",[["3094","52","<b>אלהי נשמה. . בראת. . טהורה</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 92."],["3095","53","<b>כל הנוסחאות תקנו אנשי כנסה\"ג</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר רסמ\"ו. מאמרי אדה\"ז תקס\"ג ח\"א ע' קכד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540273\" data-slug=\"torat-chaim\" data-id=\"2300540273\">תו\"ח וארא ח\"א עד, א</a>."],["3096","54","<b>אנשי כנסה\"ג. . אמרו מרע\"ה</b>: ראה גם לעיל (בחלק המאמרים) בההמשך כאן ובהערה 208."],["3097","56","<b>וזרעתי את בנ\"י</b>: ירמי' לא, כו [ושם: ב\"י. בדילוג — ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560173\" data-slug=\"or-hatorah-hb\" data-id=\"8316560173\">אוה\"ת בראשית כרך ג ע' תקנג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> הערה 627]."],["3098","55","<b>בנשמות. . זרע אדם. . זרע בהמה</b>: ראה תו\"א ותו\"ח ר\"פ משפטים. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 29."],["3099","57","<b>בדרך מעבר</b>: ראה גם (בענין מעבר והתלבשות) מאמרי אדה\"א קונטרסים ע' תקלג ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940046\" data-slug=\"or-hatorah-hb\" data-id=\"8159940046\">אוה\"ת שמיני כרך ב ע' תסב</a> ואילך. סה\"מ תרכ\"ז ע' קיז. וש\"נ."],["3100","58","<b>לבושין תקינת לון</b>: ת\"ז בהקדמה יז, א."],["3101","59","<b>דבחכ' מלובש</b>: כ\"ה בגוכתי\"ק."],["3102","60","<b>טהורה. . החוצץ</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 193."],["3103","61","<b>בטהורה. . טה\"ע</b>: ראה גם לקמן בפנים בין הערות 112-113. מאמרי אדה\"א דברים ח\"ב ס\"ע תנח ואילך. שע\"ת ל, ב ובהערה 17. סה\"מ תרל\"ח ע' ערה. וש\"נ."],["3104","62","<b>שבו שורה</b>: בתניא שם: שבה מאיר."],["3105","63","<b>ד\"ה גן נעול, מצה זו מ\"ם</b>: ראה גם לעיל (בחלק המאמרים) בההמשך כאן על יד הערה 212 שמציין: בד\"ה אז ישיר שבמאמר מצה זו — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר<sup data-n=\"e261\">ג</sup> על יד הערה *39 ואילך."],["3106","64","<b>דהעלי' הוא מגרמוהי לחיוהי</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370316\" data-slug=\"torah-or\" data-id=\"3901370316\">תו\"א יתרו עא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370321\" data-slug=\"torah-or\" data-id=\"3901370321\">עב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380599\" data-slug=\"likkutei-torah\" data-id=\"4001380599\">לקו\"ת בלק ע, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">פ' ראה כז, א</a> ואילך. יוה\"כ ע, ג.\n\n<b>ג</b>  וראה שם בהערה 1."]]],[2000480329,"<b>והנה</b> להבין זה צ\"ל תחילה מ\"ש איהו וחיוהי חד ואיהו וגרמוהי חד<sup data-n=\"3107\">65</sup> ומובן מזה שהם בחי' מחולקים דאל\"כ הול\"ל איהו וחיוהי וגרמוהי חד, דהנה איהו וגרמוהי אי' באגה\"ק<sup data-n=\"3108\">66</sup> שהוא מה שאיהו מתיחד עם חיוהי<sup data-n=\"3109\">68</sup> לברוא מאין ליש, וענין בריאה יש מאין הוא בחיק הבורא ולא בחיק הנבראים שה\"ה בעצמו נברא, וגם אינו בחיק גרמוהי בלא בחי' איהו<sup data-n=\"3110\">69</sup> איך שיפורש בחי' גרמוהי הן כמו שמפרש בע\"ח ואגה\"ק שהם כלים דע\"ס, והן כמו שמפרש בזהר מפרשי הזהר שהם ז\"ת<sup data-n=\"3111\">70</sup> ונכלל בהם האור ג\"כ מ\"מ א\"י לברוא מאין ליש אלא מצד כח האיהו, משא\"כ בחי' איהו וחיוהי חד הוא שאינו שייך כלל למציאות היש, וצ\"ל שבחי' איהו שמתיחד עם חיוהי הוא למעלה במדרי' מבחי' איהו שמתיחד עם גרמוהי דאם נא' שההפרש הוא רק באופני היחוד הול\"ל איהו וחיוהי וגרמוהי חד ומובן מאחר שמובדלים בשמותיהן הם מובדלים במדריגתם וא\"כ היחוד עם חיוהי הוא באו\"א כו' דנ\"מ עם מי שמתיחדים אלא מוכרח לומר שהם מדריגות חלוקות הגם דא\"ס הוא אחדות פשוטה, היא הנותנת מפני שהוא אחדות פשוט הרי יש בו הכל, והנה צ\"ל תחילה ענין איהו וגרמוהי חד שכ' באגה\"ק<sup data-n=\"3112\">67</sup> שהוא מה שאיהו מתיחד עם גרמוהי לברוא מאין ליש שיהי' מציאות דבר נפרד הגם שאינו דבר נפרד מאלקות אין לך דבר שחוץ ממנו ואין עוד מלבדו כתי' אפי' בחללו ש\"ע<sup data-n=\"3113\">71</sup> וכתי' את השמים ואת הארץ אני מלא<sup data-n=\"3114\">72</sup> כמו שקודם הצמצום הי' אוא\"ס ממלא כל מקום<sup data-n=\"3115\">73</sup> החלל<sup data-n=\"3116\">74</sup> כמו\"כ לאחר הצמצום את השמים ואת הארץ אני מלא, אני ר\"ל עצמות אוא\"ס וענין הצמצום הוא רק שנתעלם האור, וא\"כ אינו שייך לומר דבר נפרד ולכן מבואר במ\"א שהעולם הוא שקר גמור<sup data-n=\"3117\">75</sup> אך לפ\"ז מהו\"ע ברה\"ע, אבל עכ\"פ אינו נפרד אלא שנראה לנו כמו שהוא נפרד, והוא ע\"י התהוות איהו שמתיחד עם גרמוהי.\n<b>וביאור</b> הענין יובן מהנפש המחי' הגוף, דמוכרח לומר שיש נפש המחי' את הגוף הגם שא\"י מהו הנפש דגלוי הנשמה הוא למעלה מג\"א ומרוה\"ק<sup data-n=\"3118\">76</sup>, והאר\"י",[["3107","65","<b>איהו וחיוהי. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב. לעיל (בחלק המאמרים) בההמשך כאן הערה 216."],["3108","66","<b>איהו וגרמוהי אי' באגה\"ק</b>: ד\"ה איהו וחיוהי ס\"כ (תניא קכט, ב. קל, ב)."],["3109","68","<b>חיוהי</b>: אוצ\"ל: גרמוהי."],["3110","69","<b>אינו בחיק גרמוהי בלא בחי' איהו</b>: ראה סה\"מ תרל\"ח ע' ד."],["3111","70","<b>גרמוהי. . בע\"ח ואגה\"ק שהם כלים. . בזהר מפרשי הזהר שהם ז\"ת</b>: ראה גם סה\"מ תרל\"ג ח\"ב ע' תלה ובהערה שם. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 100. (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 52."],["3112","67","<b>באגה\"ק</b>: אולי כ\"ה בגוכתי\"ק."],["3113","71","<b>ואין עוד מלבדו</b>: ואתחנן ד, לה. ראה דב\"ר פ\"ב, (כוכז) כח. המשך תרל\"ו פי\"ב ואילך."],["3114","72","<b>את השמים. . מלא</b>: ירמי' כג, כד."],["3115","73","<b>שקודם הצמצום. . ממלא כל מקום החלל</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["3116","74","<b>ממלא כל מקום החלל</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 215."],["3117","75","<b>שהעולם הוא שקר גמור</b>: ראה גם לעיל המשך מצה זו שם ובהערה 1454."],["3118","76","<b>דגלוי הנשמה. . מג\"א ומרוה\"ק</b>: ראה שע\"ק להרח\"ו ח\"ג, ש\"ה וש\"ז. מאמרי אדה\"א דברים ח\"ב ע' תצא. וש\"נ. ח\"ד ריש ע' א'תפט. וש\"נ. דרושי חתונה ח\"א ע' קפב. הנחות תקע\"ז ע' שה. וש\"נ. סה\"מ תרל\"ח ע' שצו. וש\"נ. לקמן הנחה ד\"ה ובחודש השביעי הב' על יד הערה 89."]]],[2000480330,"זכה לזה ע\"י שמחה ש\"מ<sup data-n=\"3119\">77</sup> אבל זה עכ\"פ ודאי שיש נפש המחי' את הגוף, דהרי הגוף יחי'<sup data-n=\"3120\">78</sup> ובצאת הנפש עם הגוף<sup data-n=\"3121\">*79</sup> ה\"ה נשאר כאבן דומם תמורת שהי' תחילה בע\"ח, ומ\"מ מוכרח לומר שאפי' בצאת הנפש מן הגוף יש בו חיות<sup data-n=\"3122\">79</sup> לבד הקיסטא דחיותא<sup data-n=\"3123\">80</sup> שהוא בשביל ההרגש וכמ\"ש ונפשו עליו תאבל<sup data-n=\"3124\">81</sup> וכמארז\"ל קשה רמה למת<sup data-n=\"3125\">82</sup> כו' וכן הפלוגתא שבגמ' אם יודעים ואם לא יודעים<sup data-n=\"3126\">83</sup> זה מצד הקיסטא דחיותא שנשאר מהנפש המחי' את הגוף, לבד זאת מה שקיים תמונת הגוף הוא מצד החיות שמחי' אותו לבד, וכמו גופו של אדה\"ר הי' מציאות קודם שנפח באפיו נ\"ח א\"כ מוכרח לומר שיש לו חיות, וכמו כשחותכין עץ הרי מהות העץ הוא כמו שהי' קודם רק שאין בו כח ההרגש מפני שאין נפש צומחת שפועלת הצמיחה מקטנות לגדלות והוא מתיבש שאין בו רטיבות שהוא מצד הנפש הצומחת אבל מהות העץ הוא כמו שהי' קודם עד שנרקב דאז הוא שב לעפר ונפרדים ממנו הד' יסודות, אבל כ\"ז שיש בו הד' יסודות יש בו כח המחבר אותם (ה' שהוא כח אחר מעורב בהם, ולכן אין להעץ שום תמונה מא' מהד' יסודות ע') וכן כששורפי' העץ ויוצאים ממנו הג' יסודות ונשאר יסוד העפר<sup data-n=\"3127\">84</sup> באפר שהוא ג\"כ עפר<sup data-n=\"3128\">85</sup> שכשר כמו עפר<sup data-n=\"3129\">86</sup> שהוא מצמיח אבל מ\"מ אינו דומה לעפר וזהו שכ' ואנכי עפר ואפר<sup data-n=\"3130\">87</sup> ואם נא' שהם דבר א' מהו הכפל ל' אלא שעפר הוא שיש בו כל הד' יסודות, ואפר הגם שיש בו ד' יסודות אבל הם מחולקים ואפשר לחלק עוד ועוד עד שלא יהי' שום מציאות כלל, וכ\"ז כשנפרדים הד' יסודות אבל כשיש בו הד' יסודות יש בו הכח המרכיב. וכמו\"כ יובן בגוף האדם שיש בו חיות המחי' אותו. וזהו מכח האיהו שמתיחד עם גרמוהי לברוא בהם וע\"י מציאות היש, היינו עצם ההתהוות מציאות היש הוא מבחי' איהו, וגרמוהי הוא כדי שיהי' התחלקות זה יהי' באופן זה וזה יהי' באופן אחר והוא כמו שעושין כלי בצב<sup data-n=\"3131\">88</sup> שהעיקר הוא האדם העושה וכמו המכה בפטיש על הסדן, אבל איהו וחיוהי חד, הנה חיוהי אינו שייך למציאות היש איך שיפורש ענין חיוהי הן כפי' הזהר שהם חב\"ד",[["3119","77","<b>והאר\"י. . שמחה ש\"מ</b>: ראה גם המשך מים רבים תרל\"ו ע' רג<sup data-n=\"e262\">ד</sup>. ח\"ב ריש ע' תקיב. סה\"מ תרל\"ח ע' שצו וע' תלד. וראה גם מאמרי אדה\"א נ\"ך ע' כז. וש\"נ."],["3120","78","<b>יחי'</b>: אוצ\"ל: חי."],["3121","*79","<b>עם הגוף</b>: אוצ\"ל: מהגוף."],["3122","79","<b>בצאת הנפש מן הגוף יש בו חיות</b>: ראה גם לעיל (בחלק המאמרים) בההמשך כאן ובהערה 223."],["3123","80","<b>הקיסטא דחיותא</b>: ראה לעיל בההמשך כאן ובהערות 224-225."],["3124","81","<b>ונפשו עליו תאבל</b>: איוב יד, כב."],["3125","82","<b>קשה רמה למת</b>: ברכות יח, ב. שבת יג, ב."],["3126","83","<b>הפלוגתא שבגמ' אם יודעים אם לא יודעים</b>: ועד\"ז הובא לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 91 (ושם: ”כמארז\"ל מתים\"). ראה גם ברכות יח, א — יט, רע\"א. תוד\"ה אבותי סוטה לד, ב."],["3127","84","<b>כששורפי' העץ ויוצאים ממנו הג' יסודות. . העפר</b>: ראה גם אגה\"ק סט\"ו. סה\"מ תרל\"ח ע' רצו. וש\"נ."],["3128","85","<b>באפר שהוא ג\"כ עפר</b>: ראה גם ש\"א מז, ב."],["3129","86","<b>באפר. . שכשר כמו עפר</b>: ראה חולין פח, ב. תוד\"ה מצינו שם. שו\"ע יו\"ד הל' שחיטה סכ\"ח, סכ\"ג. תו\"א וישלח כו, רע\"ד. לקמן הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 46."],["3130","87","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["3131","88","<b>בצב</b>: אולי צ\"ל: בצבת.\n\n<b>ד</b>  ושם: ”וכמ\"ש במ\"א בד\"ה כל העוסק בתורה בלילה שהאר\"י ז\"ל זכה לזה ע\"י בחי' שמחה של מצוה\"."]]],[2000480331,"הנה הוא וחכ' ובינתו ודעתו א'<sup data-n=\"3132\">89</sup> ומאחר שהוא אחד אינו שייך לומר נפרד, אף שא' הוא וחכ' והם מדרי' חלוקים חכ' ובינתו ודעתו ובדעת גופא יש ג\"כ מדרי' ידיעת השלילה<sup data-n=\"3133\">90</sup>, וכמ\"ש והאדם ידע<sup data-n=\"3134\">91</sup> שהוא השפעה עצמיות ה\"ז כמו כחות הנפש שהם מחולקי' ובעצם הנפש אינו שייך לחלוק כחות אלו ומ\"מ כלולים בו כל הכחות והוא בחי' עקודים שהע\"ס עקודים בכלי א'<sup data-n=\"3135\">92</sup> הרי עשר ומ\"מ הם בכלי אחד, וא\"כ א\"ז נפרד, וכן לפי' הע\"ח ואגה\"ק שהם האורות הנה שם אור לא נשתנה כמו שקודם הצמצום הי' אוא\"ס ממלא מקום החלל כמו\"כ לאחר הצמצום מה שנמשך המשכת הקו הוא אוא\"ס (תו\"א לקו\"ת ביאור שוש אשיש)<sup data-n=\"3136\">93</sup> דמה שאומרים א\"ס אין הכוונה על א\"ס עצומ\"ה דשם אינו שייך לדבר כלל כ\"א הכוונה על או\"ר א\"ס ומה שנק' או\"ר הוא להורות שאינו פועל שינוי בהמאור<sup data-n=\"3137\">94</sup> ולכן אני ה' לא שניתי<sup data-n=\"3138\">95</sup> שלא יש שום שנוי בין קודם הבריאה לאחר הבריאה אתה הוא קודם שנברה\"ע<sup data-n=\"3139\">96</sup> ואתה הוא לאחר שנברה\"ע דכללות השתל' הוא רק משם והארה בעלמא שאינו נוגע לעצמיות וכמו בעצם השמש אינו פועל שום שינוי באם מאיר לארץ ולדרים עלי' וא\"ל כו' לכן נק' אור, אבל שם אור לא נשתנה, וזהו נק' חיוהי.\n<b>וביאור</b> הענין הנה מחו\"ד שניהם מלבושי הנפש, אך דיבור הוא רק לצורך זולתו דלגבי עצמו א\"צ לדיבור כלל דיכול לחשוב וכמה שיחשוב לא יודע האחר מה הוא מחשב רק יודע שהוא מחשב, אבל דיבור א\"צ לצורך עצמו (מעשה צריך האדם לצורך עצמו) רק כשצריך לומר שכל לזולתו אומר לו בדיבור וכן כשצריך שישמש לו זולתו אך הכל לצורך זולתו, רק הנ\"מ לזולתו לצורך עצמו כמו שישמש או לזולתו לצורך זולתו, אבל הכל לזולתו, משא\"כ ענין המח' הוא גלוי העלם העצמי לגבי עצמו דכשלומד איזה דבר הלכה ונופל לו ברק המבריק<sup data-n=\"3140\">97</sup> עדיין אין לו בו שום השגה רק כשמחשב באותיות המח' מביא אותו לידי השגה והבנה, ותיכף כשנפל לו הברק המבריק אם יבלבלנו א' ולא יחשוב בזה תיכף הרי נשכח הברק המבריק",[["3132","89","<b>הוא וחכ' ובינתו ודעתו א'</b>: לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 99: אמרו רז\"ל. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"י. שער היחוד והאמונה פ\"ח. <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a>."],["3133","90","<b>ידיעת השלילה</b>: ראה גם מו\"נ ח\"א, פנ\"ח. עקרים מאמר ב, פכ\"ג. פכ\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380055\" data-slug=\"likkutei-torah\" data-id=\"4001380055\">לקו\"ת פקודי ג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380066\" data-slug=\"likkutei-torah\" data-id=\"4001380066\">ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670172\" data-slug=\"torat-chaim\" data-id=\"2300670172\">תו\"ח נח מח, ב</a>. בא ח\"א צט, א. פקודי ח\"ב תמו, א ואילך. מאמרי אדה\"א נ\"ך ס\"ע ס ואילך. לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"מ."],["3134","91","<b>והאדם ידע</b>: בראשית ד, א."],["3135","92","<b>שהע\"ס עקודים בכלי א'</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370043\" data-slug=\"torah-or\" data-id=\"3901370043\">תו\"א נח י, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540165\" data-slug=\"torat-chaim\" data-id=\"2300540165\">תו\"ח וארא ח\"א נב, ד</a>. וש\"נ. סה\"מ תרנ\"ב ע' ק ואילך. תרל\"ח ס\"ע עה ואילך ובהערה 274."],["3136","93","<b>(<a class=\"ft-cite\" href=\"#/read/torah-or/3901370064\" data-slug=\"torah-or\" data-id=\"3901370064\">תו\"א</a> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380915\" data-slug=\"likkutei-torah\" data-id=\"4001380915\">לקו\"ת</a> ביאור שוש אשיש)</b>: כ\"ז נרשם עה\"ג בצד הימני של העמוד, בסמיכות להתיבות שהובאו בפנים, בלי חצ\"ע. והכוונה שלהבא בסמיכות לעיין בתו\"א וירא יד, ב. לקו\"ת נצבים מט, סע\"א."],["3137","94","<b>או\"ר. . שאינו פועל שינוי בהמאור</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381187\" data-slug=\"likkutei-torah\" data-id=\"4001381187\">לקו\"ת שה\"ש יד, ג</a>. אוה\"ת ואתחנן כרך ו ע' ב'רמו."],["3138","95","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 82."],["3139","96","<b>אתה הוא קודם שנברה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3140","97","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לעיל (בחלק המאמרים) המשך יונתי רפ\"ד. וש\"נ."]]],[2000480332,"ולכאו' מה שייך שם שכחה, אך השכחה היא מצד אחורים<sup data-n=\"3141\">98</sup>, ובבחי' חכ' יש ג\"כ אחוריים, הרי כמו שא\"א להיות השכלה חדשה בלא ברק המבריק כמו\"כ א\"א להיות בלא אותיות המח', נמצא זה וזה גורמים דמה נ\"מ דאם לא יש הפועל או אם לא יש במה להביא לידי גילוי, וכמו\"כ יובן למעלה הנה איהו וגרמוהי חד הוא כמו אותיות דיבור שהם לזולתו כמו\"כ בחי' איהו וגרמוהי הוא רק כדי שיהי' בריאה יש מאין היינו התהוות עצם מציאות היש, וגם לחבר הנפש עם הגוף שאינם בערך כלל, אך מצד א\"ס הסוכ\"ע אשר כולם בחכ' עשית<sup data-n=\"3142\">99</sup> שגם חכ' נחשבת לעשי' גשמיות<sup data-n=\"3143\">100</sup>, אפ\"ל התחברות הנשמה עם הגוף (ה' דקשור רוחניות בגשמיות הוא מכח א\"ס מפליא לעשות<sup data-n=\"3144\">101</sup> ע') אבל איהו חיוהי הוא כמו בידעות<sup data-n=\"3145\">102</sup> עצמותו יודע את הנבראים<sup data-n=\"3146\">103</sup> וכמו המח' שהוא גילוי העלם העצמי לגבי עצמו, רק שמח' הוא לבוש הנפש משא\"כ חכ' הוא עצמיות, וכמ\"ש בסש\"ב שגם חכ' אינו עצם הנפש<sup data-n=\"3147\">104</sup>, צ\"ל ההפרש כמו בין גופים ללבושים<sup data-n=\"3148\">105</sup> דשניהם לבושים, אך הנה לבוש יכולים לפשוט וללבוש שפושט א\"ע מלבוש זה ולובש א\"ע בלבוש אחר, אבל הלבוש דגוף אינו שייך שיפשוט גוף זה וילבש גוף אחר וגם אינו שייך שיפשט א\"ע לגמרי מהגוף דבע\"כ אתה חי<sup data-n=\"3149\">106</sup> רק שבכחו לזככו ולא לפשטו, וכמו\"כ יש כמה מדריגות בלבושים, ויש לבוש כהדין קמצא<sup data-n=\"3150\">107</sup> דלבושא מני' ובי' שהוא לבוש עצמי יותר ומ\"ש איהו וחיוהי חד הוא כמו הלבוש דקמצא דמני' ובי', וזהו בידיעת עצמותו כו' לא ידע אנוש ערכו<sup data-n=\"3151\">108</sup> אלקים הבין דרכו<sup data-n=\"3152\">109</sup>, ולפ\"ז הנה איהו שמתיחד עם גרמוהי לברוא מאין ליש, הוא כח הגבול שבא\"ס דכמו שיש לו כח בבע\"ג כמו\"כ יש לו כח בגבול<sup data-n=\"3153\">110</sup>, אך מה דאיהו וחיוהי חד הוא בחי' א\"ס הבבע\"ג וגבול לגבי בלתי בע\"ג אינו בערך כלל<sup data-n=\"3154\">111</sup>,",[["3141","98","<b>השכחה. . אחורים</b>: ראה קו\"א דוד זמירות (<a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא קסא, א</a>). מאו\"א מערכת שכחה סל\"ז וביאיר נתיב שם. רמ\"ז לזהר בחוקותי קיב, א (ד\"ה אר\"י א\"ל — ע' צז בדפי הספר)."],["3142","99","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["3143","100","<b>חכ' נחשבת לעשי' גשמיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a> בהגהה. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 46."],["3144","101","<b>דקשור רוחניות בגשמיות. . לעשות</b>: ראה רמ\"א שו\"ע או\"ח ס\"ו, ס\"א. וראה גם מאמרי אדה\"א דברים ח\"ב ע' תנו. נ\"ך ע' תקנא."],["3145","102","<b>חיוהי. . בידעות</b>: אוצ\"ל: וחיוהי. . בידיעת."],["3146","103","<b>בידעות עצמותו יודע את הנבראים</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ט-י."],["3147","104","<b>וכמ\"ש בסש\"ב שגם חכ' אינו עצם הנפש</b>: וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 114. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370061\" data-slug=\"torah-or\" data-id=\"3901370061\">תו\"א וירא יג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380091\" data-slug=\"likkutei-torah\" data-id=\"4001380091\">לקו\"ת ויקרא ד, ב</a>. סה\"מ תרל\"ח ע' עו ובהנסמן שם. לעיל (בחלק המאמרים) בההמשך כאן על יד הערה 240."],["3148","105","<b>ההפרש. . גופים ללבושים</b>: ראה אוה\"ת על ענינים ע' קיג אילך (ובהנסמן בריש המאמר שם). ע' קמג ואילך."],["3149","106","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["3150","107","<b>כהדין קמצא</b>: ראה ב\"ר פכ\"א, ה. <a class=\"ft-cite\" href=\"#/read/tanya/3401310026\" data-slug=\"tanya\" data-id=\"3401310026\">תניא פכ\"א<sup data-n=\"e263\">ה</a></sup> ובלקוטי הגהות־ ליקוט פירושים שם. שער היחוה\"א פ\"ז. מאמרי אדה\"א ויקרא ח\"ב ע' תשכא בהערה."],["3151","108","<b>לא ידע אנוש ערכו</b>: ע\"פ איוב כח, יג."],["3152","109","<b>אלקי' הבין דרכו</b>: ע\"פ איוב שם, כג."],["3153","110","<b>דכמו. . בבע\"ג. . כח בגבול</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 224."],["3154","111","<b>וגבול לגבי בלתי בע\"ג אינו בערך כלל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381282\" data-slug=\"likkutei-torah\" data-id=\"4001381282\">לקו\"ת שה\"ש לח, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381253\" data-slug=\"likkutei-torah\" data-id=\"4001381253\">שערי אורה לא, א</a> ובהערה 23. (לעיל בחלק המאמרים) המשך יונתי פי\"ב. לקמן הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 9. (ובחלק הההנחות שם) על יד הערה 5.\n\n<b>ה</b>  בשיעורים בספר התניא שם ע' 242 : טשערעפאכע. אבל ראה מ\"מ הגהות והע\"ק לסש\"ב שם: מין חגב. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231144\" data-slug=\"likkutei-sichot\" data-id=\"1300231144\">לקו\"ש חוקת כרך כג ע' 144</a> הערה 26 ובשולי היריעה שם."]]],[2000480333,"וזהו הירידה צורך עלי'<sup data-n=\"3155\">112</sup> שעי\"ז מתעלים בבחי' איהו דחיוהי שהוא בבע\"ג וכדאי הירידה, דאף שהנשמה שרשה מטהירא עילאה ואיך שיפורש טה\"ע אם אותיות הרשימה<sup data-n=\"3156\">*113</sup> או למעלה יותר אותיות החקיקה ואפי' מה שגלף גליפו בטה\"ע<sup data-n=\"3157\">113</sup> והוא הקלף שנושא וסובל האותיות מ\"מ הוא רק בחי' גרמוהי, וכמו שנת\"ל דגרמוהי הוא לברוא יש מאין כמו\"כ למעלה א\"ק הוא אדם דבריאה<sup data-n=\"3158\">114</sup> שהוא בריאה יש מאין, ולמעלה יותר הוא קופל מלבושיו שבע\"ח<sup data-n=\"3159\">115</sup>, אבל העלי' הוא בבחי' איהו וחיוהי שהוא א\"ס הבבע\"ג, אף דכל הדרכים בחזקת סכנה היינו אם יעלה חפצו בידו א\"ל שהוא גבול, אבל מה שהוא עושה הרצה\"ע דהוא ורצונו אחד<sup data-n=\"3160\">116</sup> שהוא כח בבע\"ג ה\"ז כדאי כו'.\n<b>וזהו</b> נרי בידך ונרך בידי, הוא נר ה' שהוא חלק ה' ויש בו בחי' י\"ה ג\"כ שהוא בחי' איהו וחיוהי חד, וע\"י קיום תומ\"צ אני משמר אותך דמ\"ש ואתה משמרה בקרבי<sup data-n=\"3161\">117</sup>, אתה הוא גילוי<sup data-n=\"3162\">118</sup> והשמירה מצד המקיף היינו המקיף שבערך הפנימי, וכמו סוכ\"ע שהוא בערך העלמין<sup data-n=\"3163\">119</sup>, אבל מה שאני משמר כו' הוא א\"ס עצומ\"ה וכמו שאדם אומר אני הוא שדברתם ממני, שהוא למעלה מגילוי דכמו דעצם המצות הם למעלה מטו\"ד כמו\"כ פעולתם הוא שיאיר מבחי' א\"ס שלמעלה מגילוי. וזהו יפה שעה א' בתשו' ומע\"ט בעה\"ז מכל חיי עוה\"ב, דהנה עתיד הקב\"ה להנחיל לכל צדיק וצדיק ש\"י עולמות<sup data-n=\"3164\">120</sup>, והנה תרי\"ג מצות דאורייתא וז\"מ דרבנן הם תר\"ך<sup data-n=\"3165\">121</sup> שהוא כת\"ר<sup data-n=\"3166\">122</sup>, וש\"י הוא מחצה מתר\"ך<sup data-n=\"3167\">123</sup> דבכתר יש ב' מדריג'<sup data-n=\"3168\">124</sup> בחי' תחתונה שבמאציל, וראש ומקור לנאצלים, והנה ש\"י הוא מחצה התחתון מכתר, אבל תר\"ך הוא כל בחי' כתר לכן יפה כו', אך צ\"ל והלא אין הקב\"ה מקפח שכר של כל ברי',",[["3155","112","<b>הירידה צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["3156","*113","<b>טה\"ע אם אותיות הרשימה</b>: ראה לעיל (בחלק המאמרים) מאמר ד\"ה כנשר יעיר קנו על יד הערה 58."],["3157","113","<b>שגלף גליפו בטה\"ע</b>: ראה זהר בראשית טו, א."],["3158","114","<b>א\"ק הוא אדם דבריאה</b>: ראה ע\"ח שער סדר אצי' ש\"ג, רפ\"א."],["3159","115","<b>קופל מלבושיו שבע\"ח</b>: וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 130. אולי הכוונה לעמק המלך שער שני."],["3160","116","<b>דהוא ורצונו אחד</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח [נ, ב</a><a class=\"ft-cite\" href=\"#/read/tanya/3401310045\" data-slug=\"tanya\" data-id=\"3401310045\">]. פ\"מ [נד, ב</a>. <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">נה, סע\"א</a>]. פלח הרמון ש\"ד, פ\"ג: הוא ורעותי' חד."],["3161","117","<b>ואתה משמרה בקרבי</b>: ברכת אלקי נשמה. ראה לעיל בפנים פיסקא והנה צלה\"ק."],["3162","118","<b>אתה הוא גילוי</b>: ראה גם לעיל (בחלק המאמרים) המשך יונתי ובהערה 32."],["3163","119","<b>סוכ\"ע שהוא בערך העלמין</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא</a> פמ\"ח. שערי אורה פט, א ובהערה 1."],["3164","120","<b>עתיד. . לכל צדיק. . ש\"י עולמות</b>: עוקצי' בסופה. ראה גם אוה\"ת בהעלותך ע' תטז."],["3165","121","<b>תרי\"ג מצות דאורייתא וז\"מ דרבנן הם תר\"ך</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות הערות 80-83."],["3166","122","<b>תר\"ך שהוא כת\"ר</b>: ראה גם לעיל הנחה ד\"ה וירא העם וינועו הערה 54."],["3167","123","<b>וש\"י הוא מחצה מתר\"ך</b>: ראה הקדמת הראב\"ד לס\"י ירושלים תשכ\"ב ד, א."],["3168","124","<b>דבכתר יש ב' מדריג'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."]]],[2000480334,"הענין דהנה ארז\"ל עתיד הקב\"ה לעשות ראש מחול לצדיקים לע\"ל<sup data-n=\"3169\">125</sup>, מחול הוא עיגול מקיף וכמו אז תשמח בתולה במחול<sup data-n=\"3170\">126</sup>, דמה שנת\"ל ענין ש\"י עולמות הם בחי' איהו וגרמוהי חד שהוא ראש ומקור לנאצלים, אבל שכר מצוה שהוא עצם המצוה זה יתגלה לע\"ל דוקא וזהו יפה שעה א' כו' שהוא ש\"י משא\"כ המצות תר\"ך, מ\"מ אין הקב\"ה מקפח כו' דשכר מצוה מצוה<sup data-n=\"3171\">127</sup> זה יתגלה לע\"ל כו'.",[["3169","125","<b>עתיד. . ראש מחול לצדיקים לע\"ל</b>: ראה ירושלמי מוע\"ק פ\"ג, ה\"ז. מגילה פ\"ב, ה\"ד. ויק\"ר פי\"א, ט. תענית לא, א. לקו\"ת ואתחנן ז, סע\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241066\" data-slug=\"likkutei-sichot\" data-id=\"1300241066\">לקו\"ש</a> ט\"ו באב כרך כד ע' 66 ובהערה 76."],["3170","126","<b>אז תשמח בתולה במחול</b>: ירמי' לא, יב."],["3171","127","<b>דשכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב. ראה תניא רפל\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתצט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540633\" data-slug=\"torat-chaim\" data-id=\"2300540633\">תו\"ח שמות ח\"א ז, ב</a>. וש\"נ. סה\"מ תרכ\"ט ע' כא. וש\"נ."]]],[2000480335,"<h3>לכל תכלה ראיתי קץ</h3>\n<b>ש\"פ שופטים תר\"ם לפ\"ק</b>\n<b>לכל</b> תכלה ראיתי קץ<sup data-n=\"3172\">1</sup> רחבה מצותך מאד<sup data-n=\"3173\">2</sup>, ופי' המפרשים לכל דבר שיש לו כלי' ראיתי קץ השיג הקץ ר\"ל סיום הדבר, רחבה מצותך מאד אין להם קץ כלל ואינו שייך בהם השגה (ה' כ\"פ המצ\"ד ומ\"ש רש\"י לכל סיום כו' יש קץ כו' אין קץ כו' צ\"ל ג\"כ כפי' המצ\"ד שזה אפשר להשיג וזה א\"א להשיג, וע' משית\"ל שפרש\"י הוא כפי מה שנת' כאן לא כמצ\"ד, וע' בחייט במע' השמות<sup data-n=\"3174\">3</sup> פי' לכל תכלה לכל דבר שיש לו סיום ראיתי קץ יש לו התחלה ג\"כ, הרי מפרש קץ ל' התחלה, וכן מפרש המרש\"א<sup data-n=\"3175\">4</sup> על מארז\"ל (נדה) ארשב\"ג לדברי אין קץ לדברי חכמים אין סוף, פי' קץ ל' התחלה, ושניהם אמת דשם קץ נושא וסובל ב' הפי' וכמו מקצה השמים ועד קצה השמים<sup data-n=\"3176\">5</sup> שכולל ההתחלה והסיום ע'), ולכאו' צ\"ל מ\"ש שהמצות אין להם קץ מפני שלא השיג קיצם, וכי מפני שהוא לא השיג אפשר שאחר ישיג קיצם, ואיך פסק בסכינא חריפא<sup data-n=\"3177\">6</sup> שאין להם קץ ואיך אפשר להשיג שאין בהם השגה אולי אחר ישיגם, ועוד צ\"ל אומרו שהמצות הם בלתי מוגבלים, והרי כל המצות באו למטה בגבול כמו",[["3172","1","<b>לכל תכלה ראיתי קץ</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הד' מהמשך יונתי (פי\"א-פי\"ב). שנדפס לעיל בחלק המאמרים [ושם הפתיחה: אך עדיין צ\"ל מאחר שבחי' חיוהי].\nהנחה אחרת מדרוש זה נדפסה לקמן (בחלק הנחות)."],["3173","2","<b>לכל תכלה ראיתי קץ רחבה מצותך מאד</b>: תהלים קיט, צו. ראה גם אוה\"ת בראשית כרך ג ע' 1010 ואילך. סה\"מ תרס\"ו ע' כ."],["3174","3","<b>בחייט במע' השמות</b>: ראה שם פ\"ג ט, סע\"ב ואילך [ושם הכותרת בריש הפרק: ערכת השמות. הכותרת ב”פ\"ז\": מערכת השמות. וב”מערכת\" הכותרת: לשכת השמות]."],["3175","4","<b>המרש\"א. . ארשב\"ג לדברי</b>: ראה שם נח, ב."],["3176","5","<b>מקצה השמים ועד קצה השמים</b>: וכ\"ה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' על יד הערה 7. ואתחנן ד, לב [ושם: ולמקצה]. ראה גם לקו\"ש מקץ כרך ה ע' 196 ואילך."],["3177","6","<b>פסק בסכינא חריפא</b>: ראה ב\"ב קיא, ב."]]],[2000480336,"סוכה צ\"ל ז\"ט ומשהו<sup data-n=\"3178\">7</sup> וכן לולב צריך לצאת טפח<sup data-n=\"3179\">8</sup> וכדומה, ואיך אפשר להתחבר ב' הפכים כא' בבע\"ג עם גבול שהם רחוקים יותר ממזרח עם מערב א\"א לחברם והוא מפני שמזרח הוא גבול ומערב ג\"כ גבול ושטח הגבול מפסיק ביניהם ולא יקרב זה לזה, אבל גבול ובבע\"ג יותר מורחקים זמ\"ז<sup data-n=\"3180\">9</sup> ואיך שהמצות שהם מוגבלים יהיו כלים לא\"ס הבבע\"ג.\n<b>ולהבין</b> זה צ\"ל תחילה משנת\"ל דירידת הנשמה בגוף אף שהיא ירידה גדולה מ\"מ כדאי בשביל ההעלאה דע\"י בירור הנה\"ב מתעלה הנה\"א ג\"כ ונת\"ל שהעלי' הוא מבחי' גרמוהי לבחי' חיוהי<sup data-n=\"3181\">10</sup>, דאף דשרש הנשמה היא מבחי' טה\"ע<sup data-n=\"3182\">11</sup> מ\"מ הוא בחי' איהו וגרמוהי חד, אבל העלי' הוא בבחי' איהו וחיוהי חד<sup data-n=\"3183\">12</sup> שהוא בחי' א\"ס הבבע\"ג והוא מה שבידיעת עצמותו יודע את התורה<sup data-n=\"3184\">13</sup>, וצ\"ל מאחר שהוא בידיעות<sup data-n=\"3185\">14</sup> עצמותו עדיין, מה נתחדש דבר באצי' זו דלעצמותו הי' ידוע תחילה ג\"כ דאינו שייך לומר שתחילה לא הי' ידוע ועכשיו ידוע אלא שהי' ידוע בתחילה כמו עתה, ולזולתו גם אחר שנאצל אינו ידוע, וא\"כ מה נתחדש במה שנאצל בחי' זו. וצ\"ל דקודם שנאצל בחי' זו לא הי' שייך כלל לומר שם חכים אף דלא בחכ' ידיעה<sup data-n=\"3186\">15</sup> מ\"מ נק' חכים ולא הי' שייך זה לומר כלל, וזהו שנאצל בחי' זו כדי שיהי' שייך לומר שם חכ' התורה, דמה שארז\"ל אלפים שנה קדמה תורה לעולם<sup data-n=\"3187\">16</sup> פי' אלפך חכ' אלפך בינה<sup data-n=\"3188\">17</sup> והוא חו\"ב דסדר השתל'<sup data-n=\"3189\">18</sup> ואפי' נא' בכללות השתל'<sup data-n=\"3190\">19</sup> ומה שם הם בחי' אלפים שנה<sup data-n=\"3191\">20</sup> מ\"מ קודם שנאצל בחי' זו דבידיעת עצמותו כו' לא הי' שייך זה כלל, ולכן נאצל בחי' זו כדי שיהי' שייך לומר שם חכ' התורה.",[["3178","7","<b>סוכה צ\"ל ז\"ט ומשהו</b>: באגה\"ק ס\"י: ז\"ט. ראה גם לעיל (בחלק המאמרים) בההמשך כאן ובהערה 270. סה\"מ תרל\"ב ח\"א ע' פד ובהערה שם."],["3179","8","<b>לולב צריך לצאת טפח</b>: ראה שו\"ע אדה\"ז הל' לולב סתר\"נ."],["3180","9","<b>ב' הפכים. . מורחקים זמ\"ז</b>: ראה גם לעיל הנחה ד\"ה יפה שעה אחת הערה 111."],["3181","10","<b>ונת\"ל שהעלי'. . חיוהי</b>: ראה בהנחה ד\"ה יפה שעה שנדפס לפנ\"ז."],["3182","11","<b>דשרש הנשמה. . טה\"ע</b>: נסמן בהנחה ד\"ה יפה שעה שם הערה 61."],["3183","12","<b>איהו וגרמוהי. . וחיוהי חד</b>: ראה ת\"ז בהקדמה ג, ב. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח ובהערה 99."],["3184","13","<b>בידיעת עצמותו יודע את התורה</b>: ראה קו\"א דוד זמירות (<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא קסא, א</a>). וראה גם לעיל הנחה ד\"ה יפה שעה אחת בפנים אחר הערה 107 ואילך. לעיל (בחלק המאמרים) המשך יונתי פ\"י על יד הערה 239 ואילך."],["3185","14","<b>בידיעות</b>: אוצ\"ל: בידיעת."],["3186","15","<b>חכים. . בחכ' ידיעה</b>: נסמן בסמוך הערה 21."],["3187","16","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו ובהערה 6."],["3188","17","<b>אלפך חכ' אלפך בינה</b>: כנצ\"ל: ואאלפך — איוב לג, ג. שבת קד, א."],["3189","18","<b>אלפים. . חו\"ב דסדר השתל'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381136\" data-slug=\"likkutei-torah\" data-id=\"4001381136\">לקו\"ת שה\"ש א, סע\"ד</a> ואילך."],["3190","19","<b>אלפים. . חו\"ב. . בכללות השתל'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' שכא וע' שכד נו\"ש. ראה גם סה\"מ תרל\"ח ע' תקב. ע' תקיב (וש\"נ)."],["3191","20","<b>ומה שם. . שנה</b>: כ\"ה בגוכתי\"ק."]]],[2000480337,"<b>ועוי\"ל</b> דכדי שיהי' בחי' חכים דבחכ' ידיעא הי' צ\"ל קודם בחי' חכים ולא בחכ' ידיעה<sup data-n=\"3192\">21</sup>. וביאור הענין, דהנה שם חכ' מורה על דבר שאפשר להתגלות לזולתו, דמה שנת' במ\"א ההפרש בין מוחין למדות<sup data-n=\"3193\">22</sup>, דמדות הם שייכים לזולת כמו רחמן חסדן שייך לומר כשיש על מי להתרחם ועל מי להתחסד, וכמו מי שהוא טוב שייך דוקא כשיש עם מי להטיב אבל בלא זולתו אינו יודעים כלל שהוא טוב, דאדה\"ר אף שהי' יחידי, מ\"מ הי' עוד נבראים שהוא הבין יותר מהם אפי' קודם החטא מכ\"ש לאחר החטא והטיב עמהם, וכן אדם שהוא בין אילנות ודשאים הוא מטיב עמהם להשפיע להם חיות, אבל מי שהוא יחידי לגמרי אינו שייך המדה כלל, הרי שפעולת המדות פועלים כ\"כ עד שעצם המדה כמו שאינו כלל דאין לו למי להשפיע רק שיש בכוחו להיטיב שרוצה להיטיב ה\"ז בכח ולא בפועל (ה' ואנו רואין מי שהוא גדול ביער שלא בין אנשים, אין לו מדות אנשים כלל והוא במדותיו כמו בהמה ממש וגרוע מהם, ומי שגדול<sup data-n=\"3194\">23</sup> בין אנשים פראים עזי נפש רוצחי נפש ר\"ל גם הוא בכל מדותיו כהם ממש, ולפיכך מי שגדולו בין אנשים בעלי מדות טובים גמ\"ח מטיבים עם זולתם, גם הוא קונה לו בנפשו מדות טובות אלו, הרי שהזולת פועל שינוי בהמדה שיהופך מן הקצה אל הקצה כמו עד\"מ מי שהי' זמן רב ביער וקנה בנפשו מדות בהמיות כנ\"ל ואח\"כ כשבא במקום שיש אנשים בעלי מדות טובים והוא עמהם זמן מה, עושה שינוי בנפשו שיהופך המדה מרע לטוב לגמרי וכן להיפך, הרי שהזולת עושה שינוי בעצם המדות להמיר אותם מרע לטוב, וסבות הדבר הוא ההשפעה באיזה אופן שהוא משפיע אותם וכמובן כו', משא\"כ המוחין שאינם שייכים לעולם כלל, שאף שיושב ביער מ\"מ יכול להשכלות<sup data-n=\"3195\">24</sup> נוראות בדבר שמעמיק דעתו בו, וחכמי המחקר והפלוסופי' עיקר ישיבתם הי' ביערות ובין ההרים הגדולים<sup data-n=\"3196\">25</sup> מקום שאין רגלי בנ\"א מצוים שם והשכילו שם השכלות גדולות. ואדרבה נהפוך הוא מי שמעמיק דעתו באיזה דבר שכל עמוק, הזולת לו למנגד ומבלבל לו עד שא\"י להעמיק דעתו כ\"כ הרי שהשכל אינו שייך להזולת כלל אבל המדות הם שייכים לזולת דוקא וכנ\"ל כו' ע').\n<b>וכמו\"כ</b> למעלה כתי' זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"3197\">26</sup>, רחמים וחסדים הם שייכי' לעולם דוקא כשיש על מי להתרחם אז שייך להקרא רחום וכן חסד כתי' כי אמרתי עולם חסד יבנה<sup data-n=\"3198\">27</sup> כשהי' צריך להיות עולמות אז נבנה בנין החסד בציור דקודם שנבה\"ע הי' בכח, אבל כשנבנה העולם נעשה בבנין וציור והיינו",[["3192","21","<b>חכים ולא בחכ' ידיעה</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה יז, ב."],["3193","22","<b>ההפרש בין מוחין למדות</b>: ראה לעיל (בחלק המאמרים) בההמשך כאן ובהערה 261."],["3194","23","<b>גדול. . שגדול</b>: אוצ\"ל: גדל. . שגדל."],["3195","24","<b>להשכלות</b>: אוצ\"ל: להשכיל השכלות."],["3196","25","<b>וחכמי המחקר והפלוסופי'. . ביערות ובין ההרים הגדולים</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו על יד הערה 89. (בחלק המאמרים) המשך מצה זו פ\"ל על יד הערה 971."],["3197","26","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]."],["3198","27","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה והנה כובע ובהערה 94."]]],[2000480338,"שבאו לידי גילוי, אבל מוחין אינם שייכים לזולת שיוכל לישב בפ\"ע ולהשכיל השכלות, וראי' דהרי אלפים שנה קדמה תורה לעולם, הגם שארז\"ל ומתלמידי יותר מכולם<sup data-n=\"3199\">28</sup> היינו שע\"י השפעה נמשך ממקור השכל (משכיל) לשכל אבל לא דבר חדש לגמרי דזה אינו שייך לזולת, ולכן רשב\"י שישב במערה י\"ב שנה<sup data-n=\"3200\">29</sup> ולא הי' לו למי להשפיע (ה' דמה שהי' עם ר\"א בנו<sup data-n=\"3201\">30</sup> זה אינו בגדר השפעה שהוא עצם א' ע') ומ\"מ ניתוסף בו ריבוי חכ' דקודם שהי' במערה הי' רפב\"י מפרק כו' ואח\"כ הי' רשב\"י מפרק ובכפל פירוקי<sup data-n=\"3202\">31</sup>, הרי מובן דחכ' אינו שייך לזולת, אך היינו שאינו מוכרח לזולת ולא כן המדות שבלתי הזולת אינו שייך שם מדה כלל, משא\"כ מוחין שייך בלא זולת ג\"כ אבל מ\"מ כשרוצה יכול להשפיע לזולתו ג\"כ, ולכן נק' בחי' זו בשם חכ' ידיעה דמה נ\"מ אם ידוע לזולתו או במה שהוא בעצמו יודע דמאחר שבכחו לגלות לזולתו מוכרח לומר שהוא בעצמו משיגו בטוב דאל\"כ לא הי' באפשרי לגלותו לזולתו, וגם אם יעמיק דעתו עוד בזה הענין יבין אותו בעומק יותר כו' א\"כ ה\"ז הגבלה, לכן נק' חכ' ידיעה אבל בחי' חכ' דלא ידיעה היינו החכ' קודם שבאה לידי השגה והבנה ואז אינו שייך לומר ע\"ז ידיעה מאחר שעדיין אינו ידוע כלל ומ\"מ שייך ע\"ז שם חכ', וכדי שיהי' בחי' חכ' ידיעה הוצרך להאציל תחילה בחי' חכ' דלא ידיעה, נמצא דבחי' זו הוא כעין ממוצע בין א\"ס הבבע\"ג ובין בחי' א\"ס שמתלבש בע\"ס, ומ\"מ אין בזה שום התחדשות, וה\"ז כמו גילוי האור מן המאור שהרי קודם שהאיר הי' כלול בהמאור והי' בהעלם ועתה מה שנגלה היינו רק מה שבא מהעלם לידי גילוי ולא כמו השפעה שהוא דבר חדש משא\"כ הי'<sup data-n=\"3203\">32</sup> כלול בתחילה בהעלם ועכשיו בא מהעלם לגילוי (ה' ולכן נק' או\"ר ולא שפ\"ע וע' מזה בלקו\"ת בד\"ה להבין מ\"ש באוצ\"ח<sup data-n=\"3204\">33</sup>, ובסידור ח\"א בפי' זכר רב טובך<sup data-n=\"3205\">34</sup>, ובד\"ה להבין ענין אוא\"ס<sup data-n=\"3206\">35</sup>, ובשער היחוד<sup data-n=\"3207\">36</sup>, ובד\"ה וככה פצט\"ק, ע').\n<b>אך</b> המשל אינו דומה להנמשל דבהמשל האור הוא מורגש כמו זיו השמש כשמאיר לארץ ולדרים עלי' הרי ניכר האור וביום המעונן שאין האור מאיר ניכר ג\"כ, וכן האור פועל שינוי באדם ג\"כ דכשמאיר הזיו למטה אז החיות באו\"א בל\"א<sup data-n=\"3208\">37</sup> ל עב עד יק וביום מעונן אז האדם ג\"כ מעונן בל\"א ן גירוֲגט והוא מפני שהמאור מורגש ומוגבל לכן האור ג\"כ מורגש ומוגבל, אבל למעלה המאור הוא א\"ס כמו\"כ",[["3199","28","<b>ומתלמידי יותר מכולם</b>: תענית ז, א. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 538."],["3200","29","<b>רשב\"י שישב במערה י\"ב שנה</b>: ראה שבת לג, ב תריסר שני. . תריסר ירחי."],["3201","30","<b>רשב\"י. . עם ר\"א בנו</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וירא העם וינועו ובהערה 92."],["3202","31","<b>רפב\"י מפרק. . פירוקי</b>: שבת שם."],["3203","32","<b>משא\"כ הי'</b>: אוצ\"ל: משא\"כ אור הי'."],["3204","33","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380302\" data-slug=\"likkutei-torah\" data-id=\"4001380302\">לקו\"ת</a>. . באוצ\"ח</b>: ויקרא בהוספות נב, ג."],["3205","34","<b>ובסידור. . טובך</b>: שחרית מח, א ואילך."],["3206","35","<b>ובד\"ה להבין ענין אוא\"ס</b>: ראה אוה\"ת על ענינים ע' קי, ואילך. וש\"נ. ע' קמד (ובהנסמן בריש המאמר שם)."],["3207","36","<b>ובשער היחוד</b>: קטז, א."],["3208","37","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211457\" data-slug=\"likkutei-sichot\" data-id=\"1300211457\">לקו\"ש משפטים כרך כא ע' 448</a> הערה 15."]]],[2000480339,"האור ג\"כ א\"ס, וביאור הענין הנה צ\"ל מ\"ש בידיעת עצמותו יודע את התורה מהו\"ע ידיעת עצמותו, אך הנה משל מכוון א\"א למצוא לזה שכל משל שיאמר עליו ה\"ז ממציאות דבר מוגבל וא\"ס הוא בבע\"ג, אך לקרב אל השכל יובן עד\"מ מי שהוא לומד דבר הלכה עד\"מ שנים אוחזים בטלית<sup data-n=\"3209\">38</sup> ומשכיל בה השכלות וכמה סברות ויוצא לו מזה איזה פס\"ד, הרי מושג אצלו השכל בטוב, ואינו מגלה השכל לזולתו, וכן עד\"מ מי שיש לו אוצר ואינו מגלה לשום אדם, אך הוא בעצמו יודע מהאוצר ויכול למנות אותו וכן השכל ה\"ה יכול למדוד אותו כמה הוא יודע בהשכל ואיזה פס\"ד יוצא ממנו אך אינו מגלה ההלכה או השו\"ת לזולתו מצד הטעם הכמוס שיש לו וכמו שיש מחברים שהמציאו שאלה מעצמם<sup data-n=\"3210\">39</sup> כדי שלא יתוודע אך זה גופא שאינו רוצה לגלות שהוא מצד הטעם הכמוס שיש לו ה\"ז ג\"כ מושג אלא שהוא כמוס לזולתו. אבל מי שהוא חכם ולומד איזה דבר הלכה ויודע דבהלכה זו יש ריבוי עומק מאד אך א\"י מה הוא ולמד עוד הפעם ועדיין א\"י אבל זה בלתי ספק אצלו שיש כאן השכלה עמוקה, דאדם פשוט כשילמוד לא ידע כלל שיש כאן עמקות אבל חכם שלומד יודע שיש כאן ענין עמוק, הרי אינו שייך לומר ע\"ז חכ' ידיעה מאחר שאינו משיג עדיין, מ\"מ שם חכ' יקרא שהרי הוא יודע בודאי שיש כאן השכלה עמוקה (ה' וצ\"ל דמאחר שיודע שיש כאן עומק יש בכוחות עצמיות שלו שיבין העומק הזה רק שעדיין לא בא לידי גילוי ע').\n<b>ולקרב</b> אל השכל יותר יובן ממשארז\"ל איזה חכם הרואה את הנולד<sup data-n=\"3211\">40</sup> ואין ר\"ל שרואה מה שנולד כבר, דלזה א\"צ חכם וכל אדם יודע זאת, אלא ר\"ל שרואה מה שנולד אחר כמה מאות שנים, דמי שאינו חכם לא יודע זאת אך הוא בחכמתו רואה ההנהגה איך שהוא עתה יודע שלאחר כמה יהי' כן, וזהו אומרו נולד כמו שא\"א לידע צורת הבן שיולד אחר זמן כמו\"כ א\"א לידע מה שיהי' אח\"ז רב, אבל מי שהוא חכם גדול יודע את הנולד ובלתי ספק אצלו שבודאי יהי' כן כאלו רואה מחר<sup data-n=\"3212\">41</sup> אך לא כל דבר אפשר לגלות ויש דברים שא\"א לגלות אותם, אך כ\"ז בשכל שחשב בו ויודע אותו אבל בדבר שלא חשב כלל אינו שייך שיודע את הנולד, מ\"מ שואלים ממנו איזה ענין שיאמר לו מה שיצמח מזה, ולכאו' צ\"ל אולי לא יודע כלל את הדבר הנולד, אך מפני שקנה לו שם חכים כבר במה שראו ממנו שבכמה דברים ראה את הנולד מה שא\"כ בכח אחר זולתו הרי יודעין שהוא בעל כח כזה לידע את הנולד, לכן בלתי ספק לו דכשיספר לו ענינו יודע את הנולד מזה, וכ\"ז לגבי זולתו, וכמו\"כ לגבי עצמו כשהזולת מספר לו הענין עדיין אינו יודע את הנולד, דאפשר לידע רק אחר כשכבר יודע הענין אבל כשמספר לו עדיין אינו יודע את הענין וממילא אינו יודע את הנולד, ומ\"מ ברור אצלו דכשיספר לו את הענין בשלימות יודע את הנולד, מפני שהוא יודע כוחות עצמיות שיש בו כח זה לידע את",[["3209","38","<b>שנים אוחזים בטלית</b>: ראה משנה ב\"מ ב, א."],["3210","39","<b>שיש מחברים שהמציאו שאלה מעצמם</b>: לדוגמא שו\"ת תרומת הדשן — ראה שם הגדולים מערכת מהר\"ר ישראל. . איסרלאן (אות תב)."],["3211","40","<b>איזה חכם. . הנולד</b>: ראה תמיד לב, א."],["3212","41","<b>רואה מחר</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן."]]],[2000480340,"הנולד לכן בלתי ספק דכשיודע את הענין, יודע את הנולד מזה אך עתה א\"י עדיין רק שהוא כלול בכוחותיו העצמיים, וזהו בידיעת עצמותו, במה שיודע העצמיות שלו שיש לו כח כזה, דחכ' וידיעה דבר א' רק חכ' הוא מה שהשכיל בעצמו וידיעה אפשר שישמע מאחר, ושם ידיעה הוא פעולה ויש מי שמפעיל את הידיעה והוא יודע והכל בעצמותו עדיין, אך למעלה אין המשל זה מכוון שה\"ה הגבלה וא\"ס הוא בבע\"ג, ומ\"ש ידיע\"ת עצמותו באמת שם ידיעה אינו שייך שם כלל וזהו שא' עצמותו לשלול ענין הידיעה אך מפני שבכוחות הנגלים יש חכ' וידיעה לכן ע\"ש המושאל אנו אומרים שם ג\"כ בשם ידיעה אבל הוא רק לשכך את האזן<sup data-n=\"3213\">42</sup>, וזהו איהו וחיוהי חד אין ר\"ל דאיהו מתייחד עם חיוהי אלא שבאמת הם דבר אחד שה\"ה בעצמיות, וזהו עליות הנשמה שמתעלה לבחי' איהו וחיוהי חד.\n<b>אך</b> צ\"ל איך יש בכח הנשמה לבוא לבחי' איהו וחיוהי חד, והנה נת\"ל שהבירור הוא ע\"י המצות<sup data-n=\"3214\">43</sup> והלא המצות הם מוגבלים כמו סוכה ז\"ט ומשהו, סוכה שהיא גבוה<sup data-n=\"3215\">44</sup> למעלה מך' אמה פסולה, לולב צריך שיוצא טפח, והדס צ\"ל ג\"ט<sup data-n=\"3216\">45</sup>, וד\"מ שבלולב ולא ה', וכן תפילין ד' בתים ולא ה', וא\"כ איך ע\"י המצות ממשיכים בחי' א\"ס הבבע\"ג. אך הענין דזהו מה שא' לכל תכלה ראיתי קץ רחבה מצותך מאד, תכלה הוא ל' כליון<sup data-n=\"3217\">46</sup> וכמו כלתה נפשי<sup data-n=\"3218\">47</sup> כו' או כלה שארי ולבבי<sup data-n=\"3219\">48</sup>, לכל תשוקה וכליון ראיתי קץ שייך בהם השגה שהם מוגבלים דהנה ג\"ע הוא הג\"ר שבכל עולם<sup data-n=\"3220\">49</sup>, וכמו עולם העשי' הז\"ת הם מקור העולם, ומי שעושה עם המדות כדבעי למהוי הוא מצד השכל שמחייב כך לכן בג\"ע נותנין לו ההשכלה, ואפי' בתענוגי עוה\"ז אם עושה כדבעי למהוי נותנים לו השכלה, וכמו\"כ ברוחניות כשיש לו אהוי\"ר, אח\"כ בג\"ע הוא ההשכלה מהו אלקות ושצריכים לאהבה אותו וליראה מפניו, והנה זהו לגבי עולם העשי' אבל לגבי עולם היצי' הרי הג\"ע דעשי' אינו תופס מקום כלל דממל' דיצי' נעשה כתר ועתיק לעשי'<sup data-n=\"3221\">50</sup> וז\"ת דיצי' הם למעלה מג\"ר דעשי', וכן יצי' לגבי בריאה ומכ\"ש בריאה לגבי אצי', א\"כ ה\"ז הגבלה, וכמו עד\"מ בן ואב כשהבן מוגבל האב ג\"כ מוגבל, והאב יש לו ג\"כ אב, וזהו לכל תכלה ראיתי קץ וגם ממה שארז\"ל צדיקי' כו'<sup data-n=\"3222\">51</sup> ילכו מחיל אל חיל<sup data-n=\"3223\">52</sup> מזה מובן שהוא",[["3213","42","<b>לשכך את האוזן</b>: מכילתא יתרו יט, יח. תנחומא שם יג. שער היחוד והאמונה רפ\"י. אגה\"ק ס\"ו קי, א. סכ\"ט קמט, ב. וראה גם ע\"ח שער ד שער אח\"פ רפ\"ב."],["3214","43","<b>נת\"ל שהבירור הוא ע\"י המצות</b>: בהנחה ד\"ה יפה שעה אחת."],["3215","44","<b>סוכה שהיא גבוה</b>: משנה סוכה ב, א [ושם גבוהה — ראה שנויי נוסחאות במשניות שם. סה\"מ תרל\"ח ע' רלו. וש\"נ]."],["3216","45","<b>והדס צ\"ל ג\"ט</b>: ראה שו\"ע אדה\"ז הל' לולב רסתר\"נ."],["3217","46","<b>תכלה הוא ל' כליון</b>: ראה אגה\"ק סי' י\"ז בסופה."],["3218","47","<b>כלתה נפשי</b>: תהלים פד, ג."],["3219","48","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["3220","49","<b>ג\"ע הוא הג\"ר שבכל עולם</b>: ראה לעיל (בחלק המאמרים) בההמשך כאן הערה 275."],["3221","50","<b>דממל' דיצי' נעשה כתר ועתיק לעשי'</b>: ראה ע\"ח שער כסה\"כ שמ\"ו, פ\"ב. פ\"ה ופ\"ו."],["3222","51","<b>צדיקי' כו'</b>: ראה תרגום לתהלים פד, ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשע ובהנסמן במ\"מ לשם. סה\"מ תרל\"ח ע' תקה. וש\"נ."],["3223","52","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."]]],[2000480341,"הגבלה מאחר שעולם זה הוא למטה והעולם העליון הוא למעלה ממנו א\"כ ה\"ז הגבלה, אבל רחבה מצותך מאד פי' בסש\"ב דמצות הם כלים רחבים לקבל מאד העליון היינו העונג העליון דא\"ס הבבע\"ג (ה' אגה\"ק ד\"ה נודע שבאתעדל\"ת<sup data-n=\"3224\">53</sup> ע'), ופי' מאד העליון, הנה כתי' ואהבת את ה' אלקיך<sup data-n=\"3225\">54</sup> בכל לבבך ובכל נפשך ובכל מאדך, הרי יש כאן ג' מיני אהבת, אהבה דבכל לבבך פי' בשני יצריך<sup data-n=\"3226\">55</sup> ביצ\"ט וביצה\"ר ונת\"ל איך אפשר שהיצה\"ר יהי' לו אהבה לאלקות (ה' ד\"ה ואהבת<sup data-n=\"3227\">56</sup> ע'), בכל נפשך, בכל כחות נפשו ששכלו יקשר בחכ' התורה, ומדותיו ידבק לאלקות שיתן צדקה ויעשה בכל כוחות נפשו בשביל חבירו כבשביל עצמו בשוה, ובכל מאדך, שיוצא חוץ להגבלות הכלי, דבכל לבבך בשני יצריך ה\"ז לפ\"ע הגבלות הלב, ובכל נפשך הוא לפ\"ע הגבלות כוחות נפשו אבל בכל מאדך הוא שיוצא מהגבלת הכלים לגמרי, וכמ\"ש מי לי בשמים<sup data-n=\"3228\">57</sup> ועמך לא חפצתי בארץ שלא יחפוץ לא בגעה\"ע ולא בגעה\"ת [ואפי' לא בהרצונות פרטים שהם מוגבלים] כ\"א א\"ס עצומ\"ה, וא' בכל מאד\"ך ולא בכל מאד שאין מבקשים רק מאד האדם<sup data-n=\"3229\">58</sup> שהוא אינו בערך למאד העליון וכמו שאמרו רז\"ל בכל מאדך בכל ממונך<sup data-n=\"3230\">59</sup> והוא מס\"נ גדול מאד ומ\"מ אינו תופס מקום אפי' לגבי אדם שהוא עשיר גדול יותר ממנו ומכ\"ש לגבי עולם שלמעלה מזה העולם ומכ\"ש כו' וכן בכל עולם יש בחי' מאד שבזה העולם שאינו תופס מקום לגבי מאד שבעולם שלמעלה ממנו ובחי' מאד העליון שהוא בבע\"ג האמיתי. וזהו שא' בכל מאדך כמה שהאדם יכול להגיע בבחי' מאדו. וזהו שא' במדר' כשהוא נותן<sup data-n=\"3231\">60</sup> נותן לפי כחו הן אל ישגיב בכחו<sup data-n=\"3232\">61</sup> מי כמוהו מורה אבל כשהוא מבקש אינו מבקש אלא לפי כוחן שור כשב ועז ולא איל צבי ויחמור שהם אינם מצויים<sup data-n=\"3233\">62</sup> וכמו\"כ יובן כאן שאין מבקשים רק מאד האדם, אבל מצות הם כלים רחבים לקבל מאד העליון בלי גבול האמיתי.\n<b>אך</b> צ\"ל איך מצות הם כלים ע\"ז, והלא מצות הם מוגבלים ואיך אפשר שבבע\"ג יהי' בגבול, ואם אפשר שמבבע\"ג יהי' גבול א\"כ קשיא טובא מהו\"ע הצמצום ומקו\"פ<sup data-n=\"3234\">63</sup>",[["3224","53","<b>בסש\"ב. . אגה\"ק ד\"ה נודע שבאתעדל\"ת</b>: סי\"ז [ושם: דבאתעדל\"ת]."],["3225","54","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה."],["3226","55","<b>דבכל לבבך פי' בשני יצריך</b>: ברכות נד, א. ראה לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 18."],["3227","56","<b>שהיצה\"ר. . אהבה. . ד\"ה ואהבת</b>: ראה לעיל שם על יד הערה 54 ואילך."],["3228","57","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 65."],["3229","58","<b>בכל מאד\"ך. . מאד האדם</b>: ואתחנן ו, ה. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370180\" data-slug=\"torah-or\" data-id=\"3901370180\">תו\"א מקץ לט רע\"ד</a>. לעיל ח\"א (בחלק ההנחות) הנחה ד\"ה תכון תפלתי קטורת לפניך ובהערה 30."],["3230","59","<b>בכל מאדך בכל ממונך</b>: ראה ברכות נד, א (במשנה). ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 102."],["3231","60","<b>כשהוא נותן. . כחו. . כחן</b>: ראה במדב\"ר פכ\"א, כא. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091478\" data-slug=\"likkutei-sichot\" data-id=\"1300091478\">לקו\"ש ר\"ה כרך ט ע' 452</a> בהערה."],["3232","61","<b>הן אל ישגיב בכחו</b>: איוב לו, כב."],["3233","62","<b>שור. . ויחמור שהם אינם מצויים</b>: ראה ויק\"ר פכ\"ז, ו."],["3234","63","<b>הצמצום ומקו\"פ</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."]]],[2000480342,"שסילק כביכול אורו הגדול על הצד<sup data-n=\"3235\">64</sup> ונשאר רשימה<sup data-n=\"3236\">65</sup> ועז\"נ הנה מקום אתי<sup data-n=\"3237\">66</sup> שמשם נצטיירו כללות עולמות אבי\"ע למה צריכים לכ\"ז, אלא שהוא מוכרח א\"כ קשיא קושי' הנ\"ל. והענין דהנה מצות הם רצה\"ע ותרי\"ג מצות דאורייתא<sup data-n=\"3238\">67</sup> הם תרי\"ג ארחין דגולגלתא<sup data-n=\"3239\">68</sup> וכמו אורח ושביל שהולך למקום א' וההולך עליו צריך לילך שלא יטה מן הדרך, כמו\"כ המצות הם כמו צנור שיומשך בצמצום ולא בהתפשטות. והנה המצות הם שלוחים לברר הדברים גשמים, והמברר מוכרח להתלבש בלבוש המתברר<sup data-n=\"3240\">69</sup> ומקום המתברר לכן נמשכו המצות למטה ונתלבשו בדברים גשמי' שהם מע' שרים<sup data-n=\"3241\">70</sup> דק\"נ לברר אותם, ושרש הדברים מתהו שקדם לתקון<sup data-n=\"3242\">71</sup> ופי' קדם אין ר\"ל בזמן אלא קדם במעלה ונת\"ל<sup data-n=\"3243\">72</sup> דמ\"ש בתהו ריבוי האור ובתיקון מיעוט אין ר\"ל ריבוי ומיעוט לבד אלא שהאור הוא באו\"א והראי' מאור שנברא ביום א' הי' אדם מביט מסוף ועד<sup data-n=\"3244\">74</sup> סופו<sup data-n=\"3245\">73</sup> ועכשיו ראיות האדם הוא רק עד מיל<sup data-n=\"3246\">75</sup> הרי שהוא שלא בערך כלל, וכ\"ז בתיקון וכ\"ש אורות דתהו לגבי אורות דתקון אינם בערך כלל (ה' ד\"ה הנ\"ל<sup data-n=\"3247\">76</sup> ע'), וע\"י הבירור דדברים גשמים מתעלים לשרשם ומקורם לעולם התהו שקדם לתיקון ועי\"ז נמשך אורות דתהו בכלים דתיקון ה\"ז מאד לגבי תיקון, דכלים דתיקון הם רק לקבל אורות המועט דתיקון, אך כשמאיר בה אורות המרובים דתיקון ה\"ז מאד, ובאמת הוא מאד לגבי תהו ג\"כ, שממשיכים אורות שלמעלה מתהו ותיקון והוא שנמשך מבחי' עקודים שלמעלה מנקודים וברודים, נקודים וברודים הם תהו ותיקון<sup data-n=\"3248\">77</sup>, וע\"י בירורי' שע\"י המצות ממשיכים מבחי' עקודים [בפ\"א<sup data-n=\"3249\">78</sup> עקודים ג\"כ עולם] ועל ל' השמות הנה ד' שמות ע\"ב<sup data-n=\"3250\">79</sup>",[["3235","64","<b>שסילק. . אורו הגדול על הצד</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 216."],["3236","65","<b>ונשאר רשימה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380261\" data-slug=\"likkutei-torah\" data-id=\"4001380261\">לקו\"ת בהר מג, ב</a>. המשך מצה זו שם הערה 217."],["3237","66","<b>הנה מקום אתי</b>: תשא לג, כא. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל על יד הערה 9 ואילך."],["3238","67","<b>ותרי\"ג מצות דאורייתא</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261512\" data-slug=\"likkutei-sichot\" data-id=\"1300261512\">לקו\"ש יתרו כרך כו ס\"ע 424</a> ואילך. אג\"ק שלו ח\"ג ע' רג."],["3239","68","<b>ותרי\"ג מצות. . ארחין דגולגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 219."],["3240","69","<b>והמברר. . בלבוש המתברר</b>: ראה ביאוה\"ז ויגש כו, ד. אמור קמב, ב. שע\"ת נ, ד. מאמרי אדה\"א ויקרא ח\"א ע' קמג. וש\"נ. סה\"מ תרל\"ב ח\"א ע' צד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251177\" data-slug=\"likkutei-sichot\" data-id=\"1300251177\">לקו\"ש וישלח כרך כה ע' 177</a> הערה 77."],["3241","70","<b>מע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."],["3242","71","<b>מתהו שקדם לתקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ. לעיל (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 51."],["3243","72","<b>ונת\"ל</b>: הנחה ד\"ה ואהבת את ה' אלקיך בסופה."],["3244","74","<b>מסוף ועד</b>: לעיל שם: מסוף עולם ועד."],["3245","73","<b>מאור שנברא. . סופו</b>: נסמן לעיל בהנחה שם הערה 83."],["3246","75","<b>ראיות האדם. . מיל</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 84."],["3247","76","<b>ד\"ה הנ\"ל</b>: ואהבת את ה' אלקיך בסופו."],["3248","77","<b>נקודים וברודים הם תהו ותיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380224\" data-slug=\"likkutei-torah\" data-id=\"4001380224\">לקו\"ת אמור לד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380436\" data-slug=\"likkutei-torah\" data-id=\"4001380436\">בהעלותך לא, ג</a>."],["3249","78","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."],["3250","79","<b>שמות ע\"ב</b>: ראה זהר תרומה קלב, ב. פרדס שער פרטי השמות שכ\"א, פ\"ה. מכתב להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק)."]]],[2000480343,"ס\"ג<sup data-n=\"3251\">80</sup> מ\"ה<sup data-n=\"3252\">81</sup> ב\"ן<sup data-n=\"3253\">82</sup>, ומ\"ה מברר ב\"ן<sup data-n=\"3254\">83</sup> ששרשו מס\"ג<sup data-n=\"3255\">84</sup> לכן אחר שנתברר שם ב\"ן יתעלה לשם ס\"ג<sup data-n=\"3256\">85</sup> שלמעלה משם מ\"ה<sup data-n=\"3257\">86</sup>, והנה ס\"ג ומ\"ה שניהם מחודשים<sup data-n=\"3258\">87</sup>, דבנין עולם התהו הי' שלא ע\"ד מקרה והאומר כן הוא מצד קליפות עמלק<sup data-n=\"3259\">90</sup>, פ\"א<sup data-n=\"3260\">91</sup> בנין התהו ע\"מ לסתור וסתירות עולם התהו ע\"מ לבנות<sup data-n=\"3261\">92</sup> עולם התיקון<sup data-n=\"3262\">88</sup> וא\"כ הם מחודשים<sup data-n=\"3263\">89</sup>, אבל שם ע\"ב עליו נא' כל האזרח<sup data-n=\"3264\">93</sup> בישראל<sup data-n=\"3265\">94</sup> שהוא למעלה מהתחדשות, ועל ל' החסידות הנה עולם הוא ל' העלם<sup data-n=\"3266\">95</sup> וכמ\"ש מלמכ\"ע<sup data-n=\"3267\">96</sup> ויש ב' בחי' בהעלם א' שמעלים שיראה ליש ודבר נפרד, הב' עולמות הא\"ס שמעלימים בתוכם אורות הא\"ס וע\"י המצות ממשיכים גילוי אלקות בהעולמות וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"3268\">97</sup>, ונגלה כבוד וראו<sup data-n=\"3269\">99</sup> כל בשר יחדיו כי פי הוי' דיבר<sup data-n=\"3270\">98</sup>, חשף ה' את זרוע קדשו<sup data-n=\"3271\">100</sup>, וזהו שיתגלה לע\"ל ובמצות דעכשיו יש ג\"כ בחי' זו רק שהוא בהעלם ולע\"ל יתגלה בחי' זו, דכל ההפרש בין עכשיו ללע\"ל הוא בין העלם לגילוי",[["3251","80","<b>שמות. . ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["3252","81","<b>שמות. . מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["3253","82","<b>שמות. . ב\"ן</b>: מובא כמ\"פ בע\"ח ופע\"ח וכו'. ז\"ח רות (מהדורת מרגליות) פד, ב."],["3254","83","<b>ומ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."],["3255","84","<b>ב\"ן ששרשו מס\"ג</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג."],["3256","85","<b>ב\"ן יתעלה לשם ס\"ג</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380280\" data-slug=\"likkutei-torah\" data-id=\"4001380280\">לקו\"ת בחוקותי מז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540240\" data-slug=\"torat-chaim\" data-id=\"2300540240\">תו\"ח וארא ח\"א ע, ג</a>. וש\"נ."],["3257","86","<b>ס\"ג שלמעלה משם מ\"ה</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה הערה ד\"ה: שם."],["3258","87","<b>והנה ס\"ג. . שניהם מחודשים</b>: ראה גם לקמן מאמר ד\"ה רני ושמחי על יד הערה 28. ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 34. סה\"מ תרע\"ט ע' תריב. תרפ\"א ע' שלא. תש\"ג ע' 73. אג\"ק מאת כ\"ק אדמו\"ר מהוריי\"צ ח\"ג ע' שלה (בתורת אדה\"ז). ראה גם אוה\"ת ע' תרלו וסה\"מ תרכ\"ו שבהערה 93 דלקמן."],["3259","90","<b>דבנין עולם התהו. . מצד קליפות עמלק</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה *100."],["3260","91","<b>פ\"א. . מחודשים</b>: אוצ\"ל: [פ\"א. . מחודשים]. ראה לעיל הערה 78."],["3261","92","<b>בנין התהו ע\"מ לסתור. . ע\"מ לבנות</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1699."],["3262","88","<b>ס\"ג ומ\"ה. . התהו. . התיקון</b>: ראה גם סה\"מ תש\"ג שם. וש\"נ."],["3263","89","<b>ומ\"ה. . מחודשים</b>: ראה ע\"ח שער שבה\"כ ש\"ט, פ\"ז. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1627."],["3264","93","<b>שם ע\"ב. . כל האזרח בישראל</b>: ראה לקמן הנחה ד\"ה רני ושמחי על יד הערה 30. (לעיל בחלק המאמרים) המשך יונתי ספט\"ו. מאמר ד\"ה רני ושמחי על יד הערה 25. אוה\"ת פ' ראה ע' תרלו<sup data-n=\"e264\">א</sup>. שם כרך ה ע' ב'לט. סה\"מ תרכ\"ו ע' רח ואילך. תרל\"ב ח\"ב ע' תקכט. ע' תקסד. עת\"ר ריש ע' ל. תרע\"ט ע' תריב (בשם הרמ\"ז<sup data-n=\"e265\">ב</sup>]."],["3265","94","<b>כל האזרח בישראל</b>: אמור כג, מב."],["3266","95","<b>עולם הוא ל' העלם</b>: ראה ספר הבהיר ס\"י. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541025\" data-slug=\"torat-chaim\" data-id=\"2300541025\">תו\"ח שמות ח\"א יח, ד</a> הערה 783."],["3267","96","<b>מלמכ\"ע</b>: תהלים קמה, יג."],["3268","97","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["3269","99","<b>כבוד וראו</b>: שם: כבוד הוי' וראו."],["3270","98","<b>ונגלה כבוד. . דיבר</b>: שם מ, ה."],["3271","100","<b>חשף ה' את זרוע קדשו</b>: ישעי' נב, י. ראה גם (לעיל בחלק המאמרים) המשך יונתי על יד הערה 384.\n\n<b>א</b>  ושם שו\"ה ואולי נדפס: מ\"ב. וכנשצ\"ל: ע\"ב.\n\n<b>ב</b>  ראה רמ\"ז לזהר אמור קג, סע\"א: אזרח גי' רי\"ו ה\"ס שם ע\"ב."]]],[2000480344,"(ה' דכל המשכות שיתגלה לע\"ל הוא מה שממשיכים עתה ע\"י המצות, אך מפני שהעולם עדיין לא נזדכך אינו נמשך בגילוי אלא הוא בהעלם ולע\"ל יוצא מהעלם אל הגילוי ע').\n<b>אך</b> צ\"ל יתלבש<sup data-n=\"3272\">101</sup> א\"ס הבבע\"ג בגבול, והענין דהנה במצות יש ב' מדרי' א' עשיית המצוה שהוא רצה\"ע, ב' משארז\"ל נח\"ר לפני שאמרתי ונעשה רצוני<sup data-n=\"3273\">102</sup>, ולפני הוא בחי' א\"ס בעל הרצון שלמעלה מהרצונות פרטים וא\"כ הם בבע\"ג, וזהו שנמשלו המצות לנר וכמ\"ש כי נר מצוה<sup data-n=\"3274\">103</sup> ותורה אור, נר הוא אור וכמו שאומרים בל\"א שבא ליכט לבית שהוא אור שאין הכוונה על השמן או החלב כ\"א על האור, והנה האור אעפ\"י שהוא מוגבל מ\"מ מצינו בו כחות בלתי מוגבלים שאם ידליקו אלף אלפי אלפים נרות מנר א' מ\"מ לא יחסר אורו ולא כמו מים שאם ישאבו הרבה אנשים יחסרו המים אף שיתוסף עוד מהמעין מ\"מ מה שחסר חסר וכן עפר שנוטלין ממקום זה למ\"א חסר ונתוסף שם כמה שחסר כאן, משא\"כ אור וכן אנו מוצאים באור עוד כח הבבע\"ג שמצד האור לא הי' מניעה לדלוק בלי שיעור רק המניעה מצד הפתילה או מצד השמן אבל יתוסף שמן כ\"ד<sup data-n=\"3275\">*104</sup> יוכל לדלוק שית אלפי' שני, ומ\"ש שית אלפי' שנין<sup data-n=\"3276\">104</sup> הוא מפני שאין לנו זמן יותר אבל באמת הי' יכול לדלוק בלי שיעור הרי אף שהוא מוגבל מ\"מ ניכר בו כח הא\"ס הבבע\"ג, ולכן נמשל הקב\"ה לאש<sup data-n=\"3277\">105</sup> שאין לנו למטה משל דק יותר מאש שניכר בו כח הא\"ס הבבע\"ג, וזהו שנמשלו המצות לנר מפני שהם בבחי' בבע\"ג, וכן על הנשמה כתי' כי נר ה'<sup data-n=\"3278\">106</sup> נשמות אדם<sup data-n=\"3279\">107</sup> שנמשל ג\"כ לנר שהוא בבע\"ג, ומ\"ש ימי שנותינו בהם<sup data-n=\"3280\">108</sup> שבעים שנה הוא מפני שא\"צ יותר שבזמן זה הוא מאיר דעיקר כוונת הנר הוא שיאיר בבית לא בשביל טובת הנר כמו\"כ בית הוא הגוף והנה\"ב וצריכים שיאיר אותם ובזמן זה הוא מאיר אותם, אבל הנשמה נר ה' היא חלק ה'<sup data-n=\"3281\">109</sup> והיא תמיד מאיר בבחי' בבע\"ג, וזהו לכל תכלה ראיתי קץ שיש להם השגה שהם מוגבלים, אבל רחבה מצותך מאד שהם בחי' בבע\"ג, ולא כמו שפירשו המפרשים שמפני שלא השיג קיצם לכן אמר שהם בבע\"ג שא\"כ הו\"ל לכל תכלה ראיתי קץ ולמצות אין להם קץ ומאחר שאמר רחבה מצותך מאד היינו שהשיג שהם בבחי' בבע\"ג (ה' ובפרש\"י שכ' אבל המצות אין להם קץ ותכלית אפשר שכיון לזה שהשיג שהם בבחי' בבע\"ג ע') אך הגילוי יהי' לע\"ל והוא ע\"י המצות וכמו עד\"מ כחות הנפש יודעי' ע\"י אמצעות הגוף (ה' ע' מזה בד\"ה להבין מ\"ש באוצ\"ח<sup data-n=\"3282\">110</sup> ע') והיודע הוא",[["3272","101","<b>צ\"ל יתלבש</b>: אוצ\"ל: צ\"ל איך יתלבש."],["3273","102","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">נח\"ר</a>. . ונעשה רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["3274","103","<b>כי נר מצוה</b>: משלי ו, כג."],["3275","*104","<b>כ\"ד</b>: כל דבר."],["3276","104","<b>שית אלפי' שנין</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["3277","105","<b>נמשל הקב\"ה לאש</b>: ואתחנן ד, כד."],["3278","106","<b>כי נר ה'</b>: משלי כ, כז [בהוספת תיבת: כי — ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540519\" data-slug=\"torat-chaim\" data-id=\"2300540519\">תו\"ח בשלח ח\"א רכו, א</a>. וש\"נ]."],["3279","107","<b>נר ה' נשמות אדם</b>: משלי שם [ושם: נשמת — ראה גם לעיל הנחה ד\"ה יפה שעה אחת הא' על יד הערה 14]."],["3280","108","<b>ימי שנותינו בהם</b>: תהלים צ, י. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ספכ\"ט."],["3281","109","<b>חלק ה'</b>: האזינו לב, ט."],["3282","110","<b>בד\"ה להבין מ\"ש באוצ\"ח</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380298\" data-slug=\"likkutei-torah\" data-id=\"4001380298\">לקו\"ת ויקרא בהוספות נא, ג</a>."]]],[2000480345,"הגוף<sup data-n=\"3283\">111</sup> כמו\"כ כאן הגילוי אוא\"ס שיתגלה לע\"ל יהי' ע\"י אמצעות המצות, וזהו לכל תכלה שבג\"ע ראיתי קץ שהם מוגבלים רחבה מצותך מאד שהם בבחי' בבע\"ג כו'.",[["3283","111","<b>הגוף</b>: אוצ\"ל: הנפש."]]],[2000480346,"<h3>אני לדודי הא'</h3>\n<b>ש\"פ תצא תר\"ם לפ\"ק</b>\n<b>אני</b> לדודי<sup data-n=\"3284\">1</sup> ודודי לי הרועה בשושנים<sup data-n=\"3285\">2</sup>. וצ\"ל מה קישור וחבור יש לרועה בשושנים עם אני לדודי ודודי לי. והענין דהנה כתי' ואהבת את ה' אלקיך<sup data-n=\"3286\">3</sup> בכל לבבך ובכל נפשך ובכל מאדך, וצ\"ל והלא אהבה שייך ללב וכמאמר הלב אוהב<sup data-n=\"3287\">4</sup> וא\"כ אחר שא' בכל לבבך מהו ובכל נפשך, ועם<sup data-n=\"3288\">5</sup> בכל נפשך מהו עוד ובכל מאדך. והנה נת\"ל (ה' בד\"ה יפה שעה א' ובד\"ה לכל תכלה ע') ענין ירידת הנשמה בגוף שהיא לצורך עלי'<sup data-n=\"3289\">6</sup> וצ\"ל דהנה\"א מצ\"ע נתעלה<sup data-n=\"3290\">7</sup> לבד מה שנתעלה מצד בירור נה\"ב. והנה יובן זאת עד\"מ מים שהולכים בנהר הולכים לאט לאט וכמו אמת המים שעובר ממקום למקום הולכים בלאט. והוא מפני שאין המים בריבוי והמעיינות אינם נובעים כ\"כ ומועטים המה מעין א' או ב' לכן הם הולכים בלאט. אבל כשמפסיקים הילוכם שסוכרין בנסרים או בעפר ומתקבץ ריבוי מים הם בוקעים הסתימה א\"כ הסתימה פועל תוקף עוז בהילוך המים שילכו בחזקה ובתוקף גדול. וכשאין בהם לבקוע הסתימה הם בוקעים עפר הארץ מצדדי הנהר המגבילים המים וג\"ז כמו בקיעות הסתי' ולפעמים כשאין כח בהם לסתור הסתום הם מתפשטים על כל גדותיו המגבילים ושוטף על השדות הסמוכים. וכמו\"כ יובן בנמשל ג\"כ דהנה הנה\"א הוא חלק הוי'<sup data-n=\"3291\">8</sup> ונת\"ל (ה' ד\"ה ואהבת<sup data-n=\"3292\">9</sup> ע') שיש בו מכל אותיות ה', י' ה' ו' ה', וגם קוש\"י הוא ביטול הרצון שלמעלה מטו\"ד וכמ\"ש כי עם קשה עורף וסלחת<sup data-n=\"3293\">10</sup>, וזהו נר ה' נשמת אדם<sup data-n=\"3294\">11</sup> הנה\"א נק' נר הוי' מפני שהוא חלק ה' והוא נשמת אדם (ה' ע' לעיל",[["3284","1","<b>אני לדודי</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הה' מהמשך יונתי (פי\"ג-פט\"ו). שנדפס לעיל בחלק המאמרים [ושם הפתיחה: והנה כל מה שנת\"ל בענין עליית נה\"א].\nהנחה אחרת מדרוש זה נדפסה לקמן (בחלק הנחות).\nאולי למאמר זה נתכווין לקמן בהנחה ד\"ה ויאמר כו' לך לך על יד הערה 30 (ושם: פ' נצבים)."],["3285","2","<b>אני לדודי ודודי לי הרועה בשושנים</b>: שה\"ש ו, ג."],["3286","3","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה."],["3287","4","<b>הלב אוהב</b>: קה\"ר פ\"א, טז."],["3288","5","<b>ועם</b>: אוצ\"ל: ואם."],["3289","6","<b>ירידת. . לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["3290","7","<b>דהנה\"א מצ\"ע נתעלה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו\"ת בלק עג, סע\"א</a>. לעיל (בחלק המאמרים) בההמשך כאן הערה 304."],["3291","8","<b>חלק הוי'</b>: האזינו לב, ט."],["3292","9","<b>ונת\"ל. . ד\"ה ואהבת</b>: על יד הערה 22 ואילך."],["3293","10","<b>כי עם קשה עורף וסלחת</b>: תשא לד, ט [בדילוג]. ראה שמו\"ר פמ\"ב, ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380589\" data-slug=\"likkutei-torah\" data-id=\"4001380589\">לקו\"ת בלק סז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380603\" data-slug=\"likkutei-torah\" data-id=\"4001380603\">עא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550766\" data-slug=\"torat-chaim\" data-id=\"2300550766\">תו\"ח תצוה ח\"ב שעט, ד</a>. וש\"נ. סה\"מ תרכ\"ז ס\"ע עד ואילך. וש\"נ."],["3294","11","<b>נר ה' נשמת אדם</b>: משלי כ, כז."]]],[2000480347,"בד\"ה ואהבת<sup data-n=\"3295\">12</sup> מבואר שנשמת אדם הוא הנה\"ב והוא אד\"ם א' דם<sup data-n=\"3296\">13</sup> והנר ה' מהפך הנשמת אדם וצ\"ע ע') ונק' נר ונת\"ל (ה' ד\"ה לכל תכלה<sup data-n=\"3297\">14</sup> ע') דעיקר נר שייך על האש והנה טבע האש לעלות למעלה<sup data-n=\"3298\">15</sup> כ\"א כשיש דבר הנאחז ואף גם זאת הוא עולה למעלה תמיד, וכשיש אבוקה הנר נמשך אחר האבוקה, וכמו\"כ יש לו בטבעו התקשרות ודביקות לאלקות ומצ\"ע תיכף כשירד לגוף הי' עולה למעלה רק הגוף והנה\"ב אוחזים אותו דבע\"כ אתה חי<sup data-n=\"3299\">16</sup>.\n<b>והנה</b> כמש\"נ במשל הנ\"ל דכשסוכרין המים ואין בהם כח לבקוע הסתימה הם מתפשטים על גדותיהם כמו\"כ יובן כאן דכשהנה\"ב מעלים ומסתיר והגוף רוצה בתענוגים גשמים והנה\"ב ברצונות זרות, ומ\"מ אינו מונע ומעכב בתומ\"צ אלא שעושה מצוה ג\"כ ולא בקרירות דכשעושה בקרירות ע\"ד מצות אנשים מלומדה<sup data-n=\"3300\">17</sup> ה\"ז כאלו עושה<sup data-n=\"3301\">18</sup> דה\"ה אינו יודע שעושה, אלא שיעשה המצוה כדבעי ויודע שעושה מצוה, וגם מקיים למוד תורה כפי חיובו אם הוא בעל עסק פ\"א שחרית ופ\"א ערבית<sup data-n=\"3302\">19</sup> ואם הוא יושב אהל והגית בו יומם ולילה<sup data-n=\"3303\">20</sup>, ואינו מונע ומעכב לו כלל (בל\"א<sup data-n=\"3304\">21</sup> עס א יז רע כט בייד ע ז„כין) ה\"ז שאין הנה\"ב גס כל כך, דמי שהנה\"ב שלו גס מאד אינו מניח אותו לעשות מצוה כלל, אבל אם אינו מונע אותו מלעשות מצוה ה\"ז הוראה שאין הנה\"ב גס כ\"כ לכן ע\"י ריבוי לימוד התורה בשקידה מתפשטים כחות הנה\"א. וכמו הנהר שמתפשטי' על גדדותיהם<sup data-n=\"3305\">22</sup> מצד הסכירה. ויש ע\"ז עוד משל כמו מים שאין סוכרין אותם כלל רק מפני שנתוסף ריבוי מים וכמו בעת הפשרת שלגים הם שוטפים על הגדות, וכאן שניהם צדקו יחדיו דהנה\"ב הוא מעלים ומסתיר שירצה ברצונות זרות כו' ומ\"מ אינו מונע ומעכב כ\"כ שלא יניח לעשות מצוה לכן ע\"י עסק התורה יבוא לבחי' ובכל נפשך. וצ\"ל מאחר שאמר בכל לבבך מהו ובכל נפשך, אך הנה עיקר האהבה שייך בלב דהלב אוהב אבל הרגל אינו כלי לאהבה, וכן הקרבים וכח הזן והעיכול אינם כלים לאהבה. ומ\"מ אנו כשאדם<sup data-n=\"3306\">23</sup> הוא טרוד מאד שהוא במוח ה\"ז פועל הילוך בהרגלים שיכול להלוך מה שבלא טרדה לא הי' יכול להלוך כ\"כ, א\"כ הרי הרגלים נעשים כלים להרצון, וכמו\"כ כשרוצה לעשות מצוה הוא רץ במרוצה ולא שהוא רוצה לרוץ רק ממילא ומאליו הוא רץ הרי הרגלים נעשים כלים",[["3295","12","<b>לעיל בד\"ה ואהבת</b>: בסופו."],["3296","13","<b>אד\"ם א' דם</b>: ראה מבו\"ש ש\"ה ח\"ב פ\"ה. לעיל הנחה ד\"ה יונתי בחגוי הסלע הערה 85."],["3297","14","<b>ונת\"ל. . ד\"ה לכל תכלה</b>: בסופו."],["3298","15","<b>טבע האש לעלות למעלה</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ד, ה\"ב. תניא פי\"ט. סה\"מ תרל\"ח ע' תצא. וש\"נ."],["3299","16","<b>דבע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["3300","17","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' כו' נביאים וכתובים הערה 12."],["3301","18","<b>כאלו עושה</b>: אוצ\"ל: כאלו אינו עושה."],["3302","19","<b>פ\"א שחרית ופ\"א ערבית</b>: ראה מנחות צט, א. הל' ת\"ת לאדה\"ז פ\"ג, ה\"ד."],["3303","20","<b>והגית בו יומם ולילה</b>: יהושע א, ה."],["3304","21","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211457\" data-slug=\"likkutei-sichot\" data-id=\"1300211457\">לקו\"ש משפטים כרך כא ע' 448</a> הערה 15."],["3305","22","<b>גדדותיהם</b>: אוצ\"ל: גדותיהם."],["3306","23","<b>אנו כשאדם</b>: אוצ\"ל: אנו רואים כשאדם."]]],[2000480348,"להאהבה, וכן מצד טרדה יכול לשכוח אפי' על כח הדוחה וכן על זמן אכילה והשינה, וזהו בכל נפשך שגם האברים חצונים יהיו כלים להאהבה.\n<b>אך</b> הנה כ\"ז כשאין הנה\"א<sup data-n=\"3307\">24</sup> מונע ומסתיר, אבל כשהנה\"א מונע ומסתיר ואין מניחו לעשות מצוה, ה\"ז כמו עד\"מ המים כשסוכרין אותם והם בוקעים הסתימה מצד התוקף עוז כמו\"כ כשהנה\"ב סותם ומונע הילוך נה\"א אז הוא בוקע הסתימה ויוצא ברעש גדול וזהו ובכל מאדך, דבכל לבבך הוא לפי הגבלת הלב, ובכל נפשך הוא רק שגם כחות החיצונים יהיו כלים לאהבה, אבל מ\"מ לפ\"ע הגבלת הכחות, דריצת רגלים הוא לפ\"ע כוחם ולא ירצו<sup data-n=\"3308\">25</sup> יותר מכפי כוחם, אבל בכל מאדך הוא למעלה מהגבלות הכלים לגמרי וכמ\"ש מי לי בשמים<sup data-n=\"3309\">26</sup> ועמך לא חפצתי בארץ שלא יחפוץ בפנימיות הרצון<sup data-n=\"3310\">27</sup> לא געה\"ע ולא געה\"ת ולא עוה\"ב (ובפ\"א<sup data-n=\"3311\">28</sup> ואפי' הגילוים שיהיו אז) דכל מה שעמך לא חפצתי וכמ\"ש כי עמך מקור חיים<sup data-n=\"3312\">29</sup> אפי' מקור החיים ומקור טפל<sup data-n=\"3313\">30</sup> ובטל לך, וכלליות העולמות הם רק מהארה בעלמא, ולכן אני ה' לא שניתי<sup data-n=\"3314\">31</sup> שלא יש שום שנוי בין קודם הבריאה לאחר, אתה הוא קודם שנבה\"ע<sup data-n=\"3315\">32</sup> ואתה הוא לאחר שנבה\"ע, והלא נבראו העולמות וכמ\"ש בראשית ברא<sup data-n=\"3316\">33</sup>, אך מפני שהם מהארה לבד ואין הארה פועל שינוי בעצם ואפי' אצי' העליון אי' בעה\"ק אתה הוא קודם שנאצל<sup data-n=\"3317\">34</sup> ואתה הוא לאחר שנאצל דבאצי' יש ב' פי' א' שהוא גילוי העלם מאלקות<sup data-n=\"3318\">35</sup> הב' שהוא הפרשת",[["3307","24","<b>הנה\"א</b>: אוצ\"ל: הנה\"ב."],["3308","25","<b>ירצו</b>: אוצ\"ל: ירוצו."],["3309","26","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גל נעול ובהערה 65."],["3310","27","<b>יחפוץ בפנימיות הרצון</b>: ראה שו\"ת הצ\"צ אבהע\"ז ח\"ב סרס\"ג (ח, ג). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381244\" data-slug=\"likkutei-torah\" data-id=\"4001381244\">לקו\"ת שה\"ש כח, ד</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540822\" data-slug=\"torat-chaim\" data-id=\"2300540822\">תו\"ח בא ח\"א קכה, ד</a> ובהערה 597. סה\"מ ליקוט ב' ע' רעו."],["3311","28","<b>ובפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."],["3312","29","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380213\" data-slug=\"likkutei-torah\" data-id=\"4001380213\">לקו\"ת אמור לא, ד</a>. לעיל ח\"א (בחלק המאמרים) ד\"ה ואעשך לגוי גדול ובהערה 50."],["3313","30","<b>ומקור טפל</b>: אוצ\"ל: ומקור התענוגים טפל."],["3314","31","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 82."],["3315","32","<b>אתה הוא קודם שנברה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3316","33","<b>בראשית ברא</b>: בראשית א, א."],["3317","34","<b>אי' בעבה\"ק אתה הוא קודם שנאצל</b>: וכ\"ה לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 33. ראה גם שם חלק היחוד פ\"ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460024\" data-slug=\"or-hatorah-hb\" data-id=\"8316460024\">אוה\"ת יתרו ע' תתלט</a>. סה\"מ תרל\"ח ע' שיט."],["3318","35","<b>דבאצי'. . שהוא גילוי העלם מאלקות</b>: ראה עבודת הקודש שם<sup data-n=\"e266\">1</sup>. מערכת האלקות פ\"ג<sup data-n=\"e267\">2</sup>. פרדס שער ט\"ז שער אבי\"ע3. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370339\" data-slug=\"torah-or\" data-id=\"3901370339\">תו\"א משפטים עו, ב</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' רסב ואילך (נו\"ש). ע' רפז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830298\" data-slug=\"or-hatorah-hb\" data-id=\"8158830298\">אוה\"ת בלק ע' תתקפד</a> ואילך. ענינים ס\"ע רא ואילך. סה\"מ תרל\"ב ח\"א ע' מב. וש\"נ. קונט' בר מצוה תרנ\"ג ע' לה. וש\"נ."],["e266","1","מובא בשמו בכ\"מ ומהם: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480243\" data-slug=\"or-hatorah-hb\" data-id=\"8316480243\">אוה\"ת וירא כרך ד ס\"ע 1480</a>. חנוכה כרך ה' ע' תתקנג [ושם: בעה\"ק ז\"א [ח\"א] פ' בגד\"ה]. ר\"ה ע' א'תמא. אוה\"ת על ענינים ע' רסז. ביאוה\"ז להצ\"צ כרך א' ע' כט. ע' תז. (ע' תעה). כרך ב ע' תתרמד. ספר החקירה ע' 112. סה\"מ תש\"ג ע' 155 בהערה."],["e267","2","מובא בשמו בכ\"מ ומהם: אוה\"ת וירא־ ר\"ה־ ענינים־ ביאוה\"ז שם. הגהות לד\"ה פתח אלי' תרנ\"ח ע' ט ואילך וע' סא ואילך. סה\"מ תרס\"ח ע' ריב. סה\"מ תרצ\"ו ע' 104. תש\"ג ע' 129. ע' 155 בהערה.\n3)מובא בשמו בכ\"מ ומהם: אוה\"ת ר\"ה־ ביאוה\"ז שם."]]],[2000480349,"הארה<sup data-n=\"3319\">36</sup>, ובשניהם שייך לומר קודם הגילוי וההפרשה כו', דאצי' הוא אלקות<sup data-n=\"3320\">37</sup> שקורין בל\"א געטליך ולא אלוה<sup data-n=\"3321\">38</sup> לכן אין בחיק אצי' לברוא יש מאין רק בכח האיהו שמתייחד עם גרמוהי<sup data-n=\"3322\">39</sup>, שאם נא' דאצי' הוא אלוקה א\"כ שם אלקים שמתלבש בהכלי מה חילוק יש בין האור להכלי אלא שזה אלוקה וזה אלקות, א\"כ כלליות השתל' העולמות הם משם והארה בעלמא ולמה ירצה בההארה יותר טוב לו שירצה בהעצם וזהו בכל מאדך שיהי' לו רצון פשוט לאלקות.\n<b>והנה</b> עתה נתבונן למי נייחס האהבה להנה\"א או להנה\"ב, הגם שהסתימה הוא מהנה\"ב ומזה בא להאהבה מ\"מ עצם האהבה בא מצד הנה\"א, וכמו המים כשסותמין אותם שבוקעים הסתימה בתוקף עוז הוא מעצם כח המים כמו\"כ כאן הוא ממה שנתקבץ כחות הנה\"א עצמו ולא שנתוסף לו כחות הנה\"ב א\"כ האהבה הוא מיוחס להנה\"א, רק שבלא הגוף והנה\"ב לא הי' בא לאהבה כזו וכמ\"ש גבי מלאכים ויעמידם לעד לעולם<sup data-n=\"3323\">40</sup> אפי' בבחי' לעד לעולם שהם עליות המדרי' הם בבחי' עמידה שהכל רק במדרי' אחת, וכמו\"כ גבי נשמות כתי' חי ה' אשר עמדתי לפניו<sup data-n=\"3324\">41</sup> רק שמלאכים הם מחיצוניות הכלים ונשמות מפנימיות הכלים<sup data-n=\"3325\">42</sup> והוא שנבראו ונוצרו כך אבל לא שנתעלה לבחי' פנימיות הכלים, אבל ע\"י שנתלבשה בגוף והנה\"ב יוכל להתעלות למעלה מעלה וכמשנת\"ל (ה' ד\"ה יפה שעה א'<sup data-n=\"3326\">43</sup> ע') דהעלי' היא מבחי' איהו וגרמוהי דהנשמה אף שטהורה היא דשרשה מטה\"ע<sup data-n=\"3327\">44</sup> זהו בחי' איהו וגרמוהי והעלי' לבחי' איהו וחיוהי שהוא בבע\"ג והוא גילוי ההעלם וזהו\"ע לאשתאבא בגופא דמלכא<sup data-n=\"3328\">45</sup>, אך עיקר העולה הוא הנה\"א מצ\"ע וכמ\"ש רוח האדם העולה היא למעלה<sup data-n=\"3329\">46</sup> שיש בה כח לעלות, והוא ע\"י סתימה דנה\"ב.",[["3319","36","<b>דבאצי'. . שהוא הפרשת הארה</b>: ראה פרדס שער אבי\"ע שט\"ז, רפ\"א. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1600."],["3320","37","<b>דאצי' הוא אלקות</b>: ראה עבודת הקדש חלק היחוד פ\"ב. רפ\"ד. לעיל שם הערה 1599."],["3321","38","<b>דאצי'. . געטליך ולא אלוה</b>: ראה גם סהמ\"צ להצ\"צ ע' נב וע' קלב ואילך. המשך וככה תרל\"ז פע\"ח. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית ע' תתרמו. סה\"מ תרל\"ח ע' תכה. וש\"נ."],["3322","39","<b>האיהו. . גרמוהי</b>: ת\"ז בהקדמה (ג, ב). אגה\"ק ס\"כ."],["3323","40","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["3324","41","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח סב, סע\"ד</a>. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["3325","42","<b>שמלאכים הם מחיצוניות הכלים. . מפנימיות הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540226\" data-slug=\"torat-chaim\" data-id=\"2300540226\">תו\"ח בשלח ח\"א רמ, ד</a> ואילך."],["3326","43","<b>וכמשנת\"ל. . ד\"ה יפה שעה א'</b>: על יד הערה 64."],["3327","44","<b>דהנשמה. . מטה\"ע</b>: נסמן לעיל שם הערה 61."],["3328","45","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 51."],["3329","46","<b>רוח האדם העולה היא למעלה</b>: ראה קהלת ג, כא [ושם: בני האדם]."]]],[2000480350,"<b>אך</b> לפי משנת\"ל דהאהבה בא מצד הסתימה, והסותם הוא הנה\"ב וכוונתו שלא יעשה רצונו וכמ\"ש בזהר עד\"מ זונה עם בן מלך<sup data-n=\"3330\">47</sup> שכוונתה שלא יתפתה, ומ\"מ צריכה לעוררו בחום ותאווה, וכשנשלם המכוון שלא נתפתה לו<sup data-n=\"3331\">48</sup> הרי אין הקב\"ה מקפח שכר<sup data-n=\"3332\">49</sup> כל ברי' וצריכי' ליתן לו שכר, ובאמת כ\"ה שנותנין לו שכר. ויובן זאת ממשל הנ\"ל דהנה כשסוכרין המים בנסרים או בעפר ואח\"כ כשהמים מתגברי' וסותרים הסתימה מוליכים איתם הנסרים הגם שאין בהם כח ההילוך מ\"מ המים פועלים בהם הילוך, וכמו\"כ העפר שטבעו לירד מ\"מ המים פועלים בהם הילוך ומוליכים אותם דכמו שפעלו הם בהמים היפוך טבעם למנוע הילוכם, כמו\"כ כשהמים מתגברים עליהם פועלים בהם הילוך שהוא היפך טבעם, רק שהנסרים שטים ע\"פ המים והעפר הולך מתחת למים, וכמו\"כ יובן בנמשל דהנה אדם יסודו מעפר<sup data-n=\"3333\">50</sup> וכמ\"ש וייצר ה' אלקי'<sup data-n=\"3334\">51</sup> את האדם עפר מהאדמה, וקודם שנפח בו נ\"ח הי' הגוף מציאות בפ\"ע והי' בו חיות וכמשנת\"ל (ה' ד\"ה הנ\"ל<sup data-n=\"3335\">52</sup> ע') ככה צ\"ל שגם האדם שנולד מאדם הגוף הוא מציאות בפ\"ע ויש לו חיות, ומשארז\"ל מאימתי הנשמה ניתנה באדם משעת יצירתו שלא יסריח<sup data-n=\"3336\">53</sup> צ\"ל שהוא חיות הבשר, ומשארז\"ל מלמדין אותו כל התורה<sup data-n=\"3337\">54</sup> כולו הלא מבואר בלקו\"ת ג\"כ שהוא כח על לימוד התורה<sup data-n=\"3338\">55</sup> לאחר יציאתו לאויר העולם, וא\"כ מוכרח לומר שהוא רק בהכחות הנעלמים שאם הלימוד הוא בהכחות נגלים הרי הי' זה כמו טבע בנפשו ללמוד תורה אפי' לאחר שסרטו המלאך, והאמת לא כן הוא שאין הגוף והנה\"ב מסכימים כלל ללמוד תורה, אלא שהוא רק בהכחות הנעלמים, [אך א\"צ לכ\"ז דאיך שיהי'] מוכרח לומר שיש מציאות הגוף בפ\"ע והוא מעפר רק שהוא עפר חי והוא נעשה חומר לקבל צורת הנפש האדם וכמשנת\"ל (ה' ד\"ה ואהבת ע') וראי' לזה הוא מגלגולים נפש האדם מגלגל בחומר הבהמה<sup data-n=\"3339\">57</sup> וכמ\"ש שם<sup data-n=\"3340\">56</sup>. וכמאמר הכל הי' מן העפר<sup data-n=\"3341\">58</sup> אפי' גלגל חמה ואינו בערך לגבי עפר גשמי רק שיש בו עפרורית וההילוך פועל בהעפרורית, ולפ\"ז אין בהגוף כח ההילוך, והנה\"ב עליו נא' רוח היורדת למטה בארץ<sup data-n=\"3342\">59</sup>, והנה\"א כשמתעלה מעלה עמו הגוף והנה\"ב ג\"כ וכמו מים שפועלים הילוך בהנסרים והעפר, כמו\"כ הנה\"א פועל הילוך בהגוף והנה\"ב.",[["3330","47","<b>עד\"מ זונה עם בן מלך</b>: ראה זהר תרומה קסג, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט</a> ופכ\"ט ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680131\" data-slug=\"torat-chaim\" data-id=\"2300680131\">תו\"ח מקץ רטז, ד</a> הערה 67."],["3331","48","<b>לו</b>: אוצ\"ל: לה."],["3332","49","<b>אין הקב\"ה מקפח שכר</b>: ב\"ק לח, ב."],["3333","50","<b>אדם יסודו מעפר</b>: נוסח כי כשמך (תפלת מוסף לימים נוראים — קודם כתר)."],["3334","51","<b>וייצר ה' אלקי'</b>: בראשית ב, ז."],["3335","52","<b>וכמשנת\"ל. . ד\"ה הנ\"ל</b>: יפה שעה אחת על יד הערה 78 ואילך."],["3336","53","<b>מאימתי הנשמה ניתנה באדם. . יסריח</b>: ראה לעיל (בחלק המאמרים) המשך יונתי כאן הערות 317-318."],["3337","54","<b>מלמדין אותו כל התורה</b>: ראה נדה ל, ב. מפרשי הע\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540931\" data-slug=\"torat-chaim\" data-id=\"2300540931\">תו\"ח בא ח\"א קכט, א</a>. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540997\" data-slug=\"torat-chaim\" data-id=\"2300540997\">בשלח קפ, ג</a>. וש\"נ."],["3338","55","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380488\" data-slug=\"likkutei-torah\" data-id=\"4001380488\">לקו\"ת</a>. . לימוד התורה</b>: שלח מד, א."],["3339","57","<b>מגלגולים. . מגלגל </b>[כ\"ה בגוכתי\"ק]<b> בחומר הבהמה</b>: ראה לעיל (בחלק המאמרים) המשך יונתי הערות 109-110."],["3340","56","<b>וכמשנת\"ל. . ד\"ה ואהבת. . וכמ\"ש שם</b>: בפיסקא וככל המשל הזה."],["3341","58","<b>הכל הי' מן העפר</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם הערה 63."],["3342","59","<b>רוח היורדת למטה בארץ</b>: ע\"פ קהלת ג, כא."]]],[2000480351,"<b>והנה</b> כמשנת\"ל יובן במצות ג\"כ אך באו\"א לגמרי, דהנה תרי\"ג מצות הם תרי\"ג ארחין דגולגלתא<sup data-n=\"3343\">60</sup> וכמו אורח ושביל שהולך ממקום למקור<sup data-n=\"3344\">61</sup> כמו\"כ המצוה ה\"ז צנור שיומשך למטה, ובמצות יש ג\"כ גוף ונפש וכמו שופר גשמי שהוא קרן של איל<sup data-n=\"3345\">62</sup> הוא גשמי ומה שהוא מצוה הרי מלובש בו הרצה\"ע הוא הנפש, ואימתי הוא מצוה כשאיש הישראלי עושה אותה וכמ\"ש צו אל בנ\"י<sup data-n=\"3346\">63</sup> ר\"ל צו הוא ל' צוותא וחיבור<sup data-n=\"3347\">64</sup> והיינו כשתחבר את בנ\"י עם המצוה אז הוא מצוה, דאפי' תפילין וציצית אם לא יקיים אותם הרי תפילין הם תשמישה קדושה<sup data-n=\"3348\">65</sup> וציצית תשמישי מצוה<sup data-n=\"3349\">66</sup> ומכ\"ש ד' מינים שבלולב כמו אתרוג אם יאכל אותו בלא ברכה ה\"ה מוריד אותו, ואם אוכל אותו (ה' שלא לשם שמים<sup data-n=\"3350\">67</sup> לא נתחדש בו דבר שהוא מנוגה והוא מחי' את (ה' מי שהוא ע') מק\"נ<sup data-n=\"3351\">68</sup>, וכשעושה אותו למצוה ה\"ז נעשה כלי להרצה\"ע ועי\"ז מתעלה לבחי' בעהר\"צ. והנה העיקר הוא העושה וכמו המים שסותרים הסתימה הגם שהוא מצד הסתימה מ\"מ העיקר הם המים הסותרים את הסתימה, כמו\"כ יובן כאן ג\"כ שהעיקר הוא האדם. ומ\"מ אינו דומה שהסתימה הוא רק לפעול תוקף עוז ההילוך, משא\"כ כאן אם לא הדבר לא הי' מציאות מצות כלל (ה' בגשמיות וצ\"ע ע'). והנה ע\"י הבירורים האדם מתעלה לשם ע\"ב<sup data-n=\"3352\">69</sup> שלמעלה מתהו והדבר גשמי לשרשו שם ס\"ג. אך צ\"ל דענין שבה\"כ הוא ג\"כ ירידה צורך עלי' דהשבירה לא הי' במקרה דזה שייך לקליפות עמלק<sup data-n=\"3353\">70</sup> כ\"א בונה כו' א\"כ מהו העלי' מה שמתעלים לשרשם, וצ\"ל דהשבירה הי' בז\"ת<sup data-n=\"3354\">72</sup> והם מתעלים לג\"ר דס\"ג, אך לפי משנת\"ל (ה' ד\"ה לכל תכלה<sup data-n=\"3355\">73</sup> ע') דהג\"ר שבכל עולם הוא הג\"ע של עולם זה א\"כ מהו ההעלאה,",[["3343","60","<b>תרי\"ג מצות. . ארחין דגולגלתא</b>: ראה לעיל הנחה ד\"ה לכל תכלה ראיתי קץ ובהערות 67-68."],["3344","61","<b>למקור</b>: אוצ\"ל: למקום."],["3345","62","<b>שופר. . קרן של איל</b>: ראה ר\"ה טז, א. מאמרי אדה\"א דברים ח\"ג ע' תתצז. וש\"נ."],["3346","63","<b>צו אל<sup data-n=\"e268\">*</sup> בנ\"י</b>: אוצ\"ל: צו את בנ\"י — ויקרא כד, ב. ועוד."],["3347","64","<b>צו הוא ל' צוותא וחיבור</b>: ראה גם סידור שחרית לו, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380624\" data-slug=\"likkutei-torah\" data-id=\"4001380624\">לקו\"ת פינחס עו, א</a>."],["3348","65","<b>תפילין הם תשמישה קדושה</b>: כ\"ה בכ\"מ — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 55. ראה שו\"ע אדה\"ז הל' תפילין סמ\"ב, ס\"ו."],["3349","66","<b>וציצית תשמישי מצוה</b>: ראה שו\"ע אדה\"ז הל' ציצית רסכ\"א. הל' תפילין שם."],["3350","67","<b>שמים</b>: אוצ\"ל: שמים ע')."],["3351","68","<b>את. . מק\"נ</b>: כ\"ה בגוכתי\"ק. וראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 62."],["3352","69","<b>ע\"ב. . ס\"ג. . ומ\"ה. . ב\"ן</b>: ראה לעיל הנחה ד\"ה לכל תכלה ראיתי קץ ובהערות 79-82."],["3353","70","<b>דהשבירה. . לקליפות עמלק</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם בין הערות 99-100."],["3354","72","<b>דהשבירה הי' בז\"ת</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370436\" data-slug=\"torah-or\" data-id=\"3901370436\">תו\"א מג\"א צז, רע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380841\" data-slug=\"likkutei-torah\" data-id=\"4001380841\">לקו\"ת פ' ראה לא, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540330\" data-slug=\"torat-chaim\" data-id=\"2300540330\">תו\"ח בא ח\"א קיז, רע\"ג</a>. (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540915\" data-slug=\"torat-chaim\" data-id=\"2300540915\">וארא פה, ג</a>. וש\"נ)."],["3355","73","<b>משנת\"ל. . ד\"ה לכל תכלה</b>: על יד הערה 49."],["e268","*","ראה גם לקמן הנחה ד\"ה אני לדודי הב' על יד הערה 24 [ושם: צו אל ישראל]. ד\"ה למה קדמה שמע לוהי' אם שמוע על יד הערה 12. המשך תער\"ב ח\"ג מהדורת תשנ\"ב ע' א'תג. אבל במהדורת תשל\"ז: צו את בנ\"י."]]],[2000480352,"וי\"ל דחו\"ב הם תרדל\"מ<sup data-n=\"3356\">74</sup> וכמו\"כ ע\"ב ס\"ג, ועוי\"ל דמשנת\"ל דג\"ר הוא ג\"ע בתהו היינו ג\"ר דז\"ת אבל משנת\"ל שהעלי' בג\"ר היינו במוחין עצמן. אך באמת א\"צ לכ\"ז דמשנת\"ל שהג\"ר הוא ג\"ע היינו בתיקון שיש שם התכללות אבל בתהו שאין התכללות אפי' במדות כ\"ש במוחין עם מדות, [והאדם מתעלה] לשם ע\"ב ועז\"נ כל<sup data-n=\"3357\">75</sup> האזרח בישראל<sup data-n=\"3358\">76</sup> דס\"ג ומ\"ה שניהם מחודשים<sup data-n=\"3359\">77</sup> דבנין התהו<sup data-n=\"3360\">71</sup> הי' ע\"מ לסתור וסותר ע\"מ לבנות אבל ע\"ב נק' אזרח שלמעלה מהתחדשות. וזהו ישבו בסוכת שעכשיו הוא בבחי' מקיף אבל לע\"ל יאיר ויתגלה למטה וזהו משכיל לאיתן האזרחי<sup data-n=\"3361\">78</sup>.\n<b>וזהו</b> אני לדודי ודודי לי הרועה בשושנים וארז\"ל א\"ת שושנים אלא ששונים בהלכות<sup data-n=\"3362\">79</sup> ולמה נמשלו לשושנים מה שושנה אית לה תריסר<sup data-n=\"3363\">81</sup> עלין<sup data-n=\"3364\">80</sup> דסחרין לשושנה כמו\"כ בתורה יש י\"ג מדות שהתורה נדרשת בהם<sup data-n=\"3365\">82</sup>, דהנה בתורה מבואר ענין המצות כמו שופר אך הוא בקיצור נמרץ, ובתושבע\"פ מפרש ומבאר איך לעשות המצוה, שיעור תקיעה<sup data-n=\"3366\">83</sup> ג' תרועות שיעור תרועות שלש יבבות, וזהו נק' הלכות וכמו\"כ שארי המצות, והוא ע\"י יג\"מ כלל ופרט כו', וע\"י ששונים בהלכות מתעלים לבחי' אני לדודי ודודי לי שס\"ת ד' יודי\"ן והוא שם ע\"ב<sup data-n=\"3367\">84</sup> דשם מ\"ה הוא במילוי אלפין<sup data-n=\"3368\">85</sup> ושם ב\"ן כו' (ה' במילוי ההי\"ן<sup data-n=\"3369\">86</sup> ע') ושם ס\"ג יו\"ד א'<sup data-n=\"3370\">87</sup> ושם ע\"ב כולו יודי\"ן, וע\"י העסק בתומ\"צ מתעלה הנה\"א לבחי' שם ע\"ב דיודין. וזהו אני לדודי כו' דע\"י הרועה בשושנים יבוא לבחי' אני לדודי ודודי לי כו'.",[["3356","74","<b>דחו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["3357","75","<b>לשם ע\"ב. . כל האזרח בישראל</b>: ראה לעיל הנחה ד\"ה לכל תכלה ובהערה 93."],["3358","76","<b>כל האזרח בישראל</b>: אמור כג, מב."],["3359","77","<b>דס\"ג ומ\"ה שניהם מחודשים</b>: ראה לעיל שם הערות 89. 87."],["3360","71","<b>בונה כו'. . דבנין התהו</b>: ראה לעיל שם הערה 102."],["3361","78","<b>משכיל לאיתן האזרחי</b>: תהלים פט, א."],["3362","79","<b>אל תקרי שושנים אלא ששונים בהלכות</b>: ראה זח\"ב תוספות עדר, א. מאמרי אדה\"א דברים ח\"ד ע' א'קפח. וש\"נ. סה\"מ תרל\"ח ע' רפה. וש\"נ. לקמן הנחה ד\"ה אני לדודי הב' בסופה."],["3363","81","<b>תריסר</b>: אוצ\"ל כבהקדמת הזהר תליסר. וראה בדרך אמת שם אות ו."],["3364","80","<b>שושנה. . תריסר עלין</b>: ראה לעיל (בחלק המאמרים) המשך יונתי כאן הערה 338."],["3365","82","<b>י\"ג מדות שהתורה נדרשת בהם</b>: תו\"כ ר\"פ ויקרא."],["3366","83","<b>שיעור תקיעה</b>: ר\"ה לג, ב (במשנה)."],["3367","84","<b>אני לדודי. . ד' יודי\"ן. . ע\"ב</b>: ראה לעיל (בחלק המאמרים) שם הערות 341-340."],["3368","85","<b>דשם מ\"ה הוא במילוי אלפין</b>: ראה ע\"ח שער לאה ורחל של\"ח, פ\"א. פ\"ב. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"א שמות ח\"ב ע' תמה. וש\"נ."],["3369","86","<b>ושם ב\"ן. . במילוי ההי\"ן</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג."],["3370","87","<b>ושם ס\"ג יו\"ד א'</b>: וכ\"ה גם לקמן (בחלק ההנחות) בהנחה כאן. ואולי צ\"ל: ג' יודי\"ן א' (או ”וא\"ו\") — ראה זהר רע\"מ פינחס רמו, ב. לוח השמות במק\"מ בסוף בראשית קכו, ב. ע\"ח שער אח\"פ שער ד, פ\"ג."]]],[2000480353,"<h3>אני לדודי הב'</h3>\n<b>ש\"פ תבוא תר\"ם לפ\"ק</b>\n<b>אני</b> לדודי<sup data-n=\"3371\">1</sup> ודודי לי ר\"ת אלול<sup data-n=\"3372\">3</sup> וס\"ת ד' יודי\"ן<sup data-n=\"3373\">4</sup> והם מ' יום שמר\"ח אלול עד אחר יוהכ\"פ ועליהם נא' ואנכי עמדתי בהר<sup data-n=\"3374\">5</sup> כימים הראשונים מה הראשונים ברצון<sup data-n=\"3375\">6</sup> אף האחרונים ברצון, ולזה אמר הרועה בשושנים<sup data-n=\"3376\">2</sup> מה שושנה אית לה תליסר עלין<sup data-n=\"3377\">7</sup> דסחרין לשושנה כך כנס\"י אית לה תליסר מכילין דרחמים דסחרין לה<sup data-n=\"3378\">8</sup>. והנה כתי' דודי לי ואני לו<sup data-n=\"3379\">9</sup> הרועה בשושנים, ופסוק זה קאי על יצי\"מ וקרי\"ס כ\"ה במפרשי'<sup data-n=\"3380\">10</sup> ובמדר'<sup data-n=\"3381\">11</sup>, וצ\"ל מה שייך לזה הרועה בשושנים דלכאור' י\"ג ת\"ד<sup data-n=\"3382\">12</sup> אין להם שייכות עם תורה. אך הנה בפסוק אחר כתי' אני לדודי ועלי תשוקתו<sup data-n=\"3383\">13</sup>, ותי' תשוקתו מורה על חמדת הלב כביכול של הקב\"ה לכנס\"י יותר מאני לדודי, וצ\"ל למה צריך להתשוקה, וכמו שמקשים המפרשים על מ\"ש ועבדתם את ה' אלקיכם<sup data-n=\"3384\">14</sup>, ולעבדו בכל לבבכם<sup data-n=\"3385\">15</sup>, מה צורך יש לעבודה למעלה, דאנת הוא שלימותא דכולא<sup data-n=\"3386\">16</sup>, דלמטה שייך עבודת עבד להאדון שהוא חסר והעבד משלים חסרונו, אבל למעלה אינו שייך זה, וכמו\"כ יש להקשות ג\"כ על מ\"ש ועלי תשוקתו.\n<b>והענין</b> דהנה אמרז\"ל נתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"3387\">17</sup> וג\"ז צ\"ל למה נתאווה<sup data-n=\"3388\">18</sup> כו'. אך באמת אינו ידוע לנו למה נתאווה אף שבאמת מס' יש ע\"ז טעם אך אינו ידועה<sup data-n=\"3389\">19</sup> ומושג לנו הטעם. אבל זה אנו יודעים שנתאווה. וכן",[["3371","1","<b>אני לדודי</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הו' מהמשך יונתי (פט\"ז-פי\"ח). שנדפס לעיל בחלק המאמרים [ושם הפתיחה: והנה אני לדודי ודודי לי].\nהנחה אחרת מדרוש זה נדפסה לקמן (בחלק ההנחות)."],["3372","3","<b>אני לדודי. . ר\"ת אלול</b>: ראה אבודרהם סדר תפלת ר\"ה ופירושה בשם הדרשנים. דרשות ר\"י אבן שועיב ס\"פ שופטים בשם המדרש. סדר היום סדר ר\"ח אלול. ב\"ח לטאו\"ח סתקפ\"א ד\"ה והעבירו בשם האחרונים. מאמרי אדה\"א דברים ח\"א ע' שלב. וש\"נ."],["3373","4","<b>וס\"ת ד' יודי\"ן</b>: אבודרהם־ דרשות ר\"י אבן שועיב־ ב\"ח שם. אילת אהבים לר\"ש אלקבץ שה\"ש ו, ג. ר\"ח שער התשובה פ\"ד (ד\"ה עוד יש)."],["3374","5","<b>ואנכי עמדתי בהר</b>: עקב י, י."],["3375","6","<b>מה הראשונים ברצון</b>: ראה רש\"י עקב ט, יח. י, י. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131272\" data-slug=\"likkutei-sichot\" data-id=\"1300131272\">לקו\"ש</a> בין המצרים כרך יג ע' 266 בהערה."],["3376","2","<b>אני לדודי ודודי לי. . הרועה בשושנים</b>: שה\"ש ו, ג."],["3377","7","<b>מה שושנה. . תליסר עלין</b>: ראה לעיל (בחלק המאמרים) המשך יונתי הערה 338."],["3378","8","<b>מה שושנה. . דסחרין לה</b>: ראה (לעיל שם) בההמשך כאן הערה 345."],["3379","9","<b>דודי לי ואני לו</b>: שה\"ש ב, טז."],["3380","10","<b>במפרשי'</b>: ראה רש\"י שם."],["3381","11","<b>ובמדר'</b>: ראה שהש\"ר כאן פ\"ב, א (ובהפסוקים שלפנ\"ז)."],["3382","12","<b>י\"ג ת\"ד</b>: ראה זהר תרומה (ספדצ\"נ פ\"ת) קעז, א."],["3383","13","<b>אני לדודי ועלי תשוקתו</b>: שה\"ש ז, יא."],["3384","14","<b>ועבדתם את ה' אלקיכם</b>: משפטים כג, כה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380453\" data-slug=\"likkutei-torah\" data-id=\"4001380453\">לקו\"ת בהעלותך לה, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">בלק ע, ג</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' רסב. ענינים ע' רמה ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010098\" data-slug=\"or-hatorah-hb\" data-id=\"8159010098\">אוה\"ת משפטים ע' א'קצח</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010124\" data-slug=\"or-hatorah-hb\" data-id=\"8159010124\">ע' א'רו</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010174\" data-slug=\"or-hatorah-hb\" data-id=\"8159010174\">ע' א'ריט</a> ואילך. ע' א'רמד. סה\"מ תרל\"ג ח\"ב ע' תלב."],["3385","15","<b>ולעבדו בכל לבבכם</b>: עקב יא, יג."],["3386","16","<b>דאנת הוא שלימותא דכולא</b>: ת\"ז בהקדמה יז, ב."],["3387","17","<b>נתאווה הקב\"ה. . דירה בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1693."],["3388","18","<b>למה נתאווה</b>: ראה גם לעיל בחלק המאמרים) שם ובהערה 1776."],["3389","19","<b>ידועה</b>: כ\"ה בגוכתי\"ק."]]],[2000480354,"ארז\"ל ע\"פ שוקיו ועמודיו שש<sup data-n=\"3390\">20</sup> שוקיו זה עולם שנשתוקק הקב\"ה לבראותו<sup data-n=\"3391\">21</sup> עמודי שש שנברא בשש, מפני מה נשתוקק אין אנו יודעין אבל זה אנו יודעים שנשתוקק. ולקרב קצת אל השכל מהו\"ע נתאווה הקב\"ה להיות לו דירה בתחתונים, ומהו\"ע ברה\"ע, הנה אי' בתדב\"א שני דברים קדמו לעולם<sup data-n=\"3392\">22</sup> תורה וישראל ואיני יודע איזה מהם קדום אומר אני ישראל קדום, ורבינו ז\"ל הביא ראי' לזה<sup data-n=\"3393\">23</sup> דכל התורה הוא צו אל ישראל<sup data-n=\"3394\">24</sup> דבר אל בנ\"י<sup data-n=\"3395\">25</sup> וכ\"כ בתורה הקדומה ג\"כ א\"כ ישראל קדמו. ועיקר המכוון הוא העבודה והתומ\"צ הוא שבהם וע\"י ניכר העבודה וכמ\"ש אתה בחרתנו<sup data-n=\"3396\">26</sup> מכל העמים כו' וקדשתנו במצותיך וכתי' כי בך בחר ה' מכל העמים להיות לו לעם סגולה<sup data-n=\"3397\">27</sup>, ובמה יודע איפוא<sup data-n=\"3398\">28</sup> הלא ע\"י התומ\"צ, דעצם המצות אינם תופסים מקום כלל דמה איכפת לו להקב\"ה<sup data-n=\"3399\">29</sup>, וכל מצותיך צדק<sup data-n=\"3400\">30</sup>, רק עיקר המכוון הוא העבודה, ולא שהי' הרצון תחילה בתומ\"צ ואח\"כ נבראו ישראל לקיימם, אלא עיקר הרצון בעבודת ישראל ולכן נעשו המצות שע\"י יוכר העבודה, ומ\"ש אנכי עשיתי ארץ<sup data-n=\"3401\">31</sup> ואדם עלי' בראתי ונת\"ל (ה' ד\"ה ואהבת<sup data-n=\"3402\">32</sup> ע') דמה שנמשך מאנכי מי שאנכי<sup data-n=\"3403\">33</sup> שיהי' ארץ הוא בשביל האדם, ובראת\"י בגימ' תרי\"ג<sup data-n=\"3404\">34</sup> שעיקר המכוון בשביל תומ\"צ, צ\"ל ג\"כ שעי\"ז ניכר העבודה אבל המכוון בשביל עבודת ישראל, דאין מקרא יוצא מידי פשוטו<sup data-n=\"3405\">35</sup> ונושא הפשוט ממ\"ש ואדם עלי' בראתי הוא בשביל ישראל, ומ\"ש בראתי בגימ' תרי\"ג כדי שיהי' אדם אתם אתם קרוים אדם<sup data-n=\"3406\">36</sup> הוא ע\"י התורה אבל עיקר המכוון הוא עבודת ישראל (בפ\"א<sup data-n=\"3407\">37</sup> וזהו נתאווה הקב\"ה להיות לו דירה בתחתונים",[["3390","20","<b>שוקיו ועמודיו שש</b>: וכ\"ה בסה\"מ תרל\"ח ע' תנה. לקמן הנחה ד\"ה יפה שעה אחת הב' על יד הערה 46 (עמודיו) — שה\"ש ה, טו [ושם: עמודי]."],["3391","21","<b>שוקיו. . שנשתוקק הקב\"ה לבראותו</b>: ראה במד\"ר רפ\"י."],["3392","22","<b>בתדב\"א שני דברים קדמו לעולם</b>: רבא קרוב לספי\"ד בשינויים. ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 355."],["3393","23","<b>ורבינו ז\"ל הביא ראי' לזה</b>: ראה גם בההמשך כאן בשוה\"ג 5."],["3394","24","<b>צו אל ישראל</b>: אוצ\"ל: צו את בנ\"י — ויקרא כד, ב. ועוד. ראה גם לעיל הנחה ד\"ה אני לדודי הא' ובהערה 63."],["3395","25","<b>דבר אל בנ\"י</b>: בשלח יד, ב. טו. תרומה כה, ב. תשא לא, יג. ויקרא א, ב. ועוד."],["3396","26","<b>אתה בחרתנו</b>: בתפלת העמידה ליו\"ט."],["3397","27","<b>כי בך. . לעם סגולה</b>: ואתחנן ז, ו [ושם: כי. . בך בחר ה\"א להיות לו לעם סגולה מכל העמים]."],["3398","28","<b>ובמה יודע איפוא</b>: תשא לג, טז."],["3399","29","<b>דמה איכפת לו להקב\"ה</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. סה\"מ תרל\"ח ע' מח ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171426\" data-slug=\"likkutei-sichot\" data-id=\"1300171426\">לקו\"ש אבות כרך יז ע' 415</a> הערה 53. שופטים כרך יט ע' 182 הערה 42."],["3400","30","<b>וכל מצותיך צדק</b>: ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה נעשה אדם ובהערה 39."],["3401","31","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["3402","32","<b>ונת\"ל. . ד\"ה ואהבת</b>: כנראה הכוונה להנחה ד\"ה יפה שעה אחת פיסקא והענין הוא."],["3403","33","<b>מאנכי מי שאנכי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא מהדו\"ק ספמ\"ט</a>. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["3404","34","<b>ובראת\"י בגימ' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש רה, ב. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1688."],["3405","35","<b>דאין מקרא יוצא מידי פשוטו</b>: שבת סג, א."],["3406","36","<b>אתם קרוים אדם</b>: יבמות סא, א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550513\" data-slug=\"torat-chaim\" data-id=\"2300550513\">תו\"ח יתרו ח\"ב רסב, א</a> ואילך ובהערה 285. סה\"מ מלוקט ו' ע' פג. וש\"נ."],["3407","37","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."]]],[2000480355,"שע\"י העבודה ממשיכים כמו בעת הבריאה, ולמעלה מזה). וענין העבודה מהו, הנה אי' בע\"ח כשעלה ברצונו הפשוט<sup data-n=\"3408\">38</sup> לברוא את העולם צמצם א\"ע, ובמ\"א אי' כביכול סילק אורו הגדול על הצד<sup data-n=\"3409\">39</sup> ונשאר מקום פנוי, הגם שאינו שייך מקו\"פ דאין דבר שבקדושה נעקר ממקומו לגמרי<sup data-n=\"3410\">41</sup> ונשאר רשימה<sup data-n=\"3411\">40</sup>, ונת' במ\"א (ה' בד\"ה גן נעול, מצה זו<sup data-n=\"3412\">42</sup> ע') שהוא מהאור שלא נגע בו הצמצום. אך מ\"מ הוא בהעלם ואינו מאיר לידי גילוי, וראשית הגילוי הוא מה שנמשך המשכת הקו, והקו מסתיים באצי'<sup data-n=\"3413\">43</sup> (ובפ\"א והארת הקו בוקע הפרסא<sup data-n=\"3414\">44</sup> ומאיר בבי\"ע), והעבודה הוא להמשיך תוס' אורות באצי'<sup data-n=\"3415\">45</sup> ויבקע הפרסא המפסקת בין אצי' לבריאה ויאיר בבי\"ע ג\"כ.\n<b>והנה</b> לכאורה צ\"ל מה שייך תוס' אורות באצי' הלא אצי' הוא אלקות<sup data-n=\"3416\">46</sup> ובעה\"ק אי' על ע\"ס דאצי' הוא אינון ואינון הוא<sup data-n=\"3417\">47</sup>, ובחי' הו\"א, הוא א\"ס סתים ונעלם ומה שייך תוס' אורות בבחי' הוא. אך הענין הוא דמה שאו' שאצי' הוא אלקות, הוא בערך הנבראים אפי' בערך ע\"ס דבריאה שהם ראשית ההתהוות, בערכם נק' אצי' אלקות, אך קריאת שם אלקות הוא כמ\"ש בל\"א<sup data-n=\"3418\">49</sup> געטליך ולא אלוקה<sup data-n=\"3419\">48</sup> שהוא מה שקורין ג' א' ט'<sup data-n=\"3420\">50</sup> שזה מורה על יחודו ואחדותו שהוא בחי' יחיד, משא\"כ אלקות הוא רק געטליך, ולכן אי' באגה\"ק דאיהו מתייחד עם גרמוהי<sup data-n=\"3421\">51</sup> אשר בהן וע\"י מהווה",[["3408","38","<b>בע\"ח כשעלה ברצונו הפשוט</b>: ראה שם דרוש עגוי\"ש ש\"א, ענף ב."],["3409","39","<b>סילק אורו הגדול על הצד</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 216."],["3410","41","<b>דאין דבר שבקדושה. . לגמרי</b>: ראה אלשיך ר\"פ לך (הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490011\" data-slug=\"or-hatorah-hb\" data-id=\"8316490011\">אוה\"ת לך כרך ד ע' תרעה</a> <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600681\" data-slug=\"or-hatorah-hb\" data-id=\"8316600681\">וע' תרפא</a>. ושם מציין לפרדס שער המציאות פ\"א). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר ובהערה 45."],["3411","40","<b>ונשאר מקום פנוי. . רשימה</b>: ראה שם הערה 217."],["3412","42","<b>ונת' במ\"א. . בד\"ה גן נעול מצה זו</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן על יד הערה 370 שמציין: ”בד\"ה מצה זו בענין אז ישיר\" — ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אז ישיר<sup data-n=\"e269\">א</sup> פיסקא אך הנה נת\"ל."],["3413","43","<b>והקו מסתיים באצי'</b>: ראה ע\"ח שער סדר אצי' ש\"ג בתחלתו. תו\"ח ויצא קעו, ג הערה 45."],["3414","44","<b>והארת הקו בוקע הפרסא</b>: ראה אגה\"ק ס\"כ (תניא קלא, ב). (לעיל בחלק המאמרים) המשך יונתי כאן הערה 372."],["3415","45","<b>להמשיך תוס' אורות באצי'</b>: ראה פע\"ח בהקדמה. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540653\" data-slug=\"torat-chaim\" data-id=\"2300540653\">תו\"ח בשלח ח\"א קנו, ב</a> הערה 312."],["3416","46","<b>אצי' הוא אלקות</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1599."],["3417","47","<b>ובעה\"ק. . הוא אינון ואינון הוא</b>: ראה שם חלק היחוד פ\"ד. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ו הערה 102."],["3418","49","<b>בל\"א</b>: בלשון אידיש. ראה שיחת ליל הושע\"ר תשנ\"ב אות ג (שיחות קודש ע' 165 ואילך). ליל שמח\"ת קודם הקפות תשנ\"ב — סה\"ש תשנ\"ב ח\"א ע' 38 בשולי הגליון להערה 20. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211457\" data-slug=\"likkutei-sichot\" data-id=\"1300211457\">לקו\"ש משפטים כרך כא ע' 448</a> הערה 15."],["3419","48","<b>אצי'. . געטליך ולא אלוקה</b>: ראה גם סהמ\"צ להצ\"צ ע' נב וע' קלב ואילך. המשך וככה תרל\"ז פע\"ח. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית ע' תתרמו. סה\"מ תרל\"ח ע' תכה. וש\"נ."],["3420","50","<b>ג' א' ט'</b>: ראה גם בענין כתיבת תיבה זו (לעיל בחלק המאמרים) בההמשך כאן על יד הערה 378. (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 42. אוה\"ת ישעי' ע' רז (ד\"ה בטחו בסופו)."],["3421","51","<b>באגה\"ק דאיהו מתייחד עם גרמוהי</b>: ס\"כ (תניא קל, ב). ראה סה\"מ תרל\"ח ע' ד.\n\n<b>א</b>  וראה שם בהערה 1."]]],[2000480356,"מאין ליש, הרי אין בכח הגרמוהי לבד לברוא מאין ליש, איך שיפורש גרמוהי אם על כלים דע\"ס או על ז\"ת<sup data-n=\"3422\">52</sup> ונכלל בזה האור והכלי, רק בחי' איהו הוא המהווה, וצריך להיות ע\"י בחי' גרמוהי כדי שיהי' מציאות היש כמו שהוא עתה ושיהי' התחלקות (ה' מ\"ש שיהי' מציאות היש צ\"ע שהרי מה שיהי' מציאות היש הוא מצד אוא\"ס הסוכ\"ע<sup data-n=\"3423\">53</sup> וכמבו' במ\"א באריכות וכמשנת\"ל ד\"ה יפה שעה אחת בתשו'<sup data-n=\"3424\">54</sup>, יעו\"ש, ואפ\"ל שאין זה בדקדוק שהכוונה כאן לבאר מהיכן המציאות היש כו' וצ\"ע, ע') רק שעי\"ז נשלם תכלית המכוון שיהי' ביטול היש להאין, ומ\"מ לפ\"ז בחי' גרמוהי הוא הכח המגביל, ובחי' איהו הוא כח המהווה וההתהוות היא דבר מלא דבר<sup data-n=\"3425\">55</sup> והוא בחי' בבע\"ג (ע' משנת\"ל ד\"ה הנ\"ל ההפרש בין איהו דחיוהי ואיהו דגרמוהי<sup data-n=\"3426\">56</sup>, דאיהו שמתייחד עם גרמוהי הוא בחי' כח הגבול, וי\"ל שהוא כח הגבול שבא\"ס שלפני הצמצום ששם יש כח על ההגבלה וכמ\"ש בעה\"ק דא\"ס הוא שלימותא דכולא<sup data-n=\"3427\">57</sup> כו' והו\"ע ע\"ס הגנוזות במאצילן<sup data-n=\"3428\">58</sup> ר\"ל בא\"ס עצמיות המאציל טרם שנתצמצם עדיין, אך בערך הנבראים הוא בבע\"ג שה\"ה א\"ס עדיין שהם א\"ס אחדות פשוטה וכמבואר במ\"א באריכות בענין ע\"ס הגנוזות הנ\"ל, וגם בע\"ס דאצי' אמר בעה\"ק וכ\"ח הגבול הנמצא ממנו תחילה<sup data-n=\"3429\">59</sup> כו' הרי שהם רק כח הגבול ולא ח\"ו הגבלה ממש ועמ\"ש מזה במאמר ד\"ה הנה שיטת הר\"ם מראקנטי<sup data-n=\"3430\">60</sup> ע') א\"כ אינם בערך זל\"ז, והי'<sup data-n=\"3431\">61</sup> אפשר ר\"ל שהם כחות מחולקים וכח ההתהוות הוא מצד בחי' איהו כנ\"ל ע') הרי שגרמוהי אין",[["3422","52","<b>גרמוהי. . כלים. . ז\"ת</b>: ראה לעיל הנחה ד\"ה יפה שעה אחת ובהערה 70."],["3423","53","<b>מציאות היש. . הסוכ\"ע</b>: ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ר' אבהו פתח והמה כאדם ובהערה 48."],["3424","54","<b>ד\"ה יפה שעה אחת בתשו'</b>: ראה לעיל שם בתחלתו."],["3425","55","<b>דבר מלא דבר</b>: אולי צ\"ל: דבר לא מדבר — ראה גם (לעיל בחלק המאמרים) המשך יונתי ובהערה 479."],["3426","56","<b>ד\"ה הנ\"ל ההפרש. . דגרמוהי</b>: פיסקא והנה להבין זה, ואילך."],["3427","57","<b>בעה\"ק דא\"ס הוא שלימותא דכולא</b>: ראה עבודת הקודש ח\"א רפ\"ח. לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 224."],["3428","58","<b>ע\"ס הגנוזות במאצילן</b>: ראה גם פרדס שער סדר האצי' ש\"ה, פ\"ד. שער הצחצחות שי\"א. וראה שם פ\"ג. סידור דרושים לחתונה קלה, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סד ואילך ובהנסמן במ\"מ לשם. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו. סהמ\"צ להצ\"צ ע' נח. ע' קפב ואילך. המשך מים רבים תרל\"ו ע' ע ואילך. תרל\"ח ע' עו. המשך תער\"ב ח\"א פט\"ו ואילך. סה\"מ מלוקט א' ע' כב. ד' ע' לז. ה' ע' רפד וע' רפז ואילך."],["3429","59","<b>בעה\"ק וכ\"ח הגבול הנמצא ממנו תחילה</b>: ראה עבודת הקודש<sup data-n=\"e270\">ב</sup> ח\"א רפ\"ח. דרך אמונה להנ\"ל רפ\"ב (קה\"ת תשמ\"ח ע' יג)."],["3430","60","<b>הנה שיטת הר\"ם מראקנטי</b>: אוה\"ת ענינים ע' רנח ואילך."],["3431","61","<b>והי'</b>: אוצ\"ל: (ה' והי'.\n\n<b>ב</b>  מובא בשמו בכ\"מ ומהם: (לעיל בחלק המאמרים) מאמר ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 114. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380778\" data-slug=\"likkutei-torah\" data-id=\"4001380778\">לקו\"ת עקב טז, א</a> [ושם: והם הספירות. . והיינו הכלים דע\"ס]. אוה\"ת על ענינים ס\"ע רפב ואילך. ע' רפד. סה\"מ תרל\"ה ח\"א ע' קעג. תרל\"ח ס\"ע ג ואילך. תר\"ן ע' שעח. תרס\"ה ע' יד. (המשך) תרס\"ו ע' תק. ע' תקי. תרס\"ט ע' לב. אעת\"ר ע' ב. ע' נח. ע' קלה. (המשך) תער\"ב ח\"א ע' יט. ע' שכא. ח\"ג ע' א'שצב. ע' א'תלז. עזר\"ת ע' קנד. וראה גם חלק מהנסמן לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 224 בשולי היריעה. לקמן הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 124."]]],[2000480357,"בו כח להוות מאין ליש וכ\"ז מפני שהוא אלקות ולא אלקה, וכדי שיהי' בחי' אצי' הוא מחמת הצמצום הראשון שפעל כ\"כ שיהי' עולם כזה שלא יהי' אלקה כ\"א אלקות.\n<b>וענין</b> תוס' באצי' היינו שיומשך מלמעלה דאצי' באצי', ובד\"כ הוא ההמשכה מלפני הצמצום, ואז בוקע הפרסא ומאיר בבי\"ע ג\"כ, הגם שלמעלה מאצי' הוא ג\"כ רצון ורצון אותיות צנור<sup data-n=\"3432\">62</sup> מ\"מ הוא למעלה מאצי' שהוא אלקות, ושרש הענין דהנה המצות לבד שהם רצה\"ע שרצון אותיות שנמשך<sup data-n=\"3433\">63</sup> הרצה\"ע למטה, ואמרז\"ל נח\"ר לפני שאמרתי ונעשה ופי' אמרתי ונעשה רצוני<sup data-n=\"3434\">64</sup> הוא בחי' א\"ס בעל הרצון ויש מה שנושא וסובל בחי' הרצון הכללי, לבד זאת הם פועלים הזדככות בהעולם וכמ\"ש גם את העולם נתן בלבו<sup data-n=\"3435\">65</sup> שלפ\"ע המעשה המצות הוא מברר בהעולם ג\"כ, דהנה המצות נתלבשו בדברים גשמים ציצית בצמר גשמי תפילין בקלף גשמי שופר קרן של איל<sup data-n=\"3436\">66</sup> גשמי ד\"מ שבלולב צמחים גשמים והנה צומח זה כשאוכלו מי שאינו מצווה לברך עליו ה\"ה נשאר בנוגה כמו שהי' מקודם רק שנתעלה מצומח למדבר<sup data-n=\"3437\">67</sup> וה\"ז עלי' קטנה, אבל כשמברך עליו ה\"ה מעלה אותו ומכ\"ש כשעושה אותה מצוה הרי נעשה כלי להרצון פרטי ולהרצון כללי שכולל כל הרצונות ומה שנושא הרצון הכללי דתי' בע\"ל הרצון הוא ל' מרא ורבון וכמו באדם למטה יש לו רצון פרטי ורצון פשוט כללי שכוללם יחד והאדם שיש לו הרצון הכללי, וכמו\"כ יובן למעלה ג\"כ שיש כל הבחי' הנ\"ל, וכ\"ז יש בהמצוה הגשמיות ואלמלא ניתנה רשות לעין לראות<sup data-n=\"3438\">68</sup> היו רואין כח הבעל הרצון שיש בהמצות וכמ\"ש בסש\"ב אלמלא ניתנה רשות<sup data-n=\"3439\">69</sup> לעין לראות בריאה יש מאין היו רואין איך שכל מציאות היש הוא אין ואפס וכמו\"כ בהמצוה הי' רואין הכח בעל הרצון שמלובש בהמצוה, רק שעכשיו מעלים ומסתיר אבל לע\"ל יאיר ויתגלה בחי' זו וזהו ונגלה כבוד ה' וראו<sup data-n=\"3440\">70</sup> כו' כי עין בעין יראו<sup data-n=\"3441\">71</sup> כו' חשף ה' את זרוע קדשו<sup data-n=\"3442\">72</sup>, חשף הוא גילוי שיתגלה בחי' א\"ס בעהר\"צ ולא יהי' עוד העלם והסתר, ומ\"ש זרוע קדשו דכלליות המצות נק' בשם צדקה<sup data-n=\"3443\">73</sup> והיד שנותנת הצדקה והמעות גשמים או ד\"א שמחי' בו",[["3432","62","<b>ורצון אותיות צנור</b>: ראה זהר הרקיע לזהר בראשית נא, א (כה, ב בדפי הספר). מאמרי אדה\"א בראשית ע' לו. וש\"נ."],["3433","63","<b>אותיות שנמשך</b>: אוצ\"ל: אותיות צנור שנמשך."],["3434","64","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490060\" data-slug=\"likkutei-sichot\" data-id=\"1301490060\">נח\"ר</a>. . ונעשה. . רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["3435","65","<b>גם את העולם נתן בלבו</b>: קהלת ג, יא [ושם: בלבם]. ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה ובהערה 142."],["3436","66","<b>שופר קרן של איל</b>: ראה ר\"ה טז, א. מאמרי אדה\"א דברים ח\"ג ע' תתצז. וש\"נ."],["3437","67","<b>צומח. . שאינו מצווה לברך. . שנתעלה מצומח למדבר</b>: ראה גם לעיל הנחה ד\"ה יונתי ובהערה 178."],["3438","68","<b>ואלמלא ניתנה רשות לעין לראות</b>: ברכות ו, א."],["3439","69","<b>בסש\"ב אלמלא ניתנה רשות</b>: ראה שער היחוד והאמונה פ\"ג."],["3440","70","<b>ונגלה כבוד ה' וראו</b>: ישעי' מ, ה. ראה בסמוך בפנים."],["3441","71","<b>כי עין בעין יראו</b>: שם נב, ח."],["3442","72","<b>חשף ה' את זרוע קדשו</b>: ישעי' שם, י."],["3443","73","<b>דכלליות המצות נק' בשם צדקה</b>: ראה גם לעיל (בחלק המאמרים) המשך יונתי ובהערה 27."]]],[2000480358,"העני ה\"ז כלי לא\"ס בעהר\"צ, וכמ\"ש הרמב\"ם בפרקי הצלחה<sup data-n=\"3444\">74</sup> בענין תקיעות שופר (ה' בשו\"ת פאר הדור סי' קנ\"ז פ\"ב<sup data-n=\"3445\">75</sup> ע') ואתה בהתקע שופר בר\"ה תקונו והכשירו הנה תהי' תנועתו כלה באבריך ידיך פשוטות ללקיחת השופר אצבעותיך מקמצות להחזיק בו גרונך ולשונך וכלי הקול בהנעים<sup data-n=\"3446\">76</sup> תקיעתו תהיינה אזניך קשובות ורגליך עומדות ועיניך עצומות ויתר חלקך נרעדים וחרדים (ה' עכ\"ל) והלב ישמע הקול שופר והמוח ירגיש בזה וכן כל הרמ\"ח אברים<sup data-n=\"3447\">77</sup> (ה' וכן קחשיב שם בשארי מצות ותפלה ע\"ש ע') הרי כל האברים הם כלים לא\"ס בעהר\"צ, ולע\"ל יתגלה בחי' זו, שזהו ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דיבר דכשילמוד תורה יראה את פה המדבר כנגדו<sup data-n=\"3448\">78</sup> וכן יראה פה המדבר את התורה וכמו בהר סיני שאנכי ולא יהי' לך מפי הגבורה שמענו<sup data-n=\"3449\">79</sup> וכמו\"כ יהי' לע\"ל, ואמר ורא\"ו כל בשר שיהי' בחי' ראי' ולא ראי' גשמיות כ\"א שישיג בשכלו, אך לא השגה לבד אלא ראי' (ה' אפ\"ל ראיות המהות בעין השכל וע' מזה בד\"ה וככה ל\"ז<sup data-n=\"3450\">80</sup> ע'), ובחי' זו יש עתה ג\"כ במצות אלא שהם בהעלם ולע\"ל יתגלה בחי' זו, וכמו מ\"ש בע\"ח שנשאר פנוי והלא נשאר רשימה וגם עכשיו הלא את השמים ואת הארץ אני מלא<sup data-n=\"3451\">81</sup>, אלא שהם בהעלם ולע\"ל יתגלה בחי' זו. וכמו\"כ במצות ג\"כ, ואיך המצות הם כלים לא\"ס בעהר\"צ, הענין הוא כמו שמבואר במ\"א (ה' ד\"ה אלה תולדות נח ל\"ז<sup data-n=\"3452\">82</sup> ע') על מארז\"ל עוה\"ב אין בו לא אכילה ולא שתי' אלא צדיקים יושבים ועטרותיהם בראשיהם<sup data-n=\"3453\">83</sup>, דהנה חיות האדם הוא מחו\"צ<sup data-n=\"3454\">84</sup> לאחר שנפרד החיות מהם דבע\"ח טעון שחיטה<sup data-n=\"3455\">85</sup> ובלא שחיטה אסור באכילה, וצומח תולשין אותו תחילה שנפרד ממנו החיות, והוא מפני שבכל דבר יש גוף ונפש ושרש הגוף מבחי' א\"ס הסוכ\"ע והנפש מבחי' ממכ\"ע, וקבלת החיות הוא מגוף גשם הדבר אשר שרשו מסוכ\"ע, הגם שגוף האדם ג\"כ מסוכ\"ע צ\"ל דמוצא פי ה' שבמאכל<sup data-n=\"3456\">86</sup> הוא גבוה יותר ממוצא פי ה' שבאדם, וכ\"ז עתה שגוף האדם",[["3444","74","<b>וכמ\"ש הרמב\"ם בפרקי הצלחה</b>: ראה גם סה\"מ תרל\"ו ח\"ב ע' שכה. ס\"ע שמז ואילך. תרל\"ח ע' תפא. שו\"ת פאר הדור סקנ\"ו (ירושלים תשד\"מ ס\"ע שז)."],["3445","75","<b>בשו\"ת פאר הדור סי' קנ\"ז פ\"ב</b>: במהדורת ירושלים הנ\"ל: סקנ\"ו, פ\"א."],["3446","76","<b>הקול בהנעים</b>: שם: הקול משמשות בהנעים."],["3447","77","<b>הרמ\"ח אברים</b>: אהלות פ\"א, מ\"ח."],["3448","78","<b>דכשילמוד תורה. . כנגדו</b>: לקמן (בחלק ההנחות) הנחה ד\"ה כנשר יעיר קנו על יד הערה 79: אי' בגמ' — ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540132\" data-slug=\"torat-chaim\" data-id=\"2300540132\">תו\"ח וארא ח\"א נח, ג</a>. וש\"נ."],["3449","79","<b>שאנכי. . מפי הגבורה שמענו</b>: מכות כד, א. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה עשה צדקה ומשפט הערה 138."],["3450","80","<b>ורא\"ו כל בשר. . ולא ראי' גשמיות. . בד\"ה וככה ל\"ז</b>: ראה המשך וככה תרל\"ז פצ\"א. פצ\"ב. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשעד. שע\"ת נו, א."],["3451","81","<b>הלא את השמים. . מלא</b>: ירמי' כג, כד."],["3452","82","<b>ד\"ה אלה תולדות נח ל\"ז</b>: פי\"ח — לא נדפס לע\"ע."],["3453","83","<b>עוה\"ב אין בו. . בראשיהם</b>: ברכות יז, א. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קלה ואילך. המשך וככה תרל\"ז שם."],["3454","84","<b>מחו\"צ</b>: מחי וצומח."],["3455","85","<b>דבע\"ח טעון שחיטה</b>: פ' ראה יב, כא. סהמ\"צ להרמב\"ם מ\"ע קמו. רמב\"ם הל' שחיטה רפ\"א."],["3456","86","<b>דמוצא פי ה' שבמאכל</b>: ראה עקב ח, ג. מאמרי אדה\"א דברים ח\"ב ע' תקעה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540054\" data-slug=\"torat-chaim\" data-id=\"2300540054\">תו\"ח וארא ח\"א נה, ב</a> ואילך. וש\"נ. סה\"מ מלוקט א' ע' קצא."]]],[2000480359,"הוא מגושם לכן הוא מקבל חיות ג\"כ מגשם הצומח ובע\"ח, אבל לע\"ל שיזדכך האדם וכמו באדה\"ר דעקב הי' מכהה אור גלגל חמה<sup data-n=\"3457\">87</sup> מצד ריבוי האור ולא זו לבד אלא שהבהירות הוא באו\"א לגמרי והוא מפני שהי' יציר כפיו של הקב\"ה וכמו\"כ לע\"ל שלא יהי' אב ואם<sup data-n=\"3458\">88</sup> ה\"ז ע\"ד יציר כפיו של הקב\"ה לכן יקבל החיות שלו מבחי' א\"ס הסוכ\"ע מקור הדבר גשמי, וכמו\"כ לע\"ל שיזדככו הגשמים ויהי' בערך מקורם א\"ס הסוכ\"ע לכן יהיו כלים לא\"ס בעהר\"צ, וזהו נתאווה הקב\"ה להיות לו דירה בתחתונים שבחי' א\"ס עצומ\"ה יאיר למטה דוקא, וע\"י המצות ממשיכים בחי' זו, וזהו דודי לי ואני לו הרועה בשושנים דכדי שיהי' אני לו צ\"ל תחילה דודי לי וזהו קאי על יצ\"מ ומ\"ת שהי' גילוי אלקות וכמ\"ש עד שנגלה עליהם<sup data-n=\"3459\">89</sup> מלך מלכי המלכים הקב\"ה, מלכים כמ\"ש הנה המלכים נועדו<sup data-n=\"3460\">90</sup>, מלכי המלכים חו\"ב, מלך מלכי המלכים כתר<sup data-n=\"3461\">91</sup>, והוא למעלה מאצי' והעטרה שע\"ג הראש שבכל עולם הוא כתר, ובמ\"ת כתי' וירד ה' על הר סיני<sup data-n=\"3462\">92</sup> ועי\"ז ואני לו, דנפשו יצא בדברו<sup data-n=\"3463\">93</sup> על כל דו\"ד פרחה נשמתם<sup data-n=\"3464\">94</sup>, ובד\"כ הוא שיהי' קיום המצות כדבעי דכשמניח תפילין יכוון<sup data-n=\"3465\">95</sup> לשעבד הלב והמוח וכן שארי המצות, וזהו עבודה מל' עורות עבודים<sup data-n=\"3466\">96</sup> דכשמעבדין עורות הם אינם בערך מכמו שהיו קודם, וצ\"ל דגם קודם שעבדן הי' בהם הטוב הזה אלא שהי' בהעלם והעבוד פועל יציאה מהעלם אל הגילוי, וכמו\"כ כאן גם במצות דעכשיו יש בהם בחי' א\"ס בעהר\"צ אלא שהם בהעלם ולע\"ל יאיר ויתגלה בחי' זו.\n<b>והנה</b> כ\"ז כשמקיימים תומ\"צ וכמ\"ש ועבדתם את ה' אלקיכם ולעבדו בכל לבבכם איזה עבודה שבלב זו תפילה<sup data-n=\"3467\">97</sup> שהוא החיות של כל המצות (ה' לכן אין התפלה במנין תרי\"ג מצות<sup data-n=\"3468\">98</sup> וכמו החוט השדרה שאינו נמנה ברמ\"ח אברים<sup data-n=\"3469\">99</sup>, ח\"י ברכאן דצלותא ח\"י חוליות שבשדרה<sup data-n=\"3470\">100</sup> וכמבואר כ\"ז במ\"א ע'), אך כשפגם הן",[["3457","87","<b>באדה\"ר דעקב. . חמה</b>: ראה ויק\"ר פ\"כ, ב. זהר רע\"מ קדושים פג, ריש ע\"ב. מאמרי אדה\"א ויקרא ח\"ב ע' תרפו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670154\" data-slug=\"torat-chaim\" data-id=\"2300670154\">תו\"ח בראשית לב, א</a> הערה 15. סה\"מ מלוקט א' ע' קעח. וש\"נ."],["3458","88","<b>לע\"ל שלא יהי' אב ואם</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קלה. וש\"נ. ח\"ב שם. מאמר ד\"ה דור לדור מכ\"ק אדה\"א (קה\"ת תשנ\"ב) ע' 16."],["3459","89","<b>עד שנגלה עליהם</b>: נוסח ההגדה."],["3460","90","<b>הנה המלכים נועדו</b>: תהלים מח, ה. זהר ויגש רו, א."],["3461","91","<b>מלכי. . המלכים כתר</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 106."],["3462","92","<b>וירד הוי' על הר סיני</b>: יתרו יט, כ."],["3463","93","<b>דנפשו יצאה בדברו</b>: שה\"ש ה, ו [ושם: נפשי]."],["3464","94","<b>על כל דו\"ד פרחה נשמתם</b>: ראה שבת פח, ב. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 35."],["3465","95","<b>דכשמניח תפילין יכוון</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, סי\"א. סידור שם [נדפס גם בהוספות לשו\"ע שם ע' קנו]."],["3466","96","<b>עבודה מל' עורות עבודים</b>: ראה שבת מט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550470\" data-slug=\"torat-chaim\" data-id=\"2300550470\">תו\"ח יתרו ח\"ב רסח, ב</a>. וש\"נ. סה\"מ תרל\"ח ע' שפ. וש\"נ."],["3467","97","<b>איזה עבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450608\" data-slug=\"or-hatorah-hb\" data-id=\"8316450608\">אוה\"ת עקב ע' תרח</a>."],["3468","98","<b>אין התפלה במנין תרי\"ג מצות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו\"ת בלק ע, סע\"ג</a> ואילך. מאמרי אדה\"א קונטרסים ע' תקעט ואילך. וש\"נ."],["3469","99","<b>החוט השדרה שאינו נמנה ברמ\"ח אברים</b>: ראה אהלות פ\"א, מ\"ח."],["3470","100","<b>ח\"י ברכאן. . ח\"י חוליות שבשדרה</b>: ראה זהר רע\"מ פינחס רנה, סע\"ב. ברכות כח, ב."]]],[2000480360,"במ\"ע או במל\"ת, ואפי' בהרהורי עבירה שבאמת קשה מעבירה<sup data-n=\"3471\">101</sup> וצ\"ל איך שייך לומר קשה כו'. והענין דאין ר\"ל שהמעשה קל יותר מההרהור, אלא מפני שכח המח' הוא כח דק יותר לכן ע\"י הפגם הוא נפסד יותר וכמו בגד משי הרבב מפסיד אותו יותר מבגד פשתן דכשמכבסין אותו ה\"ה כמקדם משא\"כ בגד משי שאינו דומה כמו שהי' קודם מפני שהוא דק יותר וכמו\"כ יובן כאן שכח המח' הוא כח דק ורוחני יותר לכן פועל בו הפגם יותר, ועוי\"ל (בפ\"א הגם שהמח' הוא רק לבו\"ש להרצון הרי מ\"מ הוא לבוש לכח הרצו\"ן) דהנה המח' הוא לבוש לרצון, וא\"כ כשפוגם במ\"ע או במל\"ת ה\"ז כמו מחוסר אבר או קלקול בגידי הדם, אבל הרצון הוא כלל הכוללם יחד וכשפוגם במח' ה\"ה פוגם בהכלל לכן הוא קשה יותר כו'. ועוי\"ל דמעשה כשעושה אותה נפסק התאווה אבל המח' יומם ולילה לא ינוח ולא ישקוט ומצד התמדת הפעולה קשה יותר כו'. ומי שפגם בהנ\"ל ה\"ה חולה וכמו החולה אינו מועיל לו אכילה ושתי' וצריך רפואות תרופות מיוחדות לרפאות אותו, וכמו\"כ מי שפגם באחת מאלה ה\"ה חולה ואינו מועיל לו אכילה ושתי' היינו תורה וכמ\"ש הוי כל צמא לכו למים<sup data-n=\"3472\">102</sup>, לכו לחמי בלחמי<sup data-n=\"3473\">103</sup>, אלא צריך רפואה וארז\"ל גדולה תשובה שמביאה רפואה לעולם<sup data-n=\"3474\">104</sup>, וכמו כשנותנין רפואה על מקום פצע או חבורה ה\"ה שורף ומכלה מקום החבורה ופועל שיעלה בשר אחר חי, כמו\"כ ענין התשובה הוא חרטה על עבר ועקירת הרצון לגמרי כמו הרפואה שעוקר בשר החי (ה' ועי\"ז ה\"ה דוחה את החיצונים וקליפות וסט\"א שינקו עד עתה מן הקדושה ע\"י מעשיו הרעים, וע\"י תשובה ה\"ה מכלה אותם, ובכח התשובה להוציא שפע הקדושה אפי' מה שנמשך בעמקי הקליפות ר\"ל וכידוע המעשה מהבע\"ת (ושמו ר\"פ<sup data-n=\"3475\">105</sup> ) שע\"י התשובה הוציא ניצוצות הקדושות שנמשכו ביסוד דנוקבא דקליפה ר\"ל, אך זהו ע\"י תשובה עילאה, אך מ\"ש כאן חרטה על עבר ועקירת הרצון לגמרי, ענין החרטה מבואר במ\"א כמו מי שבא במצולות ים<sup data-n=\"3476\">106</sup> במים עמוקים מאד ובאו לו מים עד נפש ממש ה\"ה צועק במר נפשו ומתחרט מאד למה עשה כזאת לילך במים עמוקים, וכמו\"כ צ\"ל החרטה דתשובה, א\"כ ה\"ז תשובה עילאה, וענין עקירת הרצון הוא ג\"כ כנ\"ל, ואפשר שהכוונה כאן ג\"כ על בחי' תש\"ע. ומ\"ש במשל שפועל שיעלה בשר חי, אפשר בהנמשל הוא שע\"י שפגם במ\"ע הרי חסר יומא חסר לבושא חדא<sup data-n=\"3477\">107</sup> וע\"י התשובה",[["3471","101","<b>בהרהורי עבירה. . קשה מעבירה</b>: ראה יומא כט, א. לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 381."],["3472","102","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["3473","103","<b>לכו לחמי בלחמי</b>: משלי ט, ה [ושם: לחמו]."],["3474","104","<b>גדולה תשובה. . לעולם</b>: יומא פו, סע\"א."],["3475","105","<b>המעשה מהבע\"ת (ושמו ר\"פ)</b>: ראה מאמרי אדה\"א קונטרסים (ע' תעא<sup data-n=\"e271\">ג</sup> ואילך ושם: שלמה ליב. סה\"מ תרנ\"ב ע' עב ושם: ר' אפרים, הובאו שם) ע' תקכה<sup data-n=\"e272\">ד</sup> ובהערה 7."],["3476","106","<b>ענין החרטה. . במצולות ים</b>: ראה בשם אדה\"ז לקמן (בחלק ההנחות) בהנחה ד\"ה כנשר יעיר קנו ובהערה 119."],["3477","107","<b>חסר יומא חסר לבושא חדא</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תשמט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540878\" data-slug=\"torat-chaim\" data-id=\"2300540878\">תו\"ח בשלח ח\"א קעו, א</a>. וש\"נ.\n\n<b>ג</b>  נדפס גם בפוקח עורים מהדורת* נ.י. ת\"ש (ואילך) ברשימה מהיומן פ\"מ ואילך. ובמהדורת קה\"ת תשס\"ג ע' 27 ואילך.\n\n<b>ד</b>  בפוקח עורים מהדורת תשס\"ג ע' 81.\nראה גם אודות המהדורות בס' מפתח ספרי מאמרי ודרושי כ\"ק אדה\"א בערכו (נמצא בדפוס)."]]],[2000480361,"ממשיך אותם, ועי' בלקו\"ת (כמדומה) ד\"ה תקעו הב'<sup data-n=\"3478\">108</sup> מענין זה, וע\"י המל\"ת הרי פגם ועשה נקב והו\"ע ונוקב שם ה'<sup data-n=\"3479\">109</sup> כו' וכמבואר במ\"א באריכות בענין ויתר הקב\"ה על ע\"ז<sup data-n=\"3480\">110</sup> כו' וע\"י התשובה תעלה ארוכה ורפואה שיתרפא הנקב הנ\"ל ע'). ואמרם מביאה רפואה לעולם דעי\"ז פועל הזדככות בעולם ג\"כ דגם את העולם נתן בלבו, וע\"י סור מרע הן אם לא פגם כלל או אפי' אם פגם ח\"ו ושב ורפא לו<sup data-n=\"3481\">111</sup> ונק' סור מרע אז ועשה טוב הוא ביסוד מוסד, דכשבונין בנין בלא יסוד קרוב הדבר שיפול אבל ע\"י שפועל תחילה הסור מרע אז ועשה הוא על יסוד מוסד וכמו החולה לאחר שנתרפאה<sup data-n=\"3482\">112</sup> ה\"ה מתחזק ע\"י אכו\"ש כמו\"כ ע\"י תשובה שקדם אח\"כ ע\"י קיום התומ\"צ הוא מתחזק יותר מכמו שהי' מקדם.\n<b>ושרש</b> הענין דהנה כתי' כי חלק ה' עמו יעקב חבל נחלתו<sup data-n=\"3483\">113</sup> כמו החבל שראשו א' קשור למעלה וא' למטה, כמו\"כ הנשמה לא כולה מתלבשת בגוף כ\"א הארה ומקצת מהנשמה ועיקר הנשמה נשאר למעלה, והתקשרות הנשמה המלובשת בגוף עם אלקות הוא ע\"י החבל, וכמו שהחבל ארוגה מכמה חבלים דקים ונעשה חבל עב, כמו\"כ החבל הנ\"ל ארוגה מתרי\"ג חבלים (בפ\"א מתרי\"ג נימין) דקים והם תרי\"ג מצות, וכשפוגם באיזה מצוה הרי עי\"ז נפסק חבל א' (ה' ר\"ל מהתרי\"ג חבלים דקים ע') עד שיוכל להיות שיופסק החבל לגמרי וזהו ונכרתה הנפש<sup data-n=\"3484\">114</sup> כו' מ\"מ אין לך דבר שעומד בפני התשובה<sup data-n=\"3485\">115</sup>, ומשארז\"ל ששמע מאחורי הפרגד שובו בנים שובבים<sup data-n=\"3486\">117</sup> חוץ מאחר<sup data-n=\"3487\">116</sup> היינו שלא הועיל לו תשובה תתאה אבל תשו\"ע הי' מועיל לו ג\"כ, ועוי\"ל שאין מספיקין בידו לעשות תשו'<sup data-n=\"3488\">118</sup> ואפשר שהי' מועיל לו תשו\"ת ג\"כ אלא שלא עזרו לו מלמעלה, ויש בכח התשו' לקשר החבל וכמו עד\"מ כשקושרין חבל הרי במקום הקשר חזק יותר מפני ששם הוא כפול ארבעה<sup data-n=\"3489\">119</sup> ואם יופסק יופסק במ\"א אבל לא על מקום הקשר, כמו\"כ ע\"י תשו' שקושרים החבל, במקום הקשר הוא אמיץ וחזק ולא יופסק עוד (ה' אפ\"ל ע\"ד שארז\"ל מי שבא לידי עבירה<sup data-n=\"3490\">120</sup> ולא עבר מובטח לו שלא יחטא עוד ע'). ואי לזאת כל איש ישראל שמרגיש בנפשו איזה חטא",[["3478","108","<b>ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380935\" data-slug=\"likkutei-torah\" data-id=\"4001380935\">לקו\"ת</a> (כמדומה) תקעו הב'</b>: ראה לקו\"ת ר\"ה נד, א ואילך."],["3479","109","<b>ונוקב שם הוי'</b>: אמור כד, טז. ראה גם לעיל הנחה ד\"ה יונתי על יד הערה 55 ואילך."],["3480","110","<b>ויתר הקב\"ה על ע\"ז</b>: ראה ירושלמי חגיגה פ\"א, ה\"ז. פתיחתא דאיכ\"ר ב. הל' ת\"ת לאדה\"ז פ\"ד, ה\"ז. סה\"מ תרכ\"ט ס\"ע רצ ואילך. וש\"נ."],["3481","111","<b>ושב ורפא לו</b>: ישעי' ו, י."],["3482","112","<b>שנתרפאה</b>: כ\"ה בגוכתי\"ק."],["3483","113","<b>כי חלק. . יעקב חבל נחלתו</b>: האזינו לב, ט. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310050\" data-slug=\"tanya\" data-id=\"3401310050\">תניא פמ\"ה</a>. אגה\"ת פ\"ו. מאמרי אדה\"א שמות ח\"ב ע' תרז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380858\" data-slug=\"likkutei-torah\" data-id=\"4001380858\">לקו\"ת תצא לה, ב</a>. ולהעיר מר\"ח שער היראה פי\"ד."],["3484","114","<b>ונכרתה הנפש</b>: לך יז, יד. ועוד."],["3485","115","<b>אין לך דבר שעומד בפני התשובה</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061066\" data-slug=\"likkutei-sichot\" data-id=\"1300061066\">לקו\"ש בא כרך ו ע' 66</a> הערה 54."],["3486","117","<b>שובו בנים שובבים</b>: ירמי' ג, יד. כב."],["3487","116","<b>ששמע. . חוץ מאחר</b>: חגיגה טו, א."],["3488","118","<b>שאין מספיקין בידו לעשות תשו'</b>: יומא פה, ב (במשנה)."],["3489","119","<b>הקשר. . כפול ארבעה</b>: ראה (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 410."],["3490","120","<b>מי שבא לידי עבירה</b>: ראה יומא לח, סע\"ב."]]],[2000480362,"ועון הן בהעדר מ\"ע או במל\"ת ואפי' בהרהורי עבירה שקשים מעבירה ישוב אל וירחמהו<sup data-n=\"3491\">121</sup> ויצעק במר נפשו אל ה', ועי\"ז יבא לדבקה בא\"ס עצומ\"ה.\n<b>אך</b> איך יבוא לתשו' הוא ע\"י התבוננות לעורר ר\"ר על נפשו דהנשמה היא חלק אלוקה ממעל<sup data-n=\"3492\">122</sup> וקודם התלבשותה בגוף כתי' חי ה' אשר עמדתי לפניו<sup data-n=\"3493\">123</sup>, וענין העמידה הוא כמ\"ש גבי שרפים, שרפים עומדים<sup data-n=\"3494\">124</sup>, ויעמידם לעד לעולם<sup data-n=\"3495\">125</sup> דר\"ל שעמדה בביטל, והנה מלאכים הם מחיצוניות הכלים ונשמות מפנימיות הכלי<sup data-n=\"3496\">126</sup> א\"כ כ\"ש שעמדה באהוי\"ר, דהנשמה היא רוחני ואינו שייך עמידה בדבר רוחני אלא ר\"ל שעמדה בביטל וירדה למטה בגוף ונה\"ב המעלים ומסתיר ונת\"ל (ה' ד\"ה הנ\"ל<sup data-n=\"3497\">127</sup> ע') שהירידה צורך עלי', ולסוף צלל במים אדירים והעלה בידו חרס<sup data-n=\"3498\">128</sup>, שע\"י עוונות ה\"ה ממשיך שפע הקדושה במקום הטינופת אשת הזימה, וגם ע\"י הרהורים רעים נעשה פצעים וחבורות בהנשמה מכף רגלו ועד ראשו אין בו מתום פצע וחבורה ומכה טרי'<sup data-n=\"3499\">129</sup> עד שח\"ו נדחה ממחיצתו של הקב\"ה לגמרי, וכמ\"ש עוונותיכם מבדילים<sup data-n=\"3500\">*130</sup> ביניכם לבין אלקיכם שהחטא ועון נעשה מחיצה המבדלת לגמרי (ה' והוא מחיצה של ברזל<sup data-n=\"3501\">130</sup> המפסקת כי ברז\"ל ע\"ה בגימ' עמלק<sup data-n=\"3502\">131</sup> שהו\"ע אשר קרך<sup data-n=\"3503\">132</sup>, ע') א\"כ גדלה הרחמנות על הנפש עד מאד תמורת שהיתה בטל<sup data-n=\"3504\">133</sup> לאלקות, ירדה למטה ויוכל להיות שיודחה לגמרי ממחיצתו של הקב\"ה לגמרי ח\"ו, וכשיתבונן בזה יצעק במר נפשו וכמ\"ש ויצעקו אל ה'<sup data-n=\"3505\">134</sup> בצר להם צעק לבם אל ה'<sup data-n=\"3506\">135</sup> צעקה פנימיות מעומקא דליבא.\n<b>וזהו\"ע</b> תקיעת שופר גנוחי גניח ילולי יליל<sup data-n=\"3507\">136</sup> כמו חולה שהוא נאנח על כאביו כשמרגישם, כמו\"כ כשמרגיש הפגמים הוא גונח ויליל עליהם, ותחילה צ\"ל תקיעה צעקה פנימיות מעומקא דליבא ואח\"כ שברים תרועה גנוחי גניח כו'",[["3491","121","<b>ישוב אל וירחמהו</b>: ע\"פ ישעי' נה, ז."],["3492","122","<b>דהנשמה היא חלק אלוקה ממעל</b>: ראה איוב לא, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. לעיל הנחה ד\"ה ואתה תצוה ובהערה 54."],["3493","123","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["3494","124","<b>שרפים עומדים</b>: ישעי' ו, ב. ראה סוטה לט, א (צויין אליו ב) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380390\" data-slug=\"likkutei-torah\" data-id=\"4001380390\">לקו\"ת נשא כ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380398\" data-slug=\"likkutei-torah\" data-id=\"4001380398\">כב, ג</a>."],["3495","125","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"א. וש\"נ."],["3496","126","<b>מלאכים הם מחיצוניות. . מפנימיות הכלי</b>: נסמן לעיל הנחה ד\"ה אני לדודי הערה 42."],["3497","127","<b>ד\"ה הנ\"ל</b>: יפה שעה אחת הא' על יד הערה 112."],["3498","128","<b>צלל במים אדירים והעלה בידו חרס</b>: ראה בב\"ק צא, סע\"א. רמב\"ם הל' קדוש החדש פי\"א, ה\"ב."],["3499","129","<b>מכף רגלו. . ומכה טרי'</b>: ע\"פ ישעי' א, ו."],["3500","*130","<b>עוונותיכם מבדילים</b>: ישעי' נט, ב (בדילוג]. ראה אגה\"ת פ\"ה."],["3501","130","<b>עוונותיכם. . מחיצה של ברזל. . עמלק</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370370\" data-slug=\"torah-or\" data-id=\"3901370370\">תו\"א תצוה פג, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550091\" data-slug=\"torat-chaim\" data-id=\"2300550091\">תו\"ח תצוה ח\"ב שנו, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550284\" data-slug=\"torat-chaim\" data-id=\"2300550284\">שסה, א</a> ואילך."],["3502","131","<b>ברז\"ל ע\"ה בגימ' עמלק</b>: ראה גם אוה\"ת תצוה ע' א'תרעא. ע' א'תשלט. שה\"ש ח\"ב ע' תטז. מג\"א ע' רטז. סה\"מ תרכ\"ז ס\"ע קנו. ע' קפג. תרע\"ח ע' רנג. קונטרסים ח\"א ע' רסא."],["3503","132","<b>אשר קרך</b>: תצא כה, יח. ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 560."],["3504","133","<b>בטל</b>: כ\"ה בגוכתי\"ק."],["3505","134","<b>ויצעקו אל ה'</b>: תהלים קז, ו. כח."],["3506","135","<b>צעק לבם אל ה'</b>: איכה ב, יח."],["3507","136","<b>גנוחי גניח ילולי יליל</b>: ר\"ה לג, ב. לד, א."]]],[2000480363,"וכשמתבונן על מה הוא גניח צועק במר נפשו בקול פשוט וזהו התקיעה השנית דצ\"ל פשוטה לפני' ופשוטה לאחרי'<sup data-n=\"3508\">137</sup>, ועוד יש טעמים אחרים על הקול פשוט. והנה התשובה פועל שיהי' החזרת פב\"פ כמו עד\"מ ב' אנשים שעומדים קרובים זל\"ז אך אב\"א ה\"ז נק' מרוחק, כמו\"כ כתי' כי פנה אלי עורף<sup data-n=\"3509\">138</sup> ולא פנים דאפי' מה שפנו אלי הוא רק עורף לבד דכל עשיתו הוא בקרירות מצות אנשים מלומדה<sup data-n=\"3510\">139</sup> דצריך להניח תפילין ולהתפלל והעשיות הצדקה הוא מפני שהוא בוש בפני אחרים דמה יאמרו הבריות<sup data-n=\"3511\">140</sup> והנתינה הוא כמאן דשדי בתר כתפי'<sup data-n=\"3512\">141</sup> וזה כי פנה אלי עורף, ועי\"ז גורם למעלה ג\"כ שיהי' ואנכי הסתר אסתיר פני<sup data-n=\"3513\">142</sup> ביום ההוא הגם דלית אתר פנוי מיני'<sup data-n=\"3514\">143</sup> אך מאחר שמעלים ומסתיר ה\"ז מרוחק, וע\"י התשו' נעשה החזרת פב\"פ.\n<b>וזהו</b> אני לדודי ודודי לי, תחילה צ\"ל אני לדודי הוא תשו' מלמטלמ\"ע ועי\"ז ודודי לי מלמעלמ\"ט וכמ\"ש שובו אלי ואשיב אליכם<sup data-n=\"3515\">144</sup> וכמ\"ש והחזירנו בתשו\"ש מלפניך<sup data-n=\"3516\">145</sup> שיהי' החזרת פב\"פ, ומ\"ש דודי לי ואני לו קאי על יצי\"מ ועל מ\"ת צ\"ל תחילה דודי לי מלמעלמ\"ט שהי' גילוי אלקות וכמ\"ש וירד ה' על הר סיני<sup data-n=\"3517\">146</sup> ובנו\"ן יום קיבלו התורה<sup data-n=\"3518\">147</sup> ואח\"כ ודודי לי שיהי' קיום המצות כנ\"ל, וגבי שניהם נא' הרועה בשושנים, דהנה ארז\"ל א\"ת שושנים אלא ששונים<sup data-n=\"3519\">148</sup> וצ\"ל איך שייך לאמר א\"ת שושנים והלא בפסוק כתי' שושנים, והענין דהנה משה כשהזכיר שם אל במ\"ש אנא אל נא רפא נא לה<sup data-n=\"3520\">149</sup> שהוא תיקון הראשון מי\"ג ת\"ד השיב לו הקב\"ה ק\"ו ואבי' ירוק ירק בפני'<sup data-n=\"3521\">150</sup> כו' וכ\"ש הכא, אך דיו לבוא מן הדין להיות כנדון, וצ\"ל למה השיב לו ק\"ו דוקא, ופי' המגיד דשם אל<sup data-n=\"3522\">151</sup> הוא תיקון הא' מיגת\"ד וק\"ו הוא מדה",[["3508","137","<b>פשוטה לפני' ופשוטה לאחרי'</b>: ראה ר\"ה לד, א. שו\"ע אדה\"ז חאו\"ח הל' ר\"ה רסתק\"צ."],["3509","138","<b>כי פנה אלי עורף</b>: ירמי' ב, כז [ושם: פנו<sup data-n=\"e273\">ה</sup>]. ראה גם לקמן הנחה ד\"ה ובחודש השביעי הב' על יד הערה 31. (לעיל בחלק המאמרים) המשך יונתי על יד הערה 513. סה\"מ תרל\"ג ח\"ב ס\"ע שצו ואילך. וש\"נ. מאמרי אדה\"א נ\"ך ס\"ע רי ואילך. וש\"נ."],["3510","139","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' כו' נביאים וכתובים הערה 12."],["3511","140","<b>דמה יאמרו הבריות</b>: במדב\"ר פי\"ט, יג. יומא פו, א."],["3512","141","<b>כמאן דשדי בתר כתפי'</b>: ראה תניא פכ\"ב."],["3513","142","<b>ואנכי הסתר אסתיר פני</b>: וילך לא, יח."],["3514","143","<b>דלית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. שם בהוספות נב, ג."],["3515","144","<b>שובו אלי ואשיב אליכם</b>: מלאכי ג, ז [ושם: ואשובה]."],["3516","145","<b>וכמ\"ש והחזירנו בתשו\"ש מלפניך</b>: בתפלת שמו\"ע [ושם: לפניך]."],["3517","146","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["3518","147","<b>ובנו\"ן יום קיבלו התורה</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 1217."],["3519","148","<b>א\"ת שושנים אלא ששונים</b>: נסמן לעיל הנחה ד\"ה אני לדודי הא' הערה 79."],["3520","149","<b>אנא אל נא רפא נא לה</b>: בהעלותך יב, יג [בהוספת תיבת אנא — וכ\"ה גם לקמן בהחלק ההנחות בהנחה כאן]."],["3521","150","<b>השיב. . ואבי' ירוק ירק בפני'</b>: בהעלותך שם, יד. רש\"י וספרי שם. ב\"ק כה, א."],["3522","151","<b>ופי' המגיד דשם אל</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערות 427. 429.\n\n<b>ה</b>  אבל כ\"ה גם לקמן הנחה ד\"ה ובחודש השביעי הא' בסופו. והב' על יד הערה 31. ד\"ה כנשר יעיר קנו (ב\"פ)."]]],[2000480364,"ראשונה מיגמ\"ד לכן ע\"י שם אל המשיך ק\"ו, ומובן מזה שע\"י ק\"ו ממשיכים שם אל ולכן גבי דודי לי ואני שקאי על מ\"ת א' הרועה בשושנים להורות שע\"י תורה ממשיכים יגת\"ד, וגבי אני לדודי כו' ששם שייך שושנים שהם יגת\"ד ארז\"ל א\"ת שושנים אלא ששונים להורות ג\"כ שע\"י התורה ממשיכים בחי' יגמה\"ר, ואף שנת\"ל דאני לדודי הוא מלמעלמ\"ט<sup data-n=\"3523\">152</sup>, מ\"מ אילמלי עוזרו<sup data-n=\"3524\">153</sup> כו' וזהו הד' יודי\"ן והם מ' יום שמר\"ח אלול עד אחר יוהכ\"פ שנא' עליהם ואנכי עמדתי בהר כימים הראשונים מה הראשונים ברצון כך אחרונים ברצון, א\"כ ה\"ה ימי רצון לכן הם המסייעי' שיהי' תחילה אני לדודי ועי\"ז יהי' ודודי לי.",[["3523","152","<b>דאני לדודי הוא מלמעלמ\"ט</b>: כ\"ה בגוכתי\"ק. ראה גם לעיל שם כאן. לקמן בחלק ההנחות כאן."],["3524","153","<b>אילמלי עוזרו</b>: ראה קדושין ל, ב. סוכה נב, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא רפי\"ג</a>."]]],[2000480365,"<h3>יפה שעה א' הב' - ראשי פרקים</h3>\n<b>ש\"פ נצבים תר\"ם</b>\n<b>יפה</b> שעה א'<sup data-n=\"3525\">1</sup> בתשו' ומע\"ט<sup data-n=\"3526\">2</sup>, איך יצדקו שניהם, אני לדודי ועלי תשוקתו<sup data-n=\"3527\">3</sup> הול\"ל אלי, ואי' במדרש ד' תשוקות<sup data-n=\"3528\">4</sup> (בפ\"א<sup data-n=\"3529\">5</sup> ד\"א תיקונים<sup data-n=\"3530\">6</sup> אלו) ואל אישך תשוקתך<sup data-n=\"3531\">7</sup>, וצ\"ל מהו\"ע תשוקה למעלה כלום חסר, אומרו על ישראל, וצ\"ל ענין אני לדודי בעוה\"ז<sup data-n=\"3532\">8</sup>, תשו' א\"ד על חטא ועון<sup data-n=\"3533\">9</sup>, שהוא מצוה<sup data-n=\"3534\">10</sup>, ואם שהוא על חטא דוקא ה\"ז פתח לחטוא, והוא כמו שקשה על יפה שעה כו' ושם אפ\"ל שעה ל' וישע<sup data-n=\"3535\">11</sup> ה'<sup data-n=\"3536\">12</sup> כו' ועי\"ז",[["3525","1","<b>יפה שעה א'</b>: רשימת ראשי פרקים מכ\"ק אדמו\"ר מהורש\"ב ממאמר הז' מהמשך יונתי (פי\"ט-פכ\"א). שנדפס לעיל בחלק המאמרים [ושם הפתיחה: ומעתה כו' אני לדודי ועלי תשוקתו].\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה ”נכתב בשנת תרמ\"ב כפי ששמעתי מהר\"ן מוויליז\" נדפסה לאח\"ז.\nהנחה אחרת מדרוש זה נדפסה לקמן (בחלק ההנחות)."],["3526","2","<b>יפה שעה א' בתשו' ומע\"ט</b>: אבות פ\"ד, מי\"ז."],["3527","3","<b>אני לדודי ועלי תשוקתו</b>: שה\"ש ז, יא. ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 435."],["3528","4","<b>במדרש ד' תשוקות</b>: ראה ב\"ר פ\"כ, ז. שהש\"ר פ\"ז, יא."],["3529","5","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה ואהבת את ה' אלקיך ובהערה 74."],["3530","6","<b>ד\"א תיקונים</b>: כ\"ה בגוכתי\"ק (תיבה שני' אינה ברורה כ\"כ)"],["3531","7","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["3532","8","<b>אני לדודי בעוה\"ז</b>: ילקוט שמעוני שה\"ש שה\"ש ו, ג (סוף רמז תתקצא)."],["3533","9","<b>תשו' א\"ד </b>[ אינו דוקא]<b> על חטא ועון</b>: ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 454."],["3534","10","<b>תשו'. . שהוא מצוה</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערה 464."],["3535","11","<b>שעה ל' וישע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381302\" data-slug=\"likkutei-torah\" data-id=\"4001381302\">לקו\"ת שה\"ש מג, ג</a>. מאמרי אדה\"א קונטרסים ע' רנג. סה\"מ תרל\"ו ח\"ב ע' שמז. תרל\"ח ע' שטז. לקמן בהנחה שלאח\"ז על יד הערה *21. ד\"ה ובחודש השביעי על יד הערה 50."],["3536","12","<b>וישע ה'</b>: בראשית ד, ד."]]],[2000480366,"הם מע\"ט, אך אמרז\"ל כל ימיו בתשו'<sup data-n=\"3537\">13</sup> ואינו שייך ע\"ז אחטא ואשוב<sup data-n=\"3538\">14</sup> אין מספיקין<sup data-n=\"3539\">15</sup> כו', אך התשו' אינו על חטא, חטא חסרון<sup data-n=\"3540\">16</sup>, כ\"א והרוח תשוב<sup data-n=\"3541\">17</sup> כו' וצלה\"ק שבת, תשב<sup data-n=\"3542\">18</sup> ומה שייכות זל\"ז, וישבות<sup data-n=\"3543\">19</sup> כו' ששת ימים עשה<sup data-n=\"3544\">20</sup>, עד\"מ העושה ביד מ\"מ מושפלים המוחין, והראי' והשמיעה אדם הכותב ומצייר נתפס בו כל עצמות אדם כמו\"כ למעלה אף דלא בעמל<sup data-n=\"3545\">21</sup> כו' מ\"מ דיבורו של הקב\"ה<sup data-n=\"3546\">22</sup> כו' ובו נכלל הכל, בעשרה דברים<sup data-n=\"3547\">23</sup>, ה' בחכ' יסד<sup data-n=\"3548\">24</sup>, הגם דששת ימים כו' מ\"מ יש מוחין שבמדות, עצם נקודת המדה בעתיקא<sup data-n=\"3549\">25</sup> כו' והמדות נולדים מהמוח, ואח\"כ המוחין מנהיגים המדות וזהו בחכ' בתבונה בדעת חב\"ד, אך בחכ' ולא חכ', שהוא רק מלובש במדות, וזהו בראשית נמי מאמר<sup data-n=\"3550\">26</sup> בחוכמתא<sup data-n=\"3551\">27</sup>, כולם בחכ'<sup data-n=\"3552\">28</sup>, השביתה בקידוש היום ל\"ו שעות<sup data-n=\"3553\">29</sup> כו' יודע עיתיו ורגעיו<sup data-n=\"3554\">30</sup>, עד\"מ אדם השובת מלאכתו ואח\"כ רואה בעינו ובשכלו ובכח השמיעה ומתענג מזה, כמו\"כ למעלה בדבר ה' שמים נעשו<sup data-n=\"3555\">31</sup> ויש חכ' בדיבור, ויש אדם שהוא בעל שכל ואינו יכול להסביר הענין באותיות, ושרש הלבוש מרשימה, והוא מקור הכלים, ומשם נמשך הקו, ויש חכ' בעצם הדיבור, ברכו וקדשו<sup data-n=\"3556\">32</sup>, וכמו בנפש חלק ה'<sup data-n=\"3557\">33</sup> חלק מהעצם, וירדה למטה, והתשו' והרוח תשוב, ואח\"כ ושואבת לו חיים<sup data-n=\"3558\">34</sup> מלמעלה, וכמו בשבת כמו\"כ יובן בשמיטה שש תעבוד<sup data-n=\"3559\">35</sup>",[["3537","13","<b>כל ימיו בתשו'</b>: שבת קנג, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק עד, א</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטו."],["3538","14","<b>אחטא ואשוב</b>: תיבות אלו אינם ברורים כ\"כ."],["3539","15","<b>אחטא ואשוב אין מספיקין</b>: ראה יומא פה, ב (במשנה)."],["3540","16","<b>חטא חסרון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380923\" data-slug=\"likkutei-torah\" data-id=\"4001380923\">נצבים נא, א</a>. מאמרי אדה\"א דברים ח\"ג ע' תתקיד. נ\"ך ע' נא. סה\"מ תרל\"ב ח\"א ע' קמד. המשך תער\"ב ח\"ג ע' א'תנט. סה\"מ מלוקט א' ע' רצב. שם ב' ע' קכח ובהנסמן בהנ\"ל."],["3541","17","<b>והרוח תשוב</b>: קהלת יב ז."],["3542","18","<b>שבת תשב</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן ובהערה 462."],["3543","19","<b>וישבות</b>: בראשית ב, ב."],["3544","20","<b>ששת ימים עשה</b>: ראה לקמן בהנחה שנדפסה לאח\"ז הערה 32."],["3545","21","<b>דלא בעמל</b>: ראה ב\"ר פ\"ג, ב. ספ\"י."],["3546","22","<b>דיבורו של הקב\"ה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח."],["3547","23","<b>בעשרה דברים</b>: ראה חגיגה יב, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים ובהערה 41."],["3548","24","<b>ה' בחכ' יסד</b>: משלי ג, יט."],["3549","25","<b>המדה בעתיקא</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו הערה 543."],["3550","26","<b>בראשית נמי מאמר</b>: בראשית א, א. ר\"ה לב, א."],["3551","27","<b>בראשית. . בחוכמתא</b>: תרגום ירושלמי לבראשית א, א. כ\"ה בכ\"מ בדא\"ח ובתרגום שם: בחוכמא<sup data-n=\"e274\">א</sup> — סה\"מ מלוקט ג' ע' קסד."],["3552","28","<b>כולם בחכ'</b>: תהלים קד, כד."],["3553","29","<b>ל\"ו שעות</b>: ירושלמי ברכות פ\"ח, ה\"ה. ב\"ר פי\"א, ב. פי\"ב, ו."],["3554","30","<b>יודע עיתיו ורגעיו</b>: ראה ב\"ר פ\"י, ט. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051024\" data-slug=\"likkutei-sichot\" data-id=\"1300051024\">לקו\"ש בראשית כרך ה ע' 24</a> ואילך."],["3555","31","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3556","32","<b>ברכו וקדשו</b>: בראשית ב, ג."],["3557","33","<b>בנפש חלק ה'</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 54."],["3558","34","<b>ושואבת לו חיים</b>: ב\"ר פי\"ד, ט."],["3559","35","<b>שש תעבוד</b>: לעיל (בחלק המאמרים) בההמשך כאן הובא הכתוב ששת ימים תעשה מעשיך — משפטים כג, יב. ובההנחות כאן הובא הכתוב ששת ימים תעבוד — תשא לד, כא.\n\n<b>א</b>  ראה גם זהר בראשית לא, ריש ע\"ב: בראשית. . כמה דתרגם יונתן בראשית בחכמתא."]]],[2000480367,"היתר עשיות מלאכה, את השמים כו' אנ\"י מלא<sup data-n=\"3560\">36</sup> עצמותי, אך בהעלם, ואח\"כ ושבתה הארץ<sup data-n=\"3561\">37</sup> הכוח הצומח אל המקור שהוא למעלה, וכמו\"כ יובל תשובו<sup data-n=\"3562\">38</sup>, בפי' תשובה, ראובן שקנה משמעון, וזהו יפה שעה א' בתשו' החזרת הנפש והרוח תשוב אל אלקים כו'.\n<b>",[["3560","36","<b>את השמים כו' אנ\"י מלא</b>: ירמי' כג, כד. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540360\" data-slug=\"torat-chaim\" data-id=\"2300540360\">תו\"ח בשלח ח\"א קסו, ג</a>. וש\"נ."],["3561","37","<b>ושבתה הארץ</b>: בהר כה, ב."],["3562","38","<b>יובל תשובו</b>: בהר כה, י [בדילוג]. ראה שם יג [בדילוג]."]]],[2000480368,"<h3>יפה</b> שעה א' הג' (נכתב תרמ\"ב כפי ששמעתי מהר\"ן מוויליז)</h3>\n<b></b><b>ש\"פ נצבים תר\"ם לפ\"ק (נכתב תרמ\"ב כפי ששמעתי מהר\"ן מוויליז)</b>\nש\"פ נצבים\n<b>יפה</b> שעה א'<sup data-n=\"3563\">1</sup> בתשו' ומע\"ט בעוה\"ז מכל חיי עוה\"ב<sup data-n=\"3564\">2</sup>. ולכאו' צ\"ל בסדר העבודה, איך יצדקו שניהם כיחד תשו' וגם מע\"ט דהלא תשו' הוא על חטא ועון וא\"כ אינו מע\"ט. והענין דהנה כתי' אני לדודי ועלי תשוקתו<sup data-n=\"3565\">3</sup>, וצ\"ל אומרו עלי, והל\"ל אלי כמ\"ש בתחילת הפסוק אני לדודי, והנה אי' במדר' ד' תשוקות הן<sup data-n=\"3566\">4</sup> אין תשוקת אישה<sup data-n=\"3567\">5</sup> אלא לאיש כמ\"ש ואל אישך תשוקתך<sup data-n=\"3568\">6</sup> אין תשוקת גשמים אלא להארץ כמ\"ש פקדת הארץ ותשוקקי'<sup data-n=\"3569\">7</sup> אין תשוקת היצה\"ר אלא לקין וחביריו כמ\"ש ואליך תשוקתו<sup data-n=\"3570\">8</sup>, אין תשוקת הקב\"ה אלא על ישראל דכתי' אני לדודי ועלי תשוקתו, וצ\"ל מה שייך תשוקה למעלה. דמ\"ש אין תשוקת אישה אלא לאיש הוא תשוקת המקבל אל המשפיע דלזאת יקרא<sup data-n=\"3571\">9</sup> אישה כי מאיש לוקחה זאת דאש ה' מקבל מאש יו\"ד<sup data-n=\"3572\">10</sup>, ואין תשוקת הגשמים אלא לארץ הוא תשוקת המשפיע אל המקבל דמטרא בעלי",[["3563","1","<b>יפה שעה א'</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הז' מהמשך יונתי (פי\"ט-פכ\"א<sup data-n=\"e275\">א</sup>). שנדפס לעיל בחלק המאמרים [ושם הפתיחה: ומעתה כו' אני לדודי ועלי תשוקתו].\nר\"פ מכ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסו לפנ\"ז.\nהנחה אחרת מדרוש זה נדפסה לקמן (בחלק ההנחות).\nראה גם לקמן הנחה ד\"ה ובחודש השביעי שגם היא נרשמה בשנת תרמ\"ב ע\"פ מהר\"ן מוויליז<sup data-n=\"e276\">ב</sup>."],["3564","2","<b>יפה שעה א'. . עוה\"ב</b>: אבות פ\"ד, מי\"ז [ושם: העוה\"ב ראה גם לעיל הנחה ד\"ה זה הא']."],["3565","3","<b>אני לדודי ועלי תשוקתו</b>: שה\"ש ז, יא. ראה גם (לעיל בחלק המאמרים) בההמשך כאן ובהערה 435."],["3566","4","<b>במדר' ד' תשוקות הן</b>: ראה ב\"ר פ\"כ, ז. שהש\"ר פ\"ז, יא."],["3567","5","<b>אישה</b>: אוצ\"ל: אשה."],["3568","6","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["3569","7","<b>פקדת הארץ ותשוקקי'</b>: תהלים סה, י."],["3570","8","<b>ואליך תשוקתו</b>: בראשית ד, ז."],["3571","9","<b>דלזאת יקרא אשה</b>: שם ב, כג."],["3572","10","<b>אשה. . מאיש. . דאש ה'. . מאש יו\"ד</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערות 444-445.\n\n<b>א</b>  חלק מפרק כא נכנס בדרוש ויובן ענין הטוב (ר\"ה תרמ\"א).\n\n<b>ב</b>  לע\"ע לא נתברר מיהו מהר\"ן מוויליז."]]],[2000480369,"דארעא<sup data-n=\"3573\">11</sup>, אבל תשוקת הקב\"ה על ישראל מה שייך למעלה תשוקה, דלמטה שייך תשוקה שחסר לו הדבר לכן הוא חשק<sup data-n=\"3574\">12</sup> בה, אבל למעלה כלום חסר דאנת הוא שלימותא דכולה<sup data-n=\"3575\">13</sup>, ובאמת מצינו תשוקה למעלה וכמ\"ש רק באבותיך חשק ה'<sup data-n=\"3576\">14</sup>, וחשק ותשוקה הם ענין א' ואמרז\"ל נתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"3577\">15</sup> וא\"י מפני מה נתאווה<sup data-n=\"3578\">16</sup> אבל זה אנו יודעין שנתאווה, וצ\"ל מה שייך זה למעלה, וגם צ\"ל מ\"ש אין תשוקת הקב\"ה אלא ע\"ל ישראל והול\"ל לישראל ומזה ראי' דמ\"ש ועלי תשוקתו הוא בדקדוק.\n<b>ולהבין</b> זה הנה כתי' אני לדודי ודודי לי ונת\"ל שקאי על תשובה דר\"ת אלול וס\"ת ד' יודי\"ן<sup data-n=\"3579\">17</sup> והם מ\"ם יום שמר\"ח אלול עד יוהכ\"פ שהם יומי רצון ונותנין כח על תשובה. ועוי\"ל שקאי על כלליות המצות דאי' בילקוט אני לדודי בעוה\"ז ודודי לי בעוה\"ב<sup data-n=\"3580\">18</sup>, ובעוה\"ז יש כל המצות ולא תשובה לבד, ובכלליות המצות יש מצות תשובה ג\"כ שהיא ג\"כ מצוה<sup data-n=\"3581\">19</sup> רק שהיא מצוה כלליות, ואפי' צדיק גמור צריך לקיים מצות תשובה, ולפ\"ז א\"א לומר שהתשובה הוא על חטא ועון דוקא א\"כ נמצא בתורה פתח לחטוא<sup data-n=\"3582\">20</sup>, ולכאו' הוא קושי' הנ\"ל על מ\"ש יפה שעה א' בתשו' ומע\"ט, אך שם אפשר לתרץ דשעה א' פי' א יין קער<sup data-n=\"3583\">*21</sup> בתשובה שתחילה הוא עושה תשובה ואח\"כ המעשים הם מעשים טובים<sup data-n=\"3584\">21</sup>, אבל כאן א\"א לומר כן דארז\"ל נמצא כל ימיו בתשובה<sup data-n=\"3585\">22</sup>, ואמרז\"ל האומר יחטא ואשוב<sup data-n=\"3586\">23</sup> אין מספיקין בידו לעשות תשובה לבד מה שאינו מקבלים תשובתו אין מספיקין בידו לעשות תשובה, אלא צ\"ל שהוא באופן שהתשובה מועיל וא\"כ צ\"ל איך כל ימיו כו' דאם עשה תשו' היום מה שייך תשו' למחר. אך הענין דתשו' אינו על חטא ועון<sup data-n=\"3587\">24</sup> דוקא אלא החזרת הנפש לשרשה ומקורה וכמ\"ש והרוח תשוב אל אלקים אשר נתנו<sup data-n=\"3588\">25</sup>.",[["3573","11","<b>דמטרא בעלי דארעא</b>: תענית ו, ב. ראה גם לקמן (בחלק ההנחות) בהנחה כאן ובהערה 11."],["3574","12","<b>חשק</b>: אוצ\"ל: חושק."],["3575","13","<b>דאנת הוא שלימותא דכולה</b>: ראה ת\"ז בהקדמה יז, ב."],["3576","14","<b>רק באבותיך חשק ה'</b>: עקב י, טו."],["3577","15","<b>נתאווה הקב\"ה. . דירה בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 1693."],["3578","16","<b>וא\"י מפני מה נתאווה</b>: ראה גם לעיל המשך מצה זו שם ובהערה 1776."],["3579","17","<b>אני לדודי. . דר\"ת אלול וס\"ת ד' יודי\"ן</b>: שה\"ש ו, ג. ראה לעיל הנחה רד\"ה אני לדודי הב'. וש\"נ."],["3580","18","<b>אני לדודי בעוה\"ז ודודי לי בעוה\"ב</b>: ילקוט שמעוני שה\"ש שם (סוף רמז תתקצא)."],["3581","19","<b>מצות תשובה. . שהיא ג\"כ מצוה</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערה 464."],["3582","20","<b>שהתשובה. . חטא ועון. . לחטוא</b>: ראה ברכת שמואל לר' אהרן שמואל קאיידנבור פ' וילך נד, ג."],["3583","*21","<b>דשעה א' פי' איין קער</b>: ראה גם בהנחה שלפנ\"ז ובהערה 11."],["3584","21","<b>תשובה ואח\"כ. . מעשים טובים</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'קעט. וש\"נ. תו\"ח וארא ח\"א ריש ע' סו. וש\"נ. סה\"מ תרל\"ח ע' שטז. וש\"נ."],["3585","22","<b>נמצא כל ימיו בתשובה</b>: שבת קנג, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק עד, א</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקטו."],["3586","23","<b>האומר יחטא ואשוב</b>: ראה יומא פה, ב (במשנה ושם: אחטא)."],["3587","24","<b>דתשו' אינו על חטא ועון</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי כאן ובהערה 454."],["3588","25","<b>והרוח תשוב אל אלקים אשר נתנו</b>: וכ\"ה גם בסיום ההנחה. לקמן הנחה ד\"ה ובחודש השביעי (כמה פעמים). ועד\"ז (לקמן בחלק ההנחות) הנחה ד\"ה שובה ישראל הא' על יד הערה 51. — קהלת יב ז [ושם: האלקים. . נתנה]."]]],[2000480370,"<b>והנה</b> להבין ענין התשו' צ\"ל תחילה מהו\"ע חטא ועון, לא כמו שהעולם סוברי' שחטא הוא שחוטא בפ\"מ, אלא חטא הוא כמ\"ש קולע אל השערה ולא יחטיא<sup data-n=\"3589\">26</sup> שאינו עושה חסרון אפי' כשערה, א\"כ כשעושה חסרון כשערה זה נק' חטא, וא\"כ אפי' כשעבר דקדוק קל של ד\"ס נק' חטא, וכן כמ\"ש גבי שלמה והיתי אני ובני שלמה חטאים<sup data-n=\"3590\">27</sup>, ופירש\"י חסרים, פי' שחסרים מהבטחת הטובה שהבטיחם דוד זה נק' ג\"כ חטא, וא\"כ כשאומרים דתשו' שייך אפי' כשלא יש חטא ועון היינו אפי' שלא יש שום חסרון אפי' חסרון קצת שייך ג\"כ תשו' והוא כמ\"ש והרוח תשוב אל אלקים אשר נתנו החזרת הנפש אל שרשה ומקורה, ובד\"כ יש בתשובה כמה מדרי' דכשיש איזה חטא ועון א\"כ ה\"ה אב\"א וצ\"ל תשו' שיחזיר להיות בבחי' פב\"פ, ואפי' כשלא יש שום חטא ועון שייך ג\"כ תשו' והוא ל' השבה כמו אדם שהולך בדרך שצריך לילך וחזר אח\"כ ה\"ז השבה, כמו\"כ כאן שהלך בדרך הישר וקיים תומ\"צ מ\"מ שייך תשובה ל' השבה<sup data-n=\"3591\">28</sup> שמחזיר את הנפש לשרשו.\n<b>וביאור</b> ענין התשו' הנה שבת אותיות תשב<sup data-n=\"3592\">29</sup> וצ\"ל מה שייך שבת לתשו' שהרי שבת היא מצוה בפ\"ע<sup data-n=\"3593\">30</sup> ותשו' מצוה בפ\"ע. והענין דהנה כתי' כי בו שבת<sup data-n=\"3594\">31</sup>, שהוא ל' שביתה, והענין דהנה כתי' ששת ימים ולא כתי' בששת ימים עשה<sup data-n=\"3595\">32</sup> שהי' משמע שבששת ימים פעל פעולה בנבראים, וכתי' ששת ימים שששת ימים נשפלו בעשי' וכמאמר כל יומא ויומא עביד עבידתא<sup data-n=\"3596\">33</sup> ביום ראשון נמשך מדת החסד למטה דמדת החסד למע' אינו כמו חסד למטה<sup data-n=\"3597\">34</sup>, דלמטה החסד גורם ההשפעה ולא שהחסד עצמו נשפע ולמע' החסד עצמו נמשך למטה וכמ\"ש מכלכל חיים בחסד<sup data-n=\"3598\">35</sup> שחיים נמשך מחסד עצמו שנמשך למטה, ומכלכל הוא שנמשך כלי בתוך כלי, וביום ב' נמשך גבו' וביום ג' ת\"ת, ובאמת גם הכחות שלמע' ממדות נשפלו בהעשי' וכמו עד\"מ למטה אומן שעושה מלאכה הגם שעשי' המלאכה הוא בידים או ברגלי' ומ\"מ מושפלי' בהעשי' כל הכחות כמו כלי העין צריך להסתכל בהציור שעושה ול\"ד כלי הראי' הגשמיות אפי' כלי הראי' הרוחניות כמו ראיות השכל, ובכלל מושפל חב\"ד בעשי' דחכ' הוא שנופל על ההמצאה, ובינה הוא ההתבוננות בהמדידה בכמות",[["3589","26","<b>קולע אל השערה ולא יחטיא</b>: ס' שופטים כ, טז [בדילוג]."],["3590","27","<b>והיתי אני ובני שלמה חטאים</b>: מלכים-א א, כא."],["3591","28","<b>תשו'. . ל' השבה</b>: ראה בהערה 24."],["3592","29","<b>שבת אותיות תשב</b>: ראה אגה\"ת ספ\"י. (לעיל בחלק המאמרים) בההמשך כאן ובהערה 462."],["3593","30","<b>שבת היא מצוה בפ\"ע</b>: סהמ\"צ להרמב\"ם מ\"ע קנד. קנה. רמב\"ם הל' שבת רפ\"א. רפכ\"ט."],["3594","31","<b>כי בו שבת</b>: בראשית ב, ג."],["3595","32","<b>ששת ימים. . עשה</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, ריש ע\"ב. האזינו חצר, ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["3596","33","<b>כל יומא. . עבידתא</b>: ראה זהר ויגש רה, סע\"א. אמור שם. השמטות לזח\"א רסד, ב."],["3597","34","<b>החסד למע'. . חסד למטה</b>: ראה אוה\"ת יתרו ס\"ע תתקכו ואילך. סה\"מ תרכ\"ו ע' ב."],["3598","35","<b>מכלכל חיים בחסד</b>: נוסח שמו\"ע. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה והנה כובע ובהערה 95. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370166\" data-slug=\"torah-or\" data-id=\"3901370166\">תו\"א מקץ לו, ב</a>. מג\"א קכג, א. סידור שער החנוכה רעח, ד."]]],[2000480371,"ואיכת<sup data-n=\"3599\">36</sup>, ודעת הוא לקשר דעתו איך לעשות כך או באופן אחר (ול\"נ שא' ודעת מקשר חו\"ב<sup data-n=\"3600\">37</sup> ), ובאמת אנו רואין שכל הכחות מושפלי' בהעשי' ואפי' כח השמיעה מושפל בעשי' כמו כשעושים האופן בתוך האופן שהעיגול הגדול מסבב את הקטן והוא מסבב את העיגול הגדול ממנו שצריך לשמוע בכח השמיעה אולי יש איזה כבדות וימנע ההילוך וצריך לחשוב החשבון שיסבב א' את חבירו.\n<b>וכמו\"כ</b> יובן למע' שגם המד' שלמעלה ממדות נשפלו בעשי' וכמארז\"ל בעשרה דברים ברא הקב\"ה<sup data-n=\"3601\">38</sup> את עולמו בחכ' ובחכ'<sup data-n=\"3602\">39</sup> ובתבונה ובדעת, ה' בחכ' יסד ארץ<sup data-n=\"3603\">40</sup> כונן שמים בתבונה בדעתו תהומות נבקעו<sup data-n=\"3604\">41</sup>, רק ההפרש הוא שכאן כתי' ה' בחכ' וגבי מדות כתי' ששת ימים דהששת ימים עצמן נשפלו בעשי', וכאן החכ' נתלבש במדות, וזהו ה' בחכ' יסד ארץ, ועיקר ההתהוות הוא מחכ', הגם שהמדות שרשן למעלה מחכ' דז\"א בעתיקא אחיד ותליא<sup data-n=\"3605\">42</sup> שהוא המתנשא מימות עולם<sup data-n=\"3606\">43</sup> מרומם ומנושא מגדר עולם המעתיק הרים<sup data-n=\"3607\">44</sup>, זה למע' מסדר השתל' אבל בסדר השתל' חכ' למע' ממדות לכן עיקר הבריאה מחכ', ואף שהוא רק חכ' שבמדות שאינו בערך לגבי חכ' בעצם, מ\"מ ה\"ז בכלל מוחין שיש כמה מדרי' במוחין כמו לאו כל מוחא סביל דא<sup data-n=\"3608\">45</sup> וכמו זה יכול ללמוד כך והשני יכול ללמוד בטוב יותר והג' עוד טוב יותר ומ\"מ הכל נק' מוחין, כמו\"כ כאן הגם שהוא מדות מ\"מ ה\"ז מוחין, ובאמת מושפל בעשי' ג\"כ כחות שלמע' מחכ' דכתי' שוקיו עמודיו שש<sup data-n=\"3609\">46</sup> ואמרז\"ל שוקיו זה עולם שנשתוקק הקב\"ה לבראותו<sup data-n=\"3610\">47</sup> נתאווה הקב\"ה להיות לו דירה בתחתונים מפני מה א\"י אבל זה אנו יודעי' שנתאווה א\"כ יש בזה רצון ג\"כ, ובאמת עיקר ההתהוות הוא מעצמיות אוא\"ס וכמ\"ש בסש\"ב איהו וגרמוהי חד פי' איהו הוא בעצמו בל\"א ער „ליין והוא א\"ס הנעלם ומשם שרש התהוות העולם דאיהו מתייחד עם גרמוהי<sup data-n=\"3611\">48</sup>",[["3599","36","<b>ואיכת</b>: אוצ\"ל: ואיכות."],["3600","37","<b>ול\"נ. . חו\"ב</b>: כנראה הגהת כ\"ק אדמו\"ר מהורש\"ב. ולהעיר מלקמן (בחלק ההנחות) בהנחה כאן על יד הערה 46."],["3601","38","<b>בעשרה דברים ברא הקב\"ה</b>: ראה חגיגה יב, א. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים ובהערה 41."],["3602","39","<b>בחכ' ובחכ'</b>: כ\"ה בגוכתי\"ק."],["3603","40","<b>ה' בחכ' יסד ארץ</b>: משלי ג, יט."],["3604","41","<b>בדעתו תהומות נבקעו</b>: משלי שם, כ."],["3605","42","<b>דז\"א בעתיקא אחיד ותליא</b>: ראה זהר אד\"ז האזינו רצב, א. לעיל ח\"א (בחלק המאמרים) המשך מצה זו הערה 543."],["3606","43","<b>המתנשא מימות עולם</b>: ע\"פ ברכת יוצר אור."],["3607","44","<b>המעתיק הרים</b>: איוב ט, ה. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רמה. וש\"נ. שעה\"י קכו, א ובהערה 5. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540180\" data-slug=\"torat-chaim\" data-id=\"2300540180\">תו\"ח בשלח ח\"א קמב, סע\"ב</a>. וש\"נ."],["3608","45","<b>לאו כל מוחא סביל דא</b>: ראה עבודת הקודש ס\"ת ח\"ד, רפ\"ב בשם הרשב\"י. של\"ה תולדות אדם ב, א. ענייני תפלה וקריאה בס\"ת רנא, ב (בהגהה — ד\"ה על החוט). רנז, א. נר מצוה רסג, ב. תניא ספכ\"ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370066\" data-slug=\"torah-or\" data-id=\"3901370066\">תו\"א וירא יד, ד</a>. פיה\"מ לא, ד. ש\"א פט, ב. תו\"ח ויצא קסט, ב. ג ובהערה 14. בשלח ח\"א רמט, ג."],["3609","46","<b>שוקיו עמודיו שש</b>: שה\"ש ה, טו [ושם: עמודי — ראה גם לעיל הנחה ד\"ה אני לדודי הב' ובהערה 20]."],["3610","47","<b>שוקיו. . שנשתוקק הקב\"ה לבראותו</b>: ראה במד\"ר רפ\"י."],["3611","48","<b>בסש\"ב איהו וגרמוהי. . עם גרמוהי</b>: אגה\"ק ס\"כ (תניא קכט, א. קל, ב). ראה סה\"מ תרל\"ח ע' ד."]]],[2000480372,"לברוא מאין ליש, ואח\"כ בשבת כי בו שבת כמו האדם בעת עשי' המלאכה מושפלי' הכחות בעשי' ואח\"כ השביתה היינו שהכחות חוזרים לשרשם ומקורן.\n<b>כמו\"כ</b> יובן למע' דהגם דלא בעמל וביגיעה ברא הקב\"ה את עולמו<sup data-n=\"3612\">49</sup> כ\"א במח' וברוח פיו מ\"מ דיבורו של הקב\"ה חשיב מעשה<sup data-n=\"3613\">50</sup>, וצ\"ל שבדיבור נמצא הכל וכן אנו רואים דכשדובר צריך לחשוב מה לדבר, ומדות יש ג\"כ בדבור דבאיזה מדה שהוא ה\"ה דובר, ובאמת יש חכ' בדיבור ג\"כ, כמו שאנו רואין שיש אדם שמבין את השכל ויכול להסבירו לחבירו, ויש שהוא מבין את השכל בטוב וא\"י להסבירו לחבירו<sup data-n=\"3614\">51</sup>. ולכאורה צ\"ל מפני מה א\"י להסבירו שה\"ה מבין את השכל וגם אותיות ההברה נמצאים אצלו ולמה א\"י להסבירו, אלא מפני שחסר לו כח ההלבשה באותיות, דכח ההלבשה שרשו מאותיות הרשימה שלפני הצמצום פי' שלא נגע בו הצמצום<sup data-n=\"3615\">52</sup>, ולכן משם נמשך אורות בכלים ע\"י המשכת הקו, וכח זה חסר לו, הרי שיש חכ' בדיבור, ועוד מאחר שהשכל מגלה דיבור איך שייך שבדיבור עצמו לא יהי' חכ', והנה כתי' בדבר ה' שמים נעשו<sup data-n=\"3616\">53</sup> ומאחר שנתהוו מדיבור מוכרח לומר שגם בנבראים יש חכ' וכמו אשר יצר את האדם בחכ'<sup data-n=\"3617\">54</sup> ול\"ד אדם אלא אפי' כל הנבראים יש בהם חכ' כמו בעשבים ואילנות יש בהם חכ' שא\"א להשיגו וכמה נלאו המחקרים עד שמצאו שכמו שבאדם יש גידי הדם וגידי הרוח כמו\"כ בעלים יש גידי הדם וגידי הרוח<sup data-n=\"3618\">55</sup> ובאמת לא השיגו בשלימות שיש בזה חכ' נפלאה מאד. ומזה יתבונן האדם דמה רבו מעשיך ה'<sup data-n=\"3619\">56</sup> שיש ריבוי הנבראים שנתהווה ובכולם יש חכ' מכ\"ש שבהמקור המהווה שיש חכ' ומזה יבין גדלות הבורא. וכמו אומן שעשה כלי בציורי' יפי', ואף שכעת לא יש כאן האומן ומ\"מ יודעין מהכלי שהאומן הוא חכם גדול, כמו\"כ מהעולם יובן גדלות הבורא. וזהו בראשית בחוכמתא<sup data-n=\"3620\">57</sup>, וזהו בששת ימי החול היו הכחות מושפלי' בעשי' ואח\"כ בשבת כי בו שבת ענין השביתה הוא החזרת המוחין למקורן ושרשן.\n<b>וזהו\"ע</b> קידוש היום דאי' במדר' אותה האורה שמשה ל\"ו שעות<sup data-n=\"3621\">58</sup> י\"ב שעות היום וי\"ב שעות הלילה וי\"ב שעות דשבת לכן ר\"ה נק' ג\"כ סתם",[["3612","49","<b>דלא בעמל. . את עולמו</b>: ראה ב\"ר פ\"ג, ב. ספ\"י."],["3613","50","<b>דיבורו. . חשיב מעשה</b>: ראה ב\"ר פמ\"ד, כב. רש\"י לך טו, יח."],["3614","51","<b>אדם שמבין את השכל. . וא\"י להסבירו לחבירו</b>: ראה גם (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 59 ואילך."],["3615","52","<b>מאותיות הרשימה. . שלא נגע בו הצמצום</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו פ\"ו."],["3616","53","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3617","54","<b>אשר יצר את האדם בחכ'</b>: ברכת אשר יצר. ראה גם ש\"א פג, א."],["3618","55","<b>המחקרים. . בעלים יש גידי הדם והרוח</b>: ראה גם (לקמן בחלק ההנחות) בהנחה כאן על יד הערה 64."],["3619","56","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד. ראה גם לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 36."],["3620","57","<b>בראשית בחוכמתא</b>: בראשית א, א ובתרגום ירושלמי שם. ראה גם לעיל (בחלק המאמרים) המשך יונתי כאן הערה 478."],["3621","58","<b>אותה האורה שמשה ל\"ו שעות</b>: ירושלמי ברכות פ\"ח, ה\"ה. ב\"ר פי\"א, ב. פי\"ב, ו."]]],[2000480373,"היום<sup data-n=\"3622\">59</sup>, והקב\"ה יודע עתיו ורגעיו<sup data-n=\"3623\">60</sup> א\"צ להוסיף מחול על הקדש ואפשר לצמצם, ואחר השבת כתי' ויברך אלקי' את יום השביעי ויקדש אותו<sup data-n=\"3624\">61</sup> ברכו וקדשו, כמו עד\"מ אומן שעשה כלי ה\"ה מקבל תענוג ממנו אימתי הוא מקבל התענוג לאחר שכל הכחות נחו מיגיעם, דבעת עשי' המלאכה אינו שייך תענוג שהרי חסר עדיין ולאחר שנגמר המלאכה ג\"כ אינו שייך תענוג מפני שכל הכחות הם יגעים כמו שמקבל תענוג בכלי העין כשרואה שהציור הוא ציור יפה, ותיכף אחר עשיית המלאכה הרי כלי העין עיף ויגע מהעשי' ואינו שייך שיקבל בה תענוג כ\"א לאחר שנחה מיגיעתה, וכן כשלומד איזה שכל ומטרד<sup data-n=\"3625\">62</sup> המוח הרבה והוא מקבל תענוג מהלימוד אימתי הוא מקבל התענוג דוקא לאחר שנח המוח מהיגיעה, דבעת שהוא עיף ויגע עדיין לא יקבל תענוג כלל. וכמו\"כ יובן למעלה הגם דלא בעמל וביגיעה ברא הקב\"ה את עולמו כ\"א במא' וברוח פיו וא\"כ אינו שייך שביתה ג\"כ, אבל מ\"מ דיבור של הקב\"ה חשיב מעשה והשביתה הוא החזרת המוחין למקורן ושרשן ואח\"כ נמשך תענוג. אך תענוג למעלה אינו כמו תענוג למטה שמתחילה הי' חסר מהתענוג ואח\"כ נמשך עונג, אבל למעלה כלום חסר דאנת הוא שלימותא דכולה<sup data-n=\"3626\">63</sup>, אלא הפי' הוא שנמשך עונג למטה, וזהו ברכו וקדשו, ברכו הו\"ע הברכה דתוספתא של הקב\"ה מרובה על העיקר<sup data-n=\"3627\">64</sup>, וקדשו הוא שאפי' מה שקדוש ומובדל מגדר העולמות יומשך בעולם. והנה כמו עד\"מ אדם כשדיבר איזה שכל אפי' כשפסק לדבר מ\"מ השכל עולה במח' בעצמו בל\"א עס טר„כט זעך „ליין, וכשלא יבלבלנו אדם יחשוב הפרטים ג\"כ, וכשיבלבלנו אדם יחשוב רק כלל הדברים אבל לא יופסק לגמרי, כמו\"כ יובן למעלה אפי' דבשבת נסתלקו הכחות לא נסתלקו רק מדיבור אבל לא ממח' לכן בשבת העולם מקבל ממח'<sup data-n=\"3628\">65</sup> ובאמת בשבת עליות העולמות<sup data-n=\"3629\">66</sup>.\n<b>והנה</b> כמשנת\"ל בשבת כן יובן בעבודה בנפש האדם, דהנה הנשמה היא חלק אלוקה ממעל<sup data-n=\"3630\">67</sup> ולכאו' צ\"ל הלא חלק הוא א' ממאה או מאלף או מריבוי ומה שייך זה בשם הוי' שהוא הי' הוה ויהי'<sup data-n=\"3631\">68</sup>, והענין דהנה עצם הניצוץ קטן ניצוץ אלקי",[["3622","59","<b>ר\"ה נק'. . היום</b>: ראה זהר בא לב, ב. בשלח מד, א. פינחס רלא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380885\" data-slug=\"likkutei-torah\" data-id=\"4001380885\">מב, א</a>. מאמרי אדה\"א דברים ח\"ג ע' תשמג. וש\"נ. סה\"מ תרל\"ב ח\"ב ע' תקט. ע' תקי. ריש ע' תרא. תרנ\"ז ע' יא ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241192\" data-slug=\"likkutei-sichot\" data-id=\"1300241192\">לקו\"ש נצבים כרך כד ע' 192</a>. לקמן (בחלק ההנחות) בהנחה כאן."],["3623","60","<b>והקב\"ה יודע עתיו ורגעיו</b>: ראה ב\"ר פ\"י, ט. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051024\" data-slug=\"likkutei-sichot\" data-id=\"1300051024\">לקו\"ש בראשית כרך ה ע' 24</a> ואילך."],["3624","61","<b>ויברך. . ויקדש אותו</b>: התחלת הכתוב כי בו שבת — בראשית ב, ג."],["3625","62","<b>ומטרד</b>: אוצ\"ל: ומטריד."],["3626","63","<b>דאנת הוא שלימותא דכולה</b>: ת\"ז בהקדמה יז, ב."],["3627","64","<b>דתוספתא של הקב\"ה. . העיקר</b>: ראה ב\"ר פס\"א, ד. לקו\"ש וישלח כרך ה ע' 422 הערה 3. ע' 423 הערה 10. סה\"מ תרל\"ח ע' מט. וש\"נ."],["3628","65","<b>בשבת העולם מקבל ממח'</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערות 382-383."],["3629","66","<b>בשבת עליות העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540867\" data-slug=\"torat-chaim\" data-id=\"2300540867\">תו\"ח בא ח\"א קכז, א</a> הערה 667."],["3630","67","<b>הנשמה היא חלק אלוקה ממעל</b>: ראה איוב לא, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה ובהערה 54."],["3631","68","<b>הוי' שהוא הי' הוה ויהי'</b>: ראה שער היחוד והאמונה פ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680292\" data-slug=\"torat-chaim\" data-id=\"2300680292\">תו\"ח מקץ ריט, ד</a> הערה 62."]]],[2000480374,"שמחי' את הנה\"א יש תמיד כליון ותשוקה בל\"א „ ציא לאלקות ועצם הניצוץ אינו בערך הגשמה אפי' בעשר כחות, ומה שמתלבש בגוף הוא רק הארה ומקצת מהנשמה<sup data-n=\"3632\">69</sup> וראי' שהמלאך בשליש עולם עומד<sup data-n=\"3633\">70</sup> כ\"ש הנשמה שלמעלה מהמלאך שהגוף קטן מהכיל את כל הנשמה, אלא מה שנתלבש בגוף הוא רק הארה, וזהו\"ע התשובה ל' השבה לשרשה ומקורה, והנה התחלת העלי' הוא כשאדם עומד משנתו ומתפלל ולומד מתחיל הנפש להתרומם וכמ\"ש סלסלה ותרוממך<sup data-n=\"3634\">71</sup> כמו סלסול השערות שמפריד השערות זה מזה כמו\"כ ע\"י לימוד הלכות ומקשה ורימנהו כאן כתוב כך ובמק\"א להיפך ומתרץ זה סלסול הלכות עי\"ז ותרוממך הנפש מתרומם, וכן צדקה תרומם גוי<sup data-n=\"3635\">72</sup> שע\"י נתינת הצדקה נעשה היד מרכבה למדות החסד שבלי גבול הגם שהוא חסד ולא גבו', מ\"מ מדת החסד עצמה הוא בלי גבול, וזהו רוממות הנפש ול\"ד ע\"י כ\"א<sup data-n=\"3636\">73</sup> ע\"י כל המצות שנק' בשם צדקה וכמ\"ש וצדקה<sup data-n=\"3637\">74</sup> כו' כל המצוה, אך זה אינו עדיין השבות הנפש לגמרי והעיקר בעת השינה שאז הנפש עולה למעלה וכמ\"ש ב\"ידך א\"פקיד ר\"וחי ר\"ת בא\"ר<sup data-n=\"3638\">75</sup> דכמו הבאר שנובע מתתא לעילא כמו\"כ הנשמה עולה מלמטלמ\"ע, ואם הרויחה ביום שקיימה תומ\"צ אז היא עולה למעלה, וזהו תשובה ל' השבה שהנפש עולה לשרשו ומקורו אבל אם פגם והנפש עצמו ה\"ה שליח מהמשלח וחזקה שליח עושה שליחותו<sup data-n=\"3639\">76</sup>, אבל יש יצה\"ר ונה\"ב המונעים ומעכבים וזה אין תשוקת היצה\"ר אלא לקין וחביריו שמעורר מדנים שזהו\"ע הפגם והלכלוך שעי\"ז נדחה ממחיצתו של הקב\"ה, וצריך תשובה חרטה על להבא<sup data-n=\"3640\">77</sup> ופי' חרטה שיעקור הרצון לגמרי, ולכן בק\"ש שעהמ\"ט צריך לעשות חשבון צדק בנפשו במה שעשה בכה\"י ואם פגם באיזו דבר צריך לעשות תשובה חרטה, ואח\"כ בעת השינה יתעלה הנשמה למעלה ושואבת לה חיים<sup data-n=\"3641\">78</sup> מלמעלה, ואח\"כ ביום המעהמ\"צ באו\"א שכל יום מסייע לחבירו שע\"י התשובה שהוא החזרת הנפש נמשך אור העליון יותר ביום שלאחריו.\n<b>ולהבין</b> יותר ע' התשובה ל' השבה יובן משמיטה דכתי' שש שנים תזרע שדך<sup data-n=\"3642\">79</sup> ובשנה השביעית שבת שבתון<sup data-n=\"3643\">80</sup> כמו גבי שבת כתי' ששת ימים תעשה",[["3632","69","<b>שמתלבש בגוף. . ומקצת מהנשמה</b>: ראה לעיל ח\"א (בחלק המאמרים) המשך מצה זו ובהערה 595."],["3633","70","<b>שהמלאך בשליש עולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 44."],["3634","71","<b>סלסלה ותרוממך</b>: משלי ד, ח. ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 221."],["3635","72","<b>צדקה תרומם גוי</b>: משלי יד, לד."],["3636","73","<b>ע\"י כ\"א</b>: על ידה כ\"א. או אוצ\"ל: ע\"י הצדקה כ\"א."],["3637","74","<b>כל המצות. . צדקה. . וצדקה</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי הערה 27."],["3638","75","<b>ב\"ידך א\"פקיד ר\"וחי ר\"ת בא\"ר</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן ובהערה 489."],["3639","76","<b>וחזקה שליח עושה שליחותו</b>: ערובין לא, ב."],["3640","77","<b>להבא</b>: אוצ\"ל: העבר וקבלה על להבא."],["3641","78","<b>הנשמה. . ושואבת לה חיים</b>: נסמן (לעיל בחלק המאמרים) בההמשך כאן הערה 490."],["3642","79","<b>שש שנים תזרע שדך</b>: בהר כה, ג."],["3643","80","<b>ובשנה השביעית שבת שבתון</b>: שם כה, ד."]]],[2000480375,"מעשיך<sup data-n=\"3644\">81</sup> כמו\"כ כאן שש שנים תזרע שדך וביום השביעי שבת לה'<sup data-n=\"3645\">82</sup> כמו\"כ כאן ובשנה השביעית שבת שבתון. והנה ממ\"ש ששת ימים תעשה מעשיך יש היתר על עשיי' המלאכה דלכאו' מאן דמחוי במחוג<sup data-n=\"3646\">83</sup> קדם מלכא קטלא חייב ובפרט מלאכות גרועות כמו זריעה וקצירה, וכתיב את השמים ואת הארץ אני מלא<sup data-n=\"3647\">84</sup> לית אתר פנוי מני'<sup data-n=\"3648\">85</sup>, אך הענין דקאמר קדם מלכא שהמלך הוא נראה ונגלה והמלאכה תופס מקום, אבל כאן מה שאני מלא הוא בהעלם דפי' אני הוא א\"ס עצומ\"ה בחי' הרשימה שלפני הצמצום, פי' שלא נגע בו הצמצום והוא מקור להעלם (והמלאכה אינו תופס מקום) לכן מותר בעשיי' מלאכה, ומטעם זה לא הי' מתירים עשיי' המלאכה רק מפני שיש היתר בתורה אפ\"ל שהוא מטעם זה, אבל בשביעית אז שביתה ממלאכה דע\"י הזריעה הוא מעורר את כח הצומח שבארץ ובשביעית הוא שובת מזריעה שאינו מעלה מ\"ן לכח הצומח. ויותר יובן מיובל שבת [ושמיטה], רק שבת או' תשב וגבי יובל כתי' תשבו איש אל אחוזתו<sup data-n=\"3649\">86</sup> דכתי' בפי' תשובה דביובל שדות חוזרת לבעליהם וכמו עד\"מ ראובן שקנה בית משמעון שבתחילה הי' ע\"ש ראובן ועכשיו הוא ע\"ש שמעון ואח\"כ ביובל הבית חוזרת לראובן כמו שהי' מקודם וזהו תשובה וגם יובל הוא ח'<sup data-n=\"3650\">87</sup> שהוא לאחר ז' שמיטות. וזהו יפה שעה אחת בתשובה ומע\"ט, דיש ב' מדרי' בתשובה אם פגם אז צ\"ל תשובה חרטה עקירת הרצון, ואם לא פגם אז התשובה הוא החזרת הנפש לשרשה ומקורה וכמ\"ש והרוח תשוב אל אלקים אשר נתנו, ותשובה זו היא דוקא כשהמעשים הם מעשים טובים ומאירים<sup data-n=\"3651\">88</sup>, וזהו יפה שעה בתשובה כשהוא עושה תשובה היינו החזרת לשרשה ומקורה כמ\"ש והרוח תשוב כו' אשר נתנו אז ניכר שהמעשים הם מעשים טובים ומאירים כו'.",[["3644","81","<b>ששת ימים תעשה מעשיך</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן ובהערה 494."],["3645","82","<b>וביום השביעי שבת לה'</b>: ראה גם לקו\"ת יו\"כ סח, ב. תשא לא, טו [בדילוג]. ויקהל לה, ב [בדילוגים]. או ע\"פ יתרו כ, י. ואתחנן ה, יד."],["3646","83","<b>מאן דמחוי במחוג</b>: ראה חגיגה ה, ב."],["3647","84","<b>את השמים. . מלא</b>: ירמי' כג, כד. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310053\" data-slug=\"tanya\" data-id=\"3401310053\">תניא פמ\"ח</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540360\" data-slug=\"torat-chaim\" data-id=\"2300540360\">תו\"ח בשלח ח\"א קסו, ג</a>. וש\"נ."],["3648","85","<b>לית אתר פנוי מני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. שם בהוספות נב, ג."],["3649","86","<b>תשבו איש אל אחוזתו</b>: בהר כה, יג."],["3650","87","<b>ח'</b>: ראה גם לקמן (בחלק ההנחות) בהנחה כאן: מד' שמיני ובהערה 108."],["3651","88","<b>ותשובה. . מעשים טובים ומאירים</b>: ראה גם לעיל (בחלק המאמרים) בההמשך כאן הערה 517."]]],[2000480376,"<h3>ובחודש השביעי הא' - ראשי פרקים</h3>\n<b>ר\"ה התרמ\"א</b>\n<b>ובחודש</b> השביעי<sup data-n=\"3652\">1</sup> כו' יום תרועה<sup data-n=\"3653\">2</sup>, למה נק' זכרון בנוסח שמ\"ע<sup data-n=\"3654\">3</sup>, ע\"ש הכ' זכרון תרועה<sup data-n=\"3655\">4</sup>, גזירה דרבה<sup data-n=\"3656\">5</sup> כ' א' אומר זכרון תרועה כו' בשבת, א\"כ הול\"ל יום תרועה, אך ע\"ש זכרונות, וא\"כ הול\"ל להקדים זכרונות למל', ואחר מל' א\"ש זכרונות, וע\"פ הקבלה ר\"ה בנין המל'<sup data-n=\"3657\">6</sup>, וצלה\"ק זכור לעבדיך<sup data-n=\"3658\">7</sup>, מה הגפן הזה כו' ונשען<sup data-n=\"3659\">8</sup>, עצם האילן נמוך כו' כי האדם עץ השדה<sup data-n=\"3660\">9</sup>, וצלה\"ק ענין יפה שעה א'<sup data-n=\"3661\">10</sup>, ונת\"ל<sup data-n=\"3662\">11</sup> דע\"י התשו' המע\"ט, וצ\"ל ענין מע\"ט, כמו אבנים טובות ואבנים פשוטות, כמו\"כ מעשה דומם, עשי' לעילא<sup data-n=\"3663\">12</sup> מפני האתכפי', ויש מצות אנשים מלומדה<sup data-n=\"3664\">13</sup>, בתפילין ולא שהוא בועט ח\"ו כו', וכמו\"כ בתפילה, אפי' בצדקה לא ירע לבבך<sup data-n=\"3665\">14</sup>, וע\"ז נא' כי פנה אלי עורף<sup data-n=\"3666\">15</sup> כו' ל\"מ<sup data-n=\"3667\">16</sup> בעסקו במו\"מ, אף שהוא ג\"כ עבודה<sup data-n=\"3668\">17</sup>",[["3652","1","<b>ובחודש השביעי</b>: רשימת ראשי פרקים מכ\"ק אדמו\"ר מהורש\"ב ממאמר הח' מהמשך יונתי ד\"ה ויובן ענין הטוב — (פרקים כא-כב), שנדפס לעיל בחלק המאמרים. וש\"נ.\nהראשי פרקים נמצא לפנינו — לע\"ע — רק בחלקו והם על פכ\"ד (שנאמר במוצאי ר\"ה). ופכ\"א (הנאמר בר\"ה).\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה ש”נכתב בשנת תרמ\"ב כפי ששמעתי מר\"ן מוויליז\" נדפסה לאח\"ז."],["3653","2","<b>ובחודש השביעי כו' יום תרועה</b>: פינחס כט, א."],["3654","3","<b>בנוסח שמ\"ע</b>: ראה גם לעיל (בחלק המאמרים) בההמשך כאן הערה 619."],["3655","4","<b>זכרון תרועה</b>: אמור כג, כד. ראה שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ב, ס\"ט. סט\"ו."],["3656","5","<b>גזירה דרבה</b>: ר\"ה כט, ב."],["3657","6","<b>ר\"ה בנין המל'</b>: פרע\"ח שער ר\"ה שכ\"ד, פ\"א ואילך. שער הכוונות שם. ראה גם בהנחה הבאה הערה 10."],["3658","7","<b>זכור לעבדיך</b>: עקב ט, כז."],["3659","8","<b>מה הגפן. . ונשען</b>: ראה שמו\"ר רפמ\"ד."],["3660","9","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["3661","10","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז."],["3662","11","<b>ונת\"ל</b>: ראה לעיל הנחה ד\"ה יפה שעה אחת הב' בסופה."],["3663","12","<b>עשי' לעילא</b>: ראה זהר בהר קח, ב. ביאוה\"ז בהר פב, סע\"ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעא ואילך. סה\"מ תרע\"ח ע' שצו ואילך."],["3664","13","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' כו' נביאים וכתובים הערה 12."],["3665","14","<b>לא ירע לבבך</b>: פ' ראה טו, י."],["3666","15","<b>כי פנה אלי עורף</b>: ירמי' ב, כז [ושם: פנו — אבל כ\"ה גם לעיל בהנחה ד\"ה אני לדודי הב' ובהערה 138]."],["3667","16","<b>ל\"מ</b>: לא מיבעי."],["3668","17","<b>עבודה</b>: ע\"כ נמצא לע\"ע. ראה המשך הענין בהנחה הבאה. לעיל (בחלק המאמרים) בההמשך כאן."]]],[2000480377,"<h3>ובחודש השביעי הב' (נכתב תרמ\"ב כפי ששמעתי מר\"ן מוויליז)</h3>\n<b></b><b>ר\"ה התרמ\"א\n(נכתב תרמ\"ב כפי ששמעתי מר\"ן מוויליז)</b>\nר\"ה\n<b>ובחודש</b> השביעי<sup data-n=\"3669\">1</sup> באחד לחודש מקרא קודש יהי' לכם יום תרועה<sup data-n=\"3670\">2</sup>, וצ\"ל הלא כאן נק' יום תרועה ולמה בנוסח התפלה נק' יום זכרון, ולכאו' י\"ל שהוא מפני שכ' זכרון תרועה<sup data-n=\"3671\">3</sup>, אך א\"א לומר כן דהרי מה שאינו תוקעין בשבת הוא משום גזירה דרבה<sup data-n=\"3672\">4</sup> שמא יוליכנו ברה\"ר אבל לולי זאת הי' תוקעין בשבת ג\"כ, ועוד דאי' במדר'<sup data-n=\"3673\">5</sup> כתוב א' אומר יום תרועה וכ' א' או' זכרון תרועה כאן בשבת וכאן בחול א\"כ בחול נק' יום תרועה ולמה או' גם בנוסח התפילה דחול יום הזכרון, והענין שהוא ע\"ש זכרונות דאי' במד' אמרו לפני מלכיות<sup data-n=\"3674\">6</sup> כדי שתמליכוני עליכם זכרונות כדי שיעלה זכרוניכם לפני לטובה וע\"ש<sup data-n=\"3675\">7</sup> זה נק' יום הזכרון, אך צ\"ל לבד מה שצ\"ל מה שייך זכרון למעלה והלא אין שכחה לפני כסא כבודך<sup data-n=\"3676\">8</sup> אך זה מבואר במ\"א<sup data-n=\"3677\">9</sup> ומתורץ שם, אך צ\"ל שהיו צריכים לומר תחילה זכרונות ואח\"כ מלכיות וגם במדר' הי' צ\"ל תחילה אמרו לפני זכרונות ואח\"כ מלכיות, וגם צ\"ל מה שייך זכרונות לאחר מלכיות שזה שייך קודם מלכיות לזכור שיהי' מלך אבל לאחר שנעשה מלך ה\"ה מלך על עם ומה שייך לזכור אח\"כ, והקבלה דר\"ה הוא בנין המל'<sup data-n=\"3678\">10</sup> דמל' נאצל נקודה<sup data-n=\"3679\">11</sup> חדא וצריכים להמשיך ט\"ס במל' [והוא ע\"י ט' פסוקי מלכיות<sup data-n=\"3680\">12</sup> ] ותחילה צ\"ל נסירה<sup data-n=\"3681\">13</sup> ואח\"כ בנין המל', וא\"כ צריכים לקרותו יום תרועה או יום מלוכה, ולמה נק' יום הזכרון.",[["3669","1","<b>ובחודש השביעי</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הח' מהמשך יונתי ד\"ה ויובן ענין הטוב — (פרקים כא<sup data-n=\"e277\">א</sup>-כב), שנדפס לעיל בחלק המאמרים. וש\"נ. בהנחה זו נכלל גם פכ\"ד מההמשך.\nראשי פרקים ממאמר זה נדפס לפנ\"ז.\nראה גם לעיל ההנחה ד\"ה יפה שעה אחת הג' מש\"פ נצבים שגם היא נרשמה בשנת תרמ\"ב ע\"פ ר\"ן מוויליז.\nכנראה שמאמר זה נזכר לקמן בהנחה ד\"ה כנשר יעיר קנו על יד הערה 54 עיין שם."],["3670","2","<b>ובחודש השביעי. . יום תרועה</b>: פינחס כט, א [בדילוג]."],["3671","3","<b>זכרון תרועה</b>: אמור כג, כד."],["3672","4","<b>שאינו תוקעין בשבת. . גזירה דרבה</b>: ר\"ה כט, ב."],["3673","5","<b>במדר'</b>: ראה ויק\"ר פכ\"ט, יב. לעיל (בחלק המאמרים) בההמשך כאן הערה 623."],["3674","6","<b>במד' אמרו לפני מלכיות</b>: וכ\"ה בסמוך בפנים. ראה ר\"ה טז, סע\"א. לד, ב."],["3675","7","<b>וע\"ש</b>: כנראה שכצ\"ל (תיבה זו איננה ברורה)."],["3676","8","<b>אין שכחה לפני כסא כבודך</b>: ברכת זכרונות. ברכות לב, ב."],["3677","9","<b>מבואר במ\"א</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380897\" data-slug=\"likkutei-torah\" data-id=\"4001380897\">לקו\"ת נצבים מד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380953\" data-slug=\"likkutei-torah\" data-id=\"4001380953\">ר\"ה נח, ג</a>. סידור תפלת ר\"ה רלח, ד. מאמרי אדה\"ז אתהלך לאזניא ע' רד."],["3678","10","<b>דר\"ה הוא בנין המל'</b>: פרע\"ח שער ר\"ה שכ\"ד, פ\"א ואילך. שער הכוונות שם. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380924\" data-slug=\"likkutei-torah\" data-id=\"4001380924\">לקו\"ת נצבים נא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380944\" data-slug=\"likkutei-torah\" data-id=\"4001380944\">ר\"ה נו, ב</a> ואילך. סה\"מ תרכ\"ט ע' שמא ואילך. וש\"נ. תרל\"ח ס\"ע שעג ואילך. סה\"מ מלוקט ב' ע' קה ואילך. סה\"מ מלוקט ה' ע' ד. מאמר ד\"ה אתם נצבים תשכ\"ט."],["3679","11","<b>דמל' נאצל נקודה</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380121\" data-slug=\"likkutei-torah\" data-id=\"4001380121\">לקו\"ת צו יא, ב</a>."],["3680","12","<b>ט\"ס. . ט' פסוקי מלכיות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380945\" data-slug=\"likkutei-torah\" data-id=\"4001380945\">לקו\"ת ר\"ה נו, ג</a> ואילך."],["3681","13","<b>נסירה</b>: ראה סה\"מ תש\"ט ע' 217 בהערה.\n\n<b>א</b>  חלק מפרק כא נכנס בהנחה שלפנ\"ז."]]],[2000480378,"<b>ולהבין</b> זה הנה כתי' זכור לעבדיך לאברהם ליצחק וליעקב<sup data-n=\"3682\">14</sup> ואי' במדר'<sup data-n=\"3683\">15</sup> גפן ממצרים תסיע<sup data-n=\"3684\">16</sup> מה הגפן הזה חי ונשענת על עצים מתים, כך ישראל חיים וקיימים ונשענים על המתים הוי זכור לעבדיך כו', דגפן חלוק משארי אילנות שהוא נמוך וענפיו דקים וגידול הענבים הם על הענפים וצריכים לסמוך הענפים שלא ישברו ולא יצמחו הענבים, והגפן עצמו חי שמקבל חיות מכח הצומח שבארץ וכשכורתין העץ נפסק ממנה החיות, וזהו שהוא עצמו חי ונשענת על עצים מתים, והגם שכל האילנות צריכים סמיכה, א' שאינו מצוי ועוד שאינו מוכרח כ\"כ, אבל הגפן מוכרח להסמיכה וא\"ל יבטל הצמיחה, כך בצאת ישראל ממצרים וכשצריך משה לעורר עליהם רחמים הזכיר את האבות אף שכבר מתו והם חיים, אך זהו כמשל הגפן כו', ולהבין זה צ\"ל מה שנת\"ל<sup data-n=\"3685\">17</sup> יפה שעה א'<sup data-n=\"3686\">18</sup> בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב ונת\"ל תשובה הוא השבת הנפש והרוח תשוב אל אלקים<sup data-n=\"3687\">19</sup>, עין לא ראתה<sup data-n=\"3688\">20</sup> אלקי' זולתך, וזהו הוראה שהמעשים הם מעשים טובים דאל\"כ לא הי' אפ\"ל התשובה.\n<b>וביאור</b> הענין צ\"ל מהו\"ע מע\"ט, הנה יש אבנים טובים והוא כשהכוכבים מאירים על אותו מקום נעשים אבנים טובים ומאירים<sup data-n=\"3689\">21</sup>, ומ\"מ לא יצא מכלל דומם והוא נמוך מהפחות שבצומח שאינו יוצא מכלל צומח, והאבן טוב אף שהוא מאיר ומבהיק מ\"מ לא יצא מכלל דומם ומה שהוא יקר כ\"כ הוא מפני שאינו מצוי וגם צריכים ריבוי יגיעה להשיגם, והוא קרוב למס\"נ וגם שזה דבר חידוש אשר דומם יאיר ויבהיק כ\"כ, וכמו\"כ יובן במעהמ\"צ דמעשה הוא כח היותר אחרון בנפש, דיש עשר כחות בנפש<sup data-n=\"3690\">22</sup> ג' שכלי' וז' מדות וג' לבושים מחדו\"מ<sup data-n=\"3691\">23</sup> הרי מעשה הוא הכח היותר אחרון בנפש, ומ\"מ יש מעלה במעשה דעשי' לעילא<sup data-n=\"3692\">24</sup> דמעשה הוא ל' כפי'<sup data-n=\"3693\">25</sup> והכרח כמו גט מעושה<sup data-n=\"3694\">26</sup>, מעשין על הצדקה<sup data-n=\"3695\">27</sup>, ויש מעשים טובים ומעשים שאינם טובים, וצ\"ל תחילה מה נק' מעשים שאינם טובים, הנה כשעושה מצות בקרירות דרך מצות אנשים מלומדה<sup data-n=\"3696\">28</sup> כמו מצות תפילין הוא עושה בקרירות ע\"צ ההרגל וכן",[["3682","14","<b>זכור לעבדיך. . וליעקב</b>: עקב ט, כז."],["3683","15","<b>במדר'</b>: ראה שמו\"ר רפמ\"ד."],["3684","16","<b>גפן ממצרים תסיע</b>: תהלים פ, ט."],["3685","17","<b>שנת\"ל</b>: ראה לעיל הנחה ד\"ה יפה שעה אחת הג'."],["3686","18","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז."],["3687","19","<b>והרוח תשוב אל אלקים</b>: נסמן לקמן בהערה 51."],["3688","20","<b>עין לא ראתה</b>: ישעי' סד, ג."],["3689","21","<b>כשהכוכבים מאירים. . אבנים טובים ומאירים</b>: ראה זהר תרומה קעב, רע\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380826\" data-slug=\"likkutei-torah\" data-id=\"4001380826\">לקו\"ת פ' ראה כז, ג</a>. סה\"מ תרל\"ח ע' נז (ובהנסמן שם) וע' שעו."],["3690","22","<b>עשר כחות בנפש</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370089\" data-slug=\"torah-or\" data-id=\"3901370089\">תו\"א תולדות יט, א</a>. תניא פ\"ג."],["3691","23","<b>וג' לבושים מחדו\"מ</b>: <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>."],["3692","24","<b>דעשי' לעילא</b>: ראה זהר בהר קח, ב. ביאוה\"ז בהר פב, סע\"ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעא ואילך. סה\"מ תרע\"ח ע' שצו ואילך."],["3693","25","<b>דמעשה הוא ל' כפי'</b>: ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת הב' ובהערה 14."],["3694","26","<b>גט מעושה</b>: גיטין פח, ב (במשנה)."],["3695","27","<b>מעשין על הצדקה</b>: ב\"י לטור יו\"ד סרמ\"ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121246\" data-slug=\"likkutei-sichot\" data-id=\"1300121246\">לקו\"ש</a> ל\"ג בעומר כרך יב ע' 238 ובהנסמן שם."],["3696","28","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>). לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אי' כו' נביאים וכתובים הערה 12."]]],[2000480379,"כשמניח טו\"ת ומתפלל הוא ע\"צ ההרגל לבד שמורגל בכך, ולכן כשמפסיק ה\"ה שוכח וֲו ער ה„לט והוא מפני שאינו חושב מה שהוא אומר נ ר עס ז גט זיך „ליין מצד ההרגל ולכן הוא שוכח כשמפסיק והגם שאינו מפני רוע לבב ואינו פורק עול ולא מפני שאינו מאמין ח\"ו אבל מ\"מ אינו מעשים טובים, ואפי' מצות צדקה שהוא בהרגש מ\"מ אפשר שיהי' בזה רוע לבב ג\"כ דכתי' אל ירע לבבך בתתך לו<sup data-n=\"3697\">29</sup> מכלל דשייך רוע לבב, וגם כשנותן צדקה מפני שחביריו נמנים לדבר מצוה<sup data-n=\"3698\">30</sup> והוא אינו נמנה עמהם עס ‘„סט אים „זוי והגם שהוא עשי' וא\"א להכחיש שאינו מצוה כלל אבל מ\"מ אינם מעשים טובים, וזהו מ\"ש כי פנה אלי עורף<sup data-n=\"3699\">31</sup> ולא פנים שאפי' כשפנה אלי הוא רק עורף ולא פנים, לא מבעי כשעוסק במו\"מ הרי אינו מקושר, ובאמת א\"ז כמו שהעולם סוברים שא\"א להיות מקושר לאלקות בעסקו במו\"מ דבאמת ה\"ז ג\"כ עבודה, דהנה אמרז\"ל כל הפורק ממנו עול תורה<sup data-n=\"3700\">32</sup> נותנין עליו עול ד\"א ולכאו' צ\"ל והלא אמרז\"ל יפה ת\"ת עם ד\"א<sup data-n=\"3701\">33</sup> שיגיעת שניהם משכחת עון, א\"כ הרי צריכים ד\"א ג\"כ, והענין דכאן אמר ד\"א וכאן א' עו\"ל ד\"א שהוא טרוד ומוטרד ומבולבל תמיד ואינו מרויח כלום בל\"א ער מ„כט ג רניסט, ובאמת יש עבודה במו\"מ ג\"כ כשעוסק במו\"מ להרויח כדי שיוכל ללמוד ולהתפלל ולפרנס בו\"ב<sup data-n=\"3702\">34</sup> שעז\"נ עושה צדקות בכ\"ע<sup data-n=\"3703\">35</sup> ואמרז\"ל זה הזן ומפרנס בו\"ב<sup data-n=\"3704\">36</sup>, וזהו דכתי' ואכלת את כל העמים<sup data-n=\"3705\">37</sup> ולכאו' והלא אינם בני אכילה וגם אסורים באכילה<sup data-n=\"3706\">38</sup>, אלא הפי' הוא שמברר בירורים בעסקו במו\"מ אף שהוא בירור היותר נמוך אבל שכרו למעלה יותר, אך ע\"ז אמרו ראיתי בני עלי' והמה מועטים<sup data-n=\"3707\">39</sup>, אבל אפי' כשבא לבהכנ\"ס להתפלל הוא ממהר ונחפז בל\"א ער האיילט און ח„פט ואינו ממתין להתפלל עם מנין ואפי' כשמתפלל במנין ה\"ה ממהר את אחרים ג\"כ, וכ\"ז מפני שצריך לרוץ למסחרו ער ד„רף פ„ר ח„פון און פ„ר לייפון, ובאמת ה\"ז שקר ותהו והבל מיא פ„ר ח„פט ג רניסט און מי פ„ר לייפט ג רניסט, הגם שא\"ז מצד רוע לבב ומצד פר\"ע ח\"ו וכמארז\"ל במדר' תילים",[["3697","29","<b>אל ירע לבבך בתתך לו</b>: ראה גם לעיל (בחלק המאמרים) בההמשך כאן הערה 511."],["3698","30","<b>שחביריו נמנים לדבר מצוה</b>: ראה ברכות כו, סע\"א."],["3699","31","<b>כי פנה אלי עורף</b>: ירמי' ב, כז [ושם: פנו]. ראה גם לעיל הנחה ד\"ה אני לדודי הב' ובהערה 138."],["3700","32","<b>כל הפורק ממנו עול תורה</b>: ראה אבות פ\"ג, מ\"ה. ראה גם מאמרי אדה\"א נ\"ך ס\"ע תכח ואילך."],["3701","33","<b>יפה ת\"ת עם ד\"א</b>: אבות פ\"ב, מ\"ב. ראה גם מאמרי אדה\"א דברים ח\"ד<sup data-n=\"e278\">ב</sup> ע' א'רכה<sup data-n=\"e279\">ג</sup>. וש\"נ. תו\"ח שמות ח\"א ד, ב. סה\"מ תרל\"ח ע' קסד. וש\"נ."],["3702","34","<b>בו\"ב</b>: בניו ובנותיו."],["3703","35","<b>עושה צדקות בכ\"ע</b>: תהלים קו, ג [ושם: צדקה]."],["3704","36","<b>זה הזן ומפרנס בו\"ב</b>: ראה כתובות נ, סע\"א."],["3705","37","<b>ואכלת את כל העמים</b>: עקב ז, טז. ראה גם סה\"מ תרכ\"ט ע' סה. ע' תי. תרל\"ב ח\"א ע' קנ."],["3706","38","<b>העמים. . אסורים באכילה</b>: ראה רמב\"ם הל' מאכלות אסורות פ\"ב, ה\"ג (ובמפרשיו שם). פ\"ג, ה\"ב."],["3707","39","<b>ראיתי בני עלי' והמה מועטים</b>: ראה סוכה מה, ב.\n\n<b>ב</b>  וכן צ\"ל בהערה שנדפסה בסה\"מ תרל\"ח (שהובא בפנים ההערה).\n\n<b>ג</b>  וכן צ\"ל במאמרי אדה\"א נ\"ך ע' תכט בהערה ד\"ה טוב."]]],[2000480380,"אמרה כנס\"י להקב\"ה רצוננו לעשות רצונך אבל טרדת הפרנסה מעכב<sup data-n=\"3708\">40</sup>, וגם כאו\"א צריך הכרחיות שלו ומצד חלישותו צריך יותר מה שלזולתו נראה שהוא מותרות הכרח הוא לו, אבל מ\"מ הי' די מיעוט זמן ע\"ז וכמ\"ש וברכך הוי' אלקיך בכל אשר תעשה<sup data-n=\"3709\">41</sup> כי הוא הנותן לך כח לעשות חיל<sup data-n=\"3710\">42</sup>, וזהו נק' מעשים לא טובים שא\"א להכחיש שאין זה מעשה כלל אבל הם מעשים לא טובים.\n<b>ומעשים</b> טובים הוא כשעושה המצוה בכוונה הא' מ\"ש בשו\"ע לכוון לשעבד הלב והמוח<sup data-n=\"3711\">43</sup>, והב' כמ\"ש בכהאריז\"ל שע\"י תפילין ד' בתים ממשיכים ד' מוחין<sup data-n=\"3712\">44</sup>, ועוד יש קבע\"ו שבמעשה המצוה וכמו ההפרש בין השר שעושה ציווי המלך ה\"ה עושה ע\"פ טו\"ד כמו שמחייב שכלו ועבד כשעושה ציוי המלך ה\"ה בלי שום טו\"ד רק מפני ציוי המלך וכמו\"כ במעהמ\"צ צ\"ל קבע\"ו ובאמת קבע\"ו הוא יותר טוב מכוונות המצוה, דכוונת המצות הוא בח\"ס דא\"א וקבע\"ו הוא בגולגלתא דא\"א<sup data-n=\"3713\">45</sup>, וצ\"ל שניהם תחילה צ\"ל קבע\"ו כמו כשמניח תפילין תחילה צ\"ל בדרך קבע\"ו מפני שכך צוה הקב\"ה ואח\"כ צריך לכוון שע\"י ד' בתים ממשיכים ד' מוחין, וכן בנתינת צדקה צ\"ל בקבע\"ו דכתיב פתוח תפתח ידך<sup data-n=\"3714\">46</sup> כו' ואח\"כ צריך לכוון שע\"י נתינת הצדקה נעשה היד מרכבה<sup data-n=\"3715\">47</sup> לחסד שלמעלה שבלי גבול, ואז נק' מעשים טובים ומאירים<sup data-n=\"3716\">48</sup> כמו האבנים טובים הוא מפני שהכוכבים שהם ברקיע תמינאה<sup data-n=\"3717\">49</sup> מאירים על מקום ידועה ועושים האבנים טובים ומאירים כמו\"כ כשעושה המצות ע\"ד הנ\"ל אז הם מעשים טובים שהם טובים כ\"כ עד שא\"א להיות טובים יותר מזה, ופי' טובים בל\"א אז ער בריינגט דרינען „ריין דעם העכסטן פ„ל וו ס עס קען נ ר זיין זהו מעשים טובים, וזהו יפה שעה א' בתשובה ומע\"ט פי' שעה א' א ין קער<sup data-n=\"3718\">50</sup> וזהו\"ע התשובה להשיב הנפש אל שרשו וכמ\"ש והרוח תשוב אל אלקים אשר נתנו<sup data-n=\"3719\">51</sup>, עין לא",[["3708","40","<b>במדרש תילים. . רצוננו. . טרדת הפרנסה מעכב</b>: אולי הכוונה שם א, יז."],["3709","41","<b>וברכך. . בכל אשר תעשה</b>: פ' ראה טו, יח. ראה גם מאמר ד\"ה זה במאמרי אדה\"ז תקס\"ה ח\"ב ע' תרמח ואילך."],["3710","42","<b>כי הוא הנותן. . חיל</b>: עקב ח, יח."],["3711","43","<b>לשעבד הלב והמוח</b>: ראה שו\"ע אדה\"ז הל' תפילין סכ\"ה, סי\"א. סידור שם [נדפס גם בהוספות לשו\"ע מהדורת קה\"ת שם]."],["3712","44","<b>שע\"י תפילין. . ד' מוחין</b>: ראה זהר ואתחנן רסב, א. פע\"ח שער התפילין שער ד, פ\"א ואילך. סידור שער התפילין ז, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670598\" data-slug=\"torat-chaim\" data-id=\"2300670598\">תו\"ח נח עח, ד</a> הערה 34."],["3713","45","<b>במעהמ\"צ צ\"ל קבע\"ו. . בגולגלתא דא\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380468\" data-slug=\"likkutei-torah\" data-id=\"4001380468\">לקו\"ת שלח לט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">מ, א</a>."],["3714","46","<b>פתוח תפתח ידך</b>: פ' ראה טו, ח [ושם: את ידך]."],["3715","47","<b>נתינת הצדקה נעשה היד מרכבה</b>: ראה גם תניא פכ\"ג<sup data-n=\"e280\">ד</sup>. מאמרי אדה\"ז תקס\"ה ח\"א ע' רלז."],["3716","48","<b>מעשים טובים ומאירים</b>: ראה גם לעיל (בחלק המאמרים) המשך יונתי כאן הערה 517."],["3717","49","<b>שהכוכבים שהם ברקיע תמינאה</b>: ראה זהר ויצא קסב, ב. רמב\"ם רפ\"ג מהל' יסוה\"ת. חגיגה יב, ב. פרדס שער סדר עמידתן ש\"ו, פ\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380826\" data-slug=\"likkutei-torah\" data-id=\"4001380826\">לקו\"ת פ' ראה כז, ג</a>. שיחת כ' כסלו תשי\"ז סל\"א."],["3718","50","<b>פי' שעה א' אין קער</b>: ראה גם לעיל הנחה ד\"ה יפה שעה אחת (הב' — רשימת ראשי פרקים) ובהערה 11."],["3719","51","<b>והרוח תשוב אל אלקים אשר נתנו</b>: קהלת יב ז [ושם: האלקים. . נתנה — ראה גם לעיל הנחה ד\"ה יפה שעה אחת הג' ובהערה 25].\n\n<b>ד</b>  ראה גם ת\"ז (בהקדמה יז,\nחסד דרועא ימינא. של\"ה בית ישראל יד, רע\"א."]]],[2000480381,"ראתה אלקים זולתך ונותן בעין יפה נותן<sup data-n=\"3720\">52</sup> והוא בחי' עינא פקיחא דלא נאים<sup data-n=\"3721\">53</sup>, ותשובה זו אפ\"ל דוקא כשהמעשים הם מעשים טובים ומאירים, וזהו מי יעלה בהר ה'<sup data-n=\"3722\">54</sup> נקי כפים ובר לבב<sup data-n=\"3723\">55</sup> וחשיב כאן הרבה וא\"ז עצם המצות רק מה שפעלו בו המצות ועי\"ז עולה הנשמה לשרשה ומקורה.\n<b>ולהבין</b> ענין התשובה, הנה כתי' ויפח באפיו נשמת חיים<sup data-n=\"3724\">56</sup> ואמרז\"ל בעוה\"ז בנפיחה ולכן מת, ובעוה\"ב בנתינה<sup data-n=\"3725\">57</sup> ולכן וחי לעולם<sup data-n=\"3726\">58</sup> וכמ\"ש ונתתי רוחי בהם וחייתם<sup data-n=\"3727\">59</sup>, וצ\"ל הלא עכשיו ג\"כ בנתינה וכמ\"ש אלקי נשמה שנתת בי<sup data-n=\"3728\">60</sup>, והענין דהעולם על מילואו נברא<sup data-n=\"3729\">61</sup> ואח\"כ בחטא עה\"ד נחסרו ה' דברים<sup data-n=\"3730\">62</sup>, ועוד דלא כל הנשמה מתלבשת בגוף<sup data-n=\"3731\">63</sup> כ\"א הארה ומקצת מהנשמה ועיקר הנשמה נשאר למעלה דמה מלאך בשליש עולם עומד<sup data-n=\"3732\">64</sup> כ\"ש נשמה שלמעלה ממלאך הגוף קטן מהכיל אותה, ובאמת א\"ז טענה כלל דגשמיות לגבי רוחניות כמו שהקטן אינו כלי כמו\"כ גדול ג\"כ אינו כלי לזה, אך האמת כן הוא וכמ\"ש ונוזלים מלבנון<sup data-n=\"3733\">65</sup> שמשרש הנשמה נוזל בהנשמה שבגוף, וכמ\"ש גבי לך לך<sup data-n=\"3734\">66</sup> פי' שיבא לשרש הנשמה, וכתי' לכי לך<sup data-n=\"3735\">67</sup> שיבא לשרש הנשמה, ומה שמתלבשת בגוף הוא רק הארה מהנשמה, לכן יש קצבה לשנות האדם ימי שנותינו בהם<sup data-n=\"3736\">68</sup> שבעים שנה ואם בגבורות שמונים שנה לפום גמלא שיחנא<sup data-n=\"3737\">69</sup>, והוא לפ\"ע הבירורים שצריך לברר וזהו ויפח כמו האדם כשנופח מאיזה",[["3720","52","<b>ונותן בעין יפה נותן</b>: ראה ב\"ב סה, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381012\" data-slug=\"likkutei-torah\" data-id=\"4001381012\">לקו\"ת האזינו עב, ב</a> ובהנסמן במ\"מ לשם."],["3721","53","<b>עינא פקיחא דלא נעים</b>: ראה זהר אד\"ר נשא קכט, סע\"ב. הנסמן במאמרי אדה\"א נ\"ך ע' תג."],["3722","54","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["3723","55","<b>נקי כפים ובר לבב</b>: תהלים שם, ד."],["3724","56","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["3725","57","<b>בעוה\"ז בנפיחה. . ובעוה\"ב בנתינה</b>: ב\"ר פי\"ד, ח. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381012\" data-slug=\"likkutei-torah\" data-id=\"4001381012\">לקו\"ת האזינו עב, ב</a>. המשך תער\"ב ח\"ב ע' תשעח."],["3726","58","<b>וחי לעולם</b>: לשון הכתוב בראשית ג, כב."],["3727","59","<b>ונתתי רוחי בהם וחייתם</b>: וכ\"ה בסמוך בפנים — יחזקאל לז, יד [ושם: בכם — וכ\"ה לקמן בסיום ההנחה]."],["3728","60","<b>אלקי נשמה שנתת בי</b>: ברכת אלקי נשמה (מברכות ס, ב)."],["3729","61","<b>דהעולם על מילואו נברא</b>: ראה ב\"ר פי\"ד, ז. וראה שם פי\"ב, ו. פי\"ג, ג (וביפ\"ת שם). ראה גם תו\"ח ח\"ש קלד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251014\" data-slug=\"likkutei-sichot\" data-id=\"1300251014\">לקו\"ש בראשית כרך כה ע' 14</a> ואילך."],["3730","62","<b>ואח\"כ בחטא עה\"ד נחסרו ה' דברים</b>: ראה גם לעיל הנחה ד\"ה גדולה תשובה ובהערה 76־ (בחלק המאמרים) מאמר ד\"ה ואמנם יש עוד בחי' חולה ובהערה 84: וא\"ו דברים."],["3731","63","<b>דלא כל הנשמה מתלבשת בגוף</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו ובהערה 595."],["3732","64","<b>דמה מלאך בשליש עולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 44."],["3733","65","<b>ונוזלים מלבנון</b>: שה\"ש ד, טו [ושם: מן לבנון<sup data-n=\"e281\">ה</sup>]. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, א</a> ואילך."],["3734","66","<b>לך לך</b>: לך יב, א. ראה גם אוה\"ת לך כרך ג ע' תרפא-ב. סה\"מ תרכ\"ז ע' י. תר\"ל ע' ט."],["3735","67","<b>לכי לך</b>: שה\"ש ב, י. יג [ושם: ולכי]. ראה גם אוה\"ת שם."],["3736","68","<b>ימי שנותינו בהם</b>: תהלים צ, י. ראה גם לעיל (בחלק המאמרים) המשך מצה זו ספכ\"ט (ובהנסמן שם)."],["3737","69","<b>לפום גמלא שיחנא</b>: כתובות סז, א. ראה גם ס' המצות להצ\"צ קס, סע\"ב.\n\n<b>ה</b>  אבל כ\"ה גם לקמן בהנחה ד\"ה עשה צדקה על יד הערה 14."]]],[2000480382,"דבר אינו נופח רק הארה ולא העצם<sup data-n=\"3738\">70</sup>, והגם שגם עכשיו יש בחי' נתינה ה\"ה בהעלם ולכן ג' שמתו בעטיו של נחש<sup data-n=\"3739\">71</sup> הוא מפני שהוא הארה בעלמא ובחי' נתינה הוא בהעלם, אבל לע\"ל לאחר שית אלפי שנין<sup data-n=\"3740\">72</sup> שאז יהי' גמר הבירורים יהי' בנתינה וכמ\"ש ונתתי רוחי בהם וחייתם חיים וקיימים לעולם ואז יהי' עיקר קיום המצות וכמ\"ש ושם נעשה לפניך כמצות רצונך<sup data-n=\"3741\">73</sup>, וזהו והרוח תשוב אל אלקי' אשר נתנה פי' לשרש ומקור הנשמה שהוא בבחי' נתינה ולע\"ל יאיר זה בגוף.\n<b>והנה</b> להבין זמן תשובה הנ\"ל צ\"ל תחילה ענין ג' ק\"ש, ק\"ש שחרית וערבית שהם דאורייתא<sup data-n=\"3742\">74</sup>, וק\"ש שעהמ\"ט שהיא מדרבנן<sup data-n=\"3743\">75</sup> וצ\"ל מהו\"ע ק\"ש שעהמ\"ט. והענין דק\"ש שחרית וערבית הם מס\"נ בכח וק\"ש שעהמ\"ט היא מס\"נ קרוב לפועל, דבעת השינה מסתלק הנשמה מהגוף ונשאר רק קיסטא דחיותא<sup data-n=\"3744\">76</sup> וזהו מס\"נ קרוב לפועל, והנה צ\"ל תחילה ענין ק\"ש שחרית וערבית, שמע ישראל כו' ה' אחד<sup data-n=\"3745\">77</sup> והוא ביטל היחידה שמקבל מקבל<sup data-n=\"3746\">79</sup> מיחיד<sup data-n=\"3747\">78</sup>, דאחד הוא ג\"כ יחיד וכמ\"ש יש אחד ואין שני לו<sup data-n=\"3748\">80</sup>, ואדרבה אחד מורה על אחדות יותר מיחיד<sup data-n=\"3749\">81</sup> דאפי' ז' רקיעים וארץ וד' רוחות העולם<sup data-n=\"3750\">82</sup> בטלים לאל\"ף א\"ס<sup data-n=\"3751\">83</sup> אלופו ש\"ע<sup data-n=\"3752\">84</sup>, וכדי שיבא לביטל זה צלה\"ק תחילה פסוד\"ז, כמו עד\"מ אדם שנכנס לכרם ה\"ה חותך את העצים היבשים כמו\"כ הו\"ע פסוד\"ז לזמר עריצים<sup data-n=\"3753\">85</sup> וביטל המלאכים ואח\"כ בברכת ק\"ש איך ששרפים אומרים קדוש ואופנים אומרים ברוך<sup data-n=\"3754\">86</sup>, ואי לזאת גם הנה\"ב יבא לאהבה ותשוקה",[["3738","70","<b>ויפח. . הארה ולא העצם</b>: ראה לעיל הערה 57. (בחלק המאמרים) בההמשך כאן רפכ\"ב."],["3739","71","<b>ג' שמתו בעטיו של נחש</b>: ראה זהר בראשית נז, ב<sup data-n=\"e282\">ו</sup>. לקוטי לוי יצחק לשם ע' כ ואילך.\nראה גם שבת נה, ב. ב\"ב יז, א [ושם: ד]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370352\" data-slug=\"torah-or\" data-id=\"3901370352\">תו\"א משפטים עט, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550637\" data-slug=\"torat-chaim\" data-id=\"2300550637\">תו\"ח משפטים ח\"ב שג, ב</a>. סהמ\"צ להצ\"צ ס\"ע עד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241132\" data-slug=\"likkutei-sichot\" data-id=\"1300241132\">לקו\"ש תצא כרך כד ע' 132</a>. מצורע כרך לז ע' 44."],["3740","72","<b>שית אלפי שנין</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["3741","73","<b>ושם נעשה לפניך כמצות רצונך</b>: מוסף ליו\"ט [בדילוג]. ראה לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הב' ובהערה 9."],["3742","74","<b>ק\"ש שחרית וערבית שהם דאורייתא</b>: ראה שו\"ע אדה\"ז ריש הל' ק\"ש."],["3743","75","<b>וק\"ש שעהמ\"ט שהיא מדרבנן</b>: ראה ברכות ד, סע\"ב. רמב\"ם הל' תפלה רפ\"ז."],["3744","76","<b>קיסטא דחיותא</b>: ראה גם (לעיל בחלק המאמרים) המשך יונתי פ\"ט הערה 225."],["3745","77","<b>שמע ישראל. . אחד</b>: ואתחנן ו, ד."],["3746","79","<b>שמקבל מקבל</b>: כ\"ה בגוכתי\"ק."],["3747","78","<b>היחידה שמקבל. . מיחיד</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. (לעיל בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי ובהערה 152."],["3748","80","<b>יש אחד ואין שני לו</b>: קהלת ד, ח [בדילוג]."],["3749","81","<b>אחד. . מיחיד</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a>. מאמרי אדה\"א בראשית ע' תק. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540489\" data-slug=\"torat-chaim\" data-id=\"2300540489\">תו\"ח שמות ח\"א מז, א</a>. וש\"נ. סה\"מ תרכ\"ז ע' קע. וש\"נ. תרכ\"ט ע' לא. וש\"נ."],["3750","82","<b>ז' רקיעים וארץ וד' רוחות העולם</b>: נסמן לעיל ח\"א (בחלק המאמרים) מאמר ד\"ה סמוכים לעד הערה 50."],["3751","83","<b>לאל\"ף א\"ס</b>: ראה זהר רע\"מ פינחס רנז, א."],["3752","84","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["3753","85","<b>פסוד\"ז לזמר עריצים</b>: ע\"פ ישעי' כה, ה. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' ובהערה 33."],["3754","86","<b>ששרפים אומרים קדוש ואופנים אומרים ברוך</b>: ראה גם לעיל ח\"א (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ג. וש\"נ.\n\n<b>ו</b>  צויין אליו בגליון הש\"ס שבת נה, ב."]]],[2000480383,"לאלקות, ולכאורה איך יהי' להנה\"ב אהבה לאלקות, אך באמת תלוי ברצון וכשירצה יבא גם הנה\"ב לאהבה לה' בל\"א „ז מיא ויל קען מען.\n<b>וזהוואהבת</b> את ה' אלקיך בכל לבבך<sup data-n=\"3755\">87</sup>, דהנה כתי' לאהבה את ה' אלקיך כי הוא חייך<sup data-n=\"3756\">88</sup> כמו האדם שאוהב חיי נפשו, ולכאו' צ\"ל את מי הוא אוהב אם נא' שאוהב את הגוף הרי הגוף הוא אבן דומם דבצאת הנפש מהגוף נשאר כאבן דומם וג\"ז אינו שייך לומר דבעת שהנפש מאיר בגוף הוא אוהב את הגוף, איך שייך שהחי יאהב את הבלתי בע\"ח, ואם נא' שאוהב את עצם הנפש, הרי עצם הנפש הוא למעלה ואינו מתלבש בגוף כ\"א הארה, ולומר שהוא אוהב את ההארה שמתלבשת בגוף ג\"כ אינו שייך, שהרי מהות ההארה לא ראה מעולם ואינו משיג מה היא דגילוי הנשמה הוא למעלה מרוה\"ק וגילוי אליהו<sup data-n=\"3757\">89</sup> ואנו רואין דמה שהאדם רואה הוא הדבר אשר יאהב ולא מה שלא ראה מעולם, אלא צ\"ל שהוא אוהב את התפשטות החיות בהגוף (כפי' שמבואר אח\"כ בהנמשל נ\"ל שצ\"ל כך שהוא אוהב את הנפש המתפשט בהגוף<sup data-n=\"3758\">90</sup> ) וכמו שאוהב את התפוח ה\"ה אוהב את מתיקות ולא עצם התפוח, וכן מה שאוהב את הנגינה אוהב את מתיקות הניגון, וכמו\"כ יובן למעלה כשיתבונן כי הוא חייך שא\"ס הוא המחי' את העולם וכמאמר בע\"מ נברא העולם<sup data-n=\"3759\">91</sup> ואתה מחי' את כולם<sup data-n=\"3760\">92</sup> א\"ת מחי' אלא מהווה<sup data-n=\"3761\">93</sup> שהוא מחי' ומהווה את כל העולמות מאין ליש, ולמה יאהב את אשר נברא, יותר טוב שיאהב את האלקות המחי' את העולם, וזהו לאהבה את אלקיך כי הוא חייך שע\"י התבוננות זו יבא גם הנה\"ב לאהוב את ה'. ובאמת כשיעמיק דעת יותר בהתבוננות יהי' לו אהבה וכליון לא\"ס עצומ\"ה, והוא כשיתבונן דכלליות השתל' העולמות הוא רק מהארה בעלמא ולכן אני ה' לא שניתי<sup data-n=\"3762\">94</sup> שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה אתה הוא קודם שנבה\"ע<sup data-n=\"3763\">95</sup> ואתה הוא לאחר שנבה\"ע בשוה, ולכאורה איך אפ\"ל שהוא בשוה והלא מתחילה לא הי' העולם ואח\"כ נבה\"ע אלא מפני שכלליות השתל' העולמות הם משם והארה בעלמא שאינו נוגע לעצמיות כלל, וזהו בהבראם בה' בראם<sup data-n=\"3764\">96</sup> אתא קלילא<sup data-n=\"3765\">97</sup> דלית בי' מששא, ואי",[["3755","87","<b>ואהבת. . בכל לבבך</b>: ואתחנן ו, ה."],["3756","88","<b>לאהבה את ה' אלקיך כי הוא חייך</b>: נצבים ל, כ."],["3757","89","<b>דגילוי הנשמה. . מרוה\"ק וגילוי אליהו</b>: ראה שע\"ק להרח\"ו ח\"ג, ש\"ה וש\"ז. לעיל הנחה ד\"ה יפה שעה אחת ובהערה 76."],["3758","90","<b>(כפי'<sup data-n=\"e283\">ז</sup>. . בהגוף)</b>: נרשם עה\"ג בצד הימין (ונסמן סימן בפנים). ואולי זהו הגהת של כ\"ק אדמו\"ר מהורש\"ב."],["3759","91","<b>בע\"מ נברא העולם</b>: אבות רפ\"ה."],["3760","92","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["3761","93","<b>א\"ת מחי' אלא מהווה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["3762","94","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל ח\"א (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה ובהערה 82."],["3763","95","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["3764","96","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["3765","97","<b>בה'. . אתא קלילא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381022\" data-slug=\"likkutei-torah\" data-id=\"4001381022\">לקו\"ת האזינו עד, ד</a>: והה' הוא אתא קלילא דלית בי' מששא כמבואר באקדמות. תו\"ח ח\"ש קכא, ג ובהערה 48.\n\n<b>ז</b>  כ\"ה בגוכתי\"ק."]]]]});
